import re

def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    cleaned = gstin.strip().upper()
    if len(cleaned) != 15:
        return None

    pattern = r"^([0-9]{2})([A-Z]{5}[0-9]{4}[A-Z])([1-9A-Z])(Z)([0-9A-Z])$"
    match = re.match(pattern, cleaned)
    if not match:
        return None

    state_code, pan, entity_number, fixed_z, check_char = match.groups()

    # Validate state code: 01 to 38, or 97
    try:
        sc_int = int(state_code)
    except ValueError:
        return None

    if not ((1 <= sc_int <= 38) or sc_int == 97):
        return None

    # Calculate check character
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    char_map = {ch: i for i, ch in enumerate(alphabet)}

    total_sum = 0
    for i in range(14):
        val = char_map[cleaned[i]]
        factor = 1 if i % 2 == 0 else 2
        product = val * factor
        total_sum += (product // 36) + (product % 36)

    expected_check = alphabet[(36 - (total_sum % 36)) % 36]

    if check_char != expected_check:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
