def inr_words_en(n: int) -> str:
    """
    Converts a non-negative integer (0 <= n < 1,000,000,000) into English words
    using the Indian numbering system (crore, lakh, thousand).
    """
    if not isinstance(n, int) or n < 0 or n >= 1_000_000_000:
        raise ValueError("Input must be an integer in the range 0 <= n < 1,000,000,000.")

    if n == 0:
        return "zero"

    units = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def two_digits_to_words(num: int) -> str:
        if num < 20:
            return units[num]
        t, u = divmod(num, 10)
        return tens[t] + (f"-{units[u]}" if u else "")

    def three_digits_to_words(num: int) -> str:
        h, rem = divmod(num, 100)
        parts = []
        if h:
            parts.append(f"{units[h]} hundred")
        if rem:
            parts.append(two_digits_to_words(rem))
        return " ".join(parts)

    crore, remainder = divmod(n, 10_000_000)
    lakh, remainder = divmod(remainder, 100_000)
    thousand, remainder = divmod(remainder, 1_000)

    result = []
    if crore:
        result.append(f"{two_digits_to_words(crore)} crore")
    if lakh:
        result.append(f"{two_digits_to_words(lakh)} lakh")
    if thousand:
        result.append(f"{two_digits_to_words(thousand)} thousand")
    if remainder:
        result.append(three_digits_to_words(remainder))

    return " ".join(result)
