        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def two_digit_words(num: int) -> str:
        if num < 20:
            return ones[num]
        ten_part = tens[num // 10]
        unit_part = ones[num % 10]
        if unit_part:
            return f"{ten_part}-{unit_part}"
        return ten_part

    def three_digit_words(num: int) -> str:
        parts = []
        hundreds = num // 100
        remainder = num % 100
        if hundreds > 0:
            parts.append(f"{ones[hundreds]} hundred")
        if remainder > 0:
            parts.append(two_digit_words(remainder))
        return " ".join(parts)

    crore = n // 10_000_000
    remainder = n % 10_000_000

    lakh = remainder // 100_000
    remainder = remainder % 100_000

    thousand = remainder // 1_000
    remainder = remainder % 1_000

    result = []

    if crore > 0:
        result.append(f"{two_digit_words(crore)} crore")
    if lakh > 0:
        result.append(f"{two_digit_words(lakh)} lakh")
    if thousand > 0:
        result.append(f"{two_digit_words(thousand)} thousand")
    if remainder > 0:
        result.append(three_digit_words(remainder))

    return " ".join(result)
