    if not isinstance(n, int) or n < 0 or n >= 1_000_000_000:
        raise ValueError("Input must be a non-negative integer less than 1,000,000,000")

    if n == 0:
        return "zero"

    ones = {
        1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
        6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
        11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen",
        15: "fifteen", 16: "sixteen", 17: "seventeen", 18: "eighteen",
        19: "nineteen"
    }

    tens = {
        2: "twenty", 3: "thirty", 4: "forty", 5: "fifty",
        6: "sixty", 7: "seventy", 8: "eighty", 9: "ninety"
    }

    def convert_two_digits(num: int) -> str:
        if num == 0:
            return ""
        if num < 20:
            return ones[num]
        t, rem = divmod(num, 10)
        if rem == 0:
            return tens[t]
        return f"{tens[t]}-{ones[rem]}"

    def convert_three_digits(num: int) -> str:
        parts = []
        h, rem = divmod(num, 100)
        if h > 0:
            parts.append(f"{ones[h]} hundred")
        if rem > 0:
            parts.append(convert_two_digits(rem))
        return " ".join(parts)

    parts = []

    # Crore (10,000,000)
    crore, n = divmod(n, 10_000_000)
    if crore > 0:
        parts.append(f"{convert_two_digits(crore)} crore")

    # Lakh (100,000)
    lakh, n = divmod(n, 100_000)
    if lakh > 0:
        parts.append(f"{convert_two_digits(lakh)} lakh")

    # Thousand (1,000)
    thousand, n = divmod(n, 1_000)
    if thousand > 0:
        parts.append(f"{convert_two_digits(thousand)} thousand")

    # Remaining hundreds, tens, and units (0-999)
    if n > 0:
        parts.append(convert_three_digits(n))

    return " ".join(parts)
