import datetime


def fy_quarter(d: datetime.date) -> tuple[str, str]:
    year = d.year
    month = d.month

    if month >= 4:
        start_year = year
        if month <= 6:
            quarter = "Q1"
        elif month <= 9:
            quarter = "Q2"
        else:
            quarter = "Q3"
    else:
        start_year = year - 1
        quarter = "Q4"

    end_year_short = (start_year + 1) % 100
    fy_label = f"FY{start_year}-{end_year_short:02d}"

    return fy_label, quarter
