from decimal import Decimal, ROUND_HALF_UP


def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    taxable = Decimal(taxable_paise)
    rate = Decimal(str(rate_pct))

    def round_half_up(value: Decimal) -> int:
        return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    if supplier_state == place_of_supply:
        # Intra-state supply: CGST and SGST apply at half rate each
        tax = round_half_up((taxable * rate) / Decimal("200"))
        return {"cgst": tax, "sgst": tax, "igst": 0}
    else:
        # Inter-state supply: IGST applies at full rate
        tax = round_half_up((taxable * rate) / Decimal("100"))
        return {"cgst": 0, "sgst": 0, "igst": tax}
```

