from decimal import Decimal, ROUND_HALF_UP


def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    taxable = Decimal(taxable_paise)
    rate = Decimal(str(rate_pct))

    if supplier_state == place_of_supply:
        # Intra-state supply: CGST and SGST at half the rate each
        tax = (taxable * rate / Decimal(200)).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        tax_int = int(tax)
        return {
            "cgst": tax_int,
            "sgst": tax_int,
            "igst": 0,
        }
    else:
        # Inter-state supply: IGST at full rate
        tax = (taxable * rate / Decimal(100)).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        return {
            "cgst": 0,
            "sgst": 0,
            "igst": int(tax),
        }
