def gstin_check_char(first14: str) -> str:
    ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    if len(first14) != 14:
        raise ValueError("Input must be exactly 14 characters")

    if not all(c in ALPHABET for c in first14):
        raise ValueError("Input must contain only characters from the alphabet")

    total = 0
    for i, char in enumerate(first14):
        value = ALPHABET.index(char)
        if i % 2 == 0:
            product = value * 1
        else:
            product = value * 2
        total += (product // 36) + (product % 36)

    check_value = (36 - total % 36) % 36
    return ALPHABET[check_value]
