def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    if months <= 0 or principal < 0 or annual_rate_pct < 0:
        raise ValueError("Invalid input parameters")

    if principal == 0:
        return 0.0

    if annual_rate_pct == 0:
        return round(float(principal / months), 2)

    r = annual_rate_pct / 12 / 100
    emi_val = (principal * r * (1 + r) ** months) / ((1 + r) ** months - 1)

    return round(float(emi_val), 2)
