def parse_gstin(gstin: str) -> dict | None:
    if gstin is None:
        return None

    # Trim whitespace and convert to uppercase
    gstin = gstin.strip().upper()

    # Check length
    if len(gstin) != 15:
        return None

    # Valid state codes: 01-38, 97
    state_code = gstin[:2]
    if state_code == "39":
        return None
    if state_code == "97":
        pass  # Valid
    else:
        try:
            state_num = int(state_code)
            if state_num < 1 or state_num > 38:
                return None
        except ValueError:
            return None

    # PAN validation: 5 letters, 4 digits, 1 letter
    pan = gstin[2:12]
    if len(pan) != 10:
        return None

    if not pan[:5].isalpha() or not pan[5:9].isdigit() or not pan[9:].isalpha() or len(pan[9:]) != 1:
        return None

    # Entity number: one character, 1-9 or A-Z
    entity_number = gstin[12]
    if not (entity_number.isdigit() and int(entity_number) >= 1) and not (entity_number.isalpha() and entity_number != '0'):
        return None

    # Must be 'Z'
    if gstin[13] != 'Z':
        return None

    # Calculate check character
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    sum_val = 0
    for i in range(14):
        char = gstin[i]
        if char not in alphabet:
            return None
        value = alphabet.index(char)
        if i % 2 == 0:
            product = value * 1
        else:
            product = value * 2
        sum_val += (product // 36) + (product % 36)

    check = alphabet[(36 - sum_val % 36) % 36]

    if check != gstin[14]:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number
    }
```

