def parse_ifsc(code: str) -> tuple[str, str] | None:
    # Strip whitespace and convert to uppercase
    code = code.strip().upper()

    # Check exact length
    if len(code) != 11:
        return None

    # Check first 4 characters are letters
    bank_code = code[0:4]
    if not bank_code.isalpha():
        return None

    # Check 5th character is '0'
    if code[4] != '0':
        return None

    # Check last 6 characters are alphanumeric
    branch_code = code[5:11]
    if not branch_code.isalnum():
        return None

    return (bank_code, branch_code)
```

