def ascii_to_indic_digits(text: str, script: str) -> str:
    script_offsets = {
        "devanagari": 0x0966,
        "bengali": 0x09E6,
        "gurmukhi": 0x0A66,
        "gujarati": 0x0AE6,
        "odia": 0x0B66,
        "tamil": 0x0BE6,
        "telugu": 0x0C66,
        "kannada": 0x0CE6,
        "malayalam": 0x0D66,
    }

    script_lower = script.lower()
    if script_lower not in script_offsets:
        raise ValueError(f"Invalid script: {script}")

    start_codepoint = script_offsets[script_lower]
    translation_table = {
        ord(str(i)): chr(start_codepoint + i) for i in range(10)
    }

    return text.translate(translation_table)
```

