def ascii_to_indic_digits(text: str, script: str) -> str:
    script_bases = {
        "devanagari": 0x0966,
        "bengali": 0x09E6,
        "gurmukhi": 0x0A66,
        "gujarati": 0x0AE6,
        "odia": 0x0B66,
        "tamil": 0x0BE6,
        "telugu": 0x0C66,
        "kannada": 0x0CE6,
        "malayalam": 0x0D66,
    }

    script_key = script.lower()
    if script_key not in script_bases:
        raise ValueError(f"Unsupported script: {script!r}")

    base = script_bases[script_key]
    trans_table = {ord("0") + i: base + i for i in range(10)}
    return text.translate(trans_table)
