import re


def parse_booking_status(status: str) -> dict | None:
    if not isinstance(status, str):
        return None

    # Split by one or more spaces or slashes
    tokens = [t for t in re.split(r"[\s/]+", status.strip()) if t]
    if not tokens:
        return None

    first = tokens[0].upper()

    # Confirmed case
    if first == "CNF":
        if len(tokens) not in (3, 4):
            return None
        coach = tokens[1].upper()
        if not coach:
            return None
        try:
            berth = int(tokens[2])
        except ValueError:
            return None

        berth_type = tokens[3].upper() if len(tokens) == 4 else None
        return {
            "status": "CNF",
            "coach": coach,
            "berth": berth,
            "berth_type": berth_type,
        }

    # RAC case
    if first == "RAC":
        if len(tokens) != 2:
            return None
        try:
            number = int(tokens[1])
        except ValueError:
            return None
        return {
            "status": "RAC",
            "number": number,
        }

    # Waitlist case
    valid_wl_codes = {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}
    if first in valid_wl_codes:
        if len(tokens) != 2:
            return None
        try:
            number = int(tokens[1])
        except ValueError:
            return None
        return {
            "status": "WL",
            "list": first,
            "number": number,
        }

    return None
