    if not s:
        return None

    # हिस्सों को '/' या spaces (एक या अधिक) से अलग करें
    tokens = [t for t in re.split(r"[/ \t]+", s) if t]
    if not tokens:
        return None

    first = tokens[0].upper()

    # Confirmed cases: CNF/coach/berth या CNF/coach/berth/berth_type
    if first == "CNF":
        if len(tokens) == 3:
            coach = tokens[1].upper()
            berth_str = tokens[2]
            if not berth_str.isdigit():
                return None
            return {
                "status": "CNF",
                "coach": coach,
                "berth": int(berth_str),
                "berth_type": None,
            }
        elif len(tokens) == 4:
            coach = tokens[1].upper()
            berth_str = tokens[2]
            berth_type = tokens[3].upper()
            if not berth_str.isdigit():
                return None
            return {
                "status": "CNF",
                "coach": coach,
                "berth": int(berth_str),
                "berth_type": berth_type,
            }
        else:
            return None

    # RAC cases: RAC/number या RAC number
    if first == "RAC":
        if len(tokens) == 2 and tokens[1].isdigit():
            return {"status": "RAC", "number": int(tokens[1])}
        return None

    # Waitlist cases: WL, GNWL, RLWL, PQWL, TQWL
    wl_codes = {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}
    if first in wl_codes:
        if len(tokens) == 2 and tokens[1].isdigit():
            return {
                "status": "WL",
                "list": first,
                "number": int(tokens[1]),
            }
        return None

    return None
