        50: "पचास", 60: "साठ", 70: "सत्तर", 80: "अस्सी", 90: "नब्बे"
    }

    crore_part = n // 10**7
    remainder = n % 10**7

    lakh_part = remainder // 10**5
    remainder = remainder % 10**5

    thousand_part = remainder // 10**3
    remainder = remainder % 10**3

    hundred_part = remainder // 100
    last_two = remainder % 100

    parts = []

    if crore_part > 0:
        crore_str = ""
        if crore_part == 1:
            crore_str = "एक"
        else:
            crore_str = num_words[crore_part]
        parts.append(crore_str + " करोड़")

    if lakh_part > 0:
        lakh_str = ""
        if lakh_part == 1:
            lakh_str = "एक"
        else:
