        parts.append(thousand_str + " हज़ार")

    if hundred_part > 0:
        hundred_str = ""
        if hundred_part == 1:
            hundred_str = "एक"
        else:
            hundred_str = num_words[hundred_part]
        parts.append(hundred_str + " सौ")

