import re


def normalize_mobile(s: str) -> str | None:
    if not isinstance(s, str):
        return None

    # spaces, hyphens, dots और कोष्ठक (parentheses) हटाएं
    cleaned = re.sub(r"[\s\-\.()]", "", s)

    # Prefix हटाने का क्रम: "+91", "0091", "91" (यदि 12 अंक हों), "0" (यदि 11 अंक हों)
    if cleaned.startswith("+91"):
        cleaned = cleaned[3:]
    elif cleaned.startswith("0091"):
        cleaned = cleaned[4:]
    elif cleaned.startswith("91") and len(cleaned) == 12 and cleaned.isdigit():
        cleaned = cleaned[2:]
    elif cleaned.startswith("0") and len(cleaned) == 11 and cleaned.isdigit():
        cleaned = cleaned[1:]

    # शेष ठीक 10 ASCII अंक होने चाहिए जो 6, 7, 8 या 9 से शुरू हों
    if re.fullmatch(r"[6-9]\d{9}", cleaned):
        return f"+91{cleaned}"

    return None
