import datetime

def fy_quarter(d: datetime.date) -> tuple[str, str]:
    year = d.year

    # Determine financial year
    if d.month >= 4:
        # April to March
        fy_start = year
        fy_end = year + 1
    else:
        # January to March
        fy_start = year - 1
        fy_end = year

    fy_label = f"FY{fy_start}{fy_end % 100:02d}"

    # Determine quarter
    if d.month in (4, 5, 6):
        quarter = "Q1"
    elif d.month in (7, 8, 9):
        quarter = "Q2"
    elif d.month in (10, 11, 12):
        quarter = "Q3"
    else:
        quarter = "Q4"

    return (fy_label, quarter)
