def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    def round_half_up(value: float) -> int:
        # Round to nearest integer, with exact halves rounded up
        # Add 0.5 and floor for positive numbers
        return int(value + 0.5)

    if supplier_state == place_of_supply:
        # Intra-state: CGST + SGST, each at half rate
        cgst_rate_pct = rate_pct / 2
        sgst_rate_pct = rate_pct / 2

        cgst_paise = round_half_up(taxable_paise * cgst_rate_pct / 100)
        sgst_paise = round_half_up(taxable_paise * sgst_rate_pct / 100)

        # IGST is 0 for intra-state
        return {
            "cgst": cgst_paise,
            "sgst": sgst_paise,
            "igst": 0
        }
    else:
        # Inter-state: IGST at full rate
        igst_paise = round_half_up(taxable_paise * rate_pct / 100)

        # CGST and SGST are 0 for inter-state
        return {
            "cgst": 0,
            "sgst": 0,
            "igst": igst_paise
        }
