def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    # Helper function to round half up
    def round_half_up(n):
        # Multiply by 100 to convert to paise (already in paise, so just round)
        # Actually taxable_paise is already in paise, so we need to round the final tax amount
        # n is a float representing paise, we want to round it to nearest integer paise
        # Using math.floor(n + 0.5) for positive numbers
        import math
        return math.floor(n + 0.5)

    # Validate inputs
    if not isinstance(taxable_paise, int) or taxable_paise < 0:
        return {"cgst": 0, "sgst": 0, "igst": 0}
    if not isinstance(rate_pct, (int, float)) or rate_pct < 0:
        return {"cgst": 0, "sgst": 0, "igst": 0}
    if not isinstance(supplier_state, str) or len(supplier_state) != 2 or not supplier_state.isdigit():
        return {"cgst": 0, "sgst": 0, "igst": 0}
    if not isinstance(place_of_supply, str) or len(place_of_supply) != 2 or not place_of_supply.isdigit():
        return {"cgst": 0, "sgst": 0, "igst": 0}

    # Check if intra-state supply
    if supplier_state == place_of_supply:
        # Split equally between CGST and SGST
        cgst = round_half_up(taxable_paise * rate_pct / 2.0 / 100.0)
        sgst = round_half_up(taxable_paise * rate_pct / 2.0 / 100.0)
        igst = 0
    else:
        # Inter-state: full IGST
        igst = round_half_up(taxable_paise * rate_pct / 100.0)
        cgst = 0
        sgst = 0

    return {"cgst": cgst, "sgst": sgst, "igst": igst}
