def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    if months <= 0:
        raise ValueError("months must be positive")
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if annual_rate_pct < 0:
        raise ValueError("annual_rate_pct must be non-negative")

    if annual_rate_pct == 0:
        emi_value = principal / months
    else:
        r = annual_rate_pct / 12 / 100
        emi_value = principal * r * (1 + r) ** months / ((1 + r) ** months - 1)

    return round(emi_value, 2)
