def ascii_to_indic_digits(text: str, script: str) -> str:
    script = script.lower()

    digit_maps = {
        "devanagari": "०१२३४५६७८९",
        "bengali": "০১২৩৪৫৬৭৮৯",
        "gurmukhi": "੦੧੨੩੪੫੬੭੮੯",
        "gujarati": "૦૧૨૩૪૫૬૭૮૯",
        "odia": "୦୧୨୩୪୫୬୭୮୯",
        "tamil": "௦௧௨௩௪௫௬௭௮௯",
        "telugu": "౦౧౨౩౪౫౬౭౮౯",
        "kannada": "೦೧೨೩೪೫೬೭೮೯",
        "malayalam": "൦൧൨൩൪൫൬൭൮൯",
    }

    if script not in digit_maps:
        raise ValueError(f"Unsupported script: {script!r}. Supported scripts: {', '.join(digit_maps.keys())}")

    target_digits = digit_maps[script]

    result = []
    for char in text:
        if '0' <= char <= '9':
            result.append(target_digits[ord(char) - ord('0')])
        else:
            result.append(char)

    return "".join(result)
