MONTH_NAMES = {name.lower(): idx for idx, name in enumerate(calendar.month_name) if name}
MONTH_ABBRS = {abbr.lower(): idx for idx, abbr in enumerate(calendar.month_abbr) if abbr}


def parse_indian_date(s: str) -> date:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    # Match: day [sep] month [sep] year with separators: '/', '-', '.', or spaces
    pattern = r"^\s*(\d{1,2})[\/\-\.\s]+([A-Za-z]+|\d{1,2})[\/\-\.\s]+(\d{4}|\d{2})\s*$"
    match = re.match(pattern, s)
    if not match:
        raise ValueError(f"Invalid date format: {s!r}")

    day_str, month_str, year_str = match.groups()

    # Parse year (2-digit mapped to 2000-2099)
    year = int(year_str)
    if len(year_str) == 2:
        year += 2000

    # Parse month (number, 3-letter abbreviation, or full name)
    if month_str.isdigit():
        month = int(month_str)
    else:
        m_lower = month_str.lower()
        if m_lower in MONTH_NAMES:
            month = MONTH_NAMES[m_lower]
        elif m_lower in MONTH_ABBRS:
            month = MONTH_ABBRS[m_lower]
        else:
            raise ValueError(f"Invalid month name: {month_str!r}")

    # Parse day
    day = int(day_str)

    # Validate and construct date object
    try:
        return date(year, month, day)
    except ValueError as e:
        raise ValueError(f"Invalid date values: {e}") from e
