def pincode_state(pincode: str, table: dict[str, str]) -> str | None:
    # PIN code se spaces hatao
    cleaned_pincode = pincode.replace(" ", "")

    # Validate: exactly 6 ASCII digits hona chahiye aur 0 se start nahi hona chahiye
    if len(cleaned_pincode) != 6 or not cleaned_pincode.isdigit() or cleaned_pincode[0] == '0':
        return None

    # Table mein se sabse lambi key dhoondo jo PIN code se start hoti hai
    matched_state = None

    for table_key in table.keys():
        # Check if the PIN code starts with the table key
        if cleaned_pincode.startswith(table_key):
            # Agar abhi tak koi state nahi mili ya yeh key pehle wali se lambi hai
            if matched_state is None or len(table_key) > len(matched_state):
                matched_state = table_key

    # Agar koi matching key mili toh uska state return karo, warna None
    if matched_state is not None:
        return table[matched_state]

    return None
