import re

def parse_booking_status(status: str) -> dict | None:
    if status is None:
        return None

    s = status.strip().upper().replace("/", " ")
    parts = s.split()

    if not parts:
        return None

    # Check for Confirmed
    if parts[0] == "CNF":
        if len(parts) >= 3:
            try:
                berth = int(parts[2])
                coach = parts[1]
                berth_type = parts[3] if len(parts) > 3 else None
                return {
                    "status": "CNF",
                    "coach": coach,
                    "berth": berth,
                    "berth_type": berth_type
                }
            except ValueError:
                return None

    # Check for RAC
    elif parts[0] == "RAC":
        if len(parts) >= 2:
            try:
                number = int(parts[1])
                return {"status": "RAC", "number": number}
            except ValueError:
                return None

    # Check for Waitlist
    elif parts[0] in ["WL", "GNWL", "RLWL", "PQWL", "TQWL"]:
        if len(parts) >= 2:
            try:
                number = int(parts[1])
                return {"status": "WL", "list": parts[0], "number": number}
            except ValueError:
                return None

    return None
