import re
from datetime import datetime, timezone, timedelta

def ist_to_utc(s: str) -> str:
    # Validate and parse the input string
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    # Regex to match the format DD/MM/YYYY hh:mm AM/PM
    pattern = r'^(\d{2})/(\d{2})/(\d{4})\s+(\d{1,2}):(\d{2})\s+(AM|PM)$'
    match = re.match(pattern, s.strip(), re.IGNORECASE)

    if not match:
        raise ValueError("Invalid string format. Expected format: DD/MM/YYYY hh:mm AM/PM")

    day, month, year, hour_str, minute_str, am_pm = match.groups()

    try:
        day_int = int(day)
        month_int = int(month)
        year_int = int(year)
        hour_int = int(hour_str)
        minute_int = int(minute_str)
    except ValueError:
        raise ValueError("Invalid date or time values")

    # Validate ranges
    if not (1 <= day_int <= 31):
        raise ValueError("Day must be between 01 and 31")
    if not (1 <= month_int <= 12):
        raise ValueError("Month must be between 01 and 12")
    if not (1 <= hour_int <= 12):
        raise ValueError("Hour must be between 01 and 12")
    if not (0 <= minute_int <= 59):
        raise ValueError("Minute must be between 00 and 59")

    # Handle 12-hour clock conversion
    if am_pm.upper() == 'AM':
        if hour_int == 12:
            hour_int = 0  # 12 AM is midnight
    else:  # PM
        if hour_int != 12:
            hour_int += 12  # 1-11 PM

    # Create datetime object in IST (UTC+05:30)
    try:
        ist_dt = datetime(year_int, month_int, day_int, hour_int, minute_int, tzinfo=timezone(timedelta(hours=5, minutes=30)))
    except ValueError as e:
        raise ValueError(f"Invalid date: {e}")

    # Convert to UTC
    utc_dt = ist_dt.astimezone(timezone.utc)

    # Format to ISO format with Z suffix
    return utc_dt.strftime("%Y-%m-%dT%H:%M:00Z")
