def card_info(number: str) -> tuple[str, bool] | None:
    cleaned = number.replace(" ", "").replace("-", "")

    if not (12 <= len(cleaned) <= 19):
        return None

    if not cleaned.isdigit():
        return None

    def luhn_check(s: str) -> bool:
        total = 0
        reverse = s[::-1]
        for i, ch in enumerate(reverse):
            d = int(ch)
            if i % 2 == 1:
                d *= 2
                if d > 9:
                    d -= 9
            total += d
        return total % 10 == 0

    def get_network(s: str) -> str:
        if s.startswith("34") or s.startswith("37"):
            return "Amex"
        if s.startswith("4"):
            return "Visa"
        if len(s) >= 4:
            first_two = int(s[:2])
            first_four = int(s[:4])
            if 51 <= first_two <= 55 or (2221 <= first_four <= 2720):
                return "Mastercard"
            if s.startswith("60") or s.startswith("65") or s.startswith("81") or s.startswith("82") or s.startswith("508"):
                return "RuPay"
        return "Unknown"

    return (get_network(cleaned), luhn_check(cleaned))
