def card_info(number: str) -> tuple[str, bool] | None:
    # Spaces और hyphens हटाएँ
    cleaned = number.replace(" ", "").replace("-", "")

    # 12-19 ASCII अंक हैं या नहीं, यह जाँचें
    if not (12 <= len(cleaned) <= 19) or not cleaned.isdigit():
        return None

    # Luhn checksum जाँचें
    total = 0
    reverse_digits = list(map(int, cleaned[::-1]))
    for i, digit in enumerate(reverse_digits):
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    luhn_ok = (total % 10 == 0)

    # Network पहचानें
    prefix = cleaned[:4]
    first_two = int(cleaned[:2])
    first_four = int(cleaned[:4])

    if cleaned.startswith("34") or cleaned.startswith("37"):
        network = "Amex"
    elif cleaned.startswith("4"):
        network = "Visa"
    elif (51 <= first_two <= 55) or (2221 <= first_four <= 2720):
        network = "Mastercard"
    elif cleaned.startswith("60") or cleaned.startswith("65") or cleaned.startswith("81") or cleaned.startswith("82") or cleaned.startswith("508"):
        network = "RuPay"
    else:
        network = "Unknown"

    return (network, luhn_ok)
