import re

def parse_booking_status(status: str) -> dict | None:
    if status is None:
        return None

    s = status.strip().upper()

    # Check for Confirmed status
    if s.startswith("CNF"):
        # Split by "/" or one or more spaces
        parts = re.split(r'\s+/', s)

        if len(parts) == 3:
            # Format: "CNF/B2/45"
            if parts[1] == "CNF":
                try:
                    berth = int(parts[2])
                    return {
                        "status": "CNF",
                        "coach": parts[1],
                        "berth": berth,
                        "berth_type": None
                    }
                except ValueError:
                    return None

            # Format: "CNF/B2/45/LB"
            elif len(parts) == 4 and parts[2] == "CNF":
                try:
                    berth = int(parts[3])
                    return {
                        "status": "CNF",
                        "coach": parts[1],
                        "berth": berth,
                        "berth_type": parts[2]
                    }
                except ValueError:
                    return None

            elif len(parts) >= 4 and parts[1] == "CNF":
                # Format: "CNF B2 45 LB"
                try:
                    berth = int(parts[3])
                    return {
                        "status": "CNF",
                        "coach": parts[1],
                        "berth": berth,
                        "berth_type": parts[2]
                    }
                except ValueError:
                    return None

        # Check for "CNF B2 45" or "CNF/B2 45"
        elif len(parts) == 3 and parts[1] != "CNF":
            if parts[0] == "CNF":
                try:
                    berth = int(parts[2])
                    return {
                        "status": "CNF",
                        "coach": parts[1],
                        "berth": berth,
                        "berth_type": None
                    }
                except ValueError:
                    return None

        elif len(parts) == 3 and parts[0] == "CNF":
            # Format: "CNF/B2/45" already checked, but just in case
            try:
                berth = int(parts[2])
                return {
                    "status": "CNF",
                    "coach": parts[1],
                    "berth": berth,
                    "berth_type": None
                }
            except ValueError:
                return None

    # Check for RAC
    if s.startswith("RAC"):
        # "RAC 12" or "RAC/12"
        parts = re.split(r'\s+/', s)

        if len(parts) == 2:
            if parts[0] == "RAC":
                try:
                    number = int(parts[1])
                    return {
                        "status": "RAC",
                        "number": number
                    }
                except ValueError:
                    return None

        elif len(parts) == 2 and parts[0] == "RAC":
            try:
                number = int(parts[1])
                return {
                    "status": "RAC",
                    "number": number
                }
            except ValueError:
                return None

    # Check for Waitlist
    wl_patterns = [
        (r'^WL\s+(\d+)$', "WL"),
        (r'^GNWL\s+(\d+)$', "GNWL"),
        (r'^RLWL/(\d+)$', "RLWL"),
        (r'^PQWL\s+(\d+)$', "PQWL"),
        (r'^TQWL\s+(\d+)$', "TQWL"),
    ]

    for pattern, waitlist_code in wl_patterns:
        match = re.match(pattern, s)
        if match:
            number = int(match.group(1))
            return {
                "status": "WL",
                "list": waitlist_code,
                "number": number
            }

        # Check with space separator for GNWL, PQWL, TQWL
        match = re.match(pattern.replace('/', r'\s+'), s)
        if match:
            number = int(match.group(1))
            return {
                "status": "WL",
                "list": waitlist_code,
                "number": number
            }

        # Check for RLWL with space
        if pattern[0] == '^RLWL':
            match = re.match(r'^RLWL\s+(\d+)$', s)
            if match:
                number = int(match.group(1))
                return {
                    "status": "WL",
                    "list": "RLWL",
                    "number": number
                }

    # Check for "WL 34" or "WL/34"
    if s.startswith("WL") and len(parts) == 2 and parts[0] == "WL":
        try:
            number = int(parts[1])
            return {
                "status": "WL",
                "list": "WL",
                "number": number
            }
        except ValueError:
            return None

    return None
