                        "coach": parts[1],
                        "berth": berth,
                        "berth_type": None
                    }
                except ValueError:
                    return None

        # Format: "CNF/S5/7" or "CNF S5 7"
        elif len(parts) >= 3 and parts[0] == "CNF":
            try:
                berth = int(parts[2])
                return {
                    "status": "CNF",
                    "coach": parts[1],
                    "berth": berth,
                    "berth_type": None
                }
            except ValueError:
                return None

    # Check for RAC
    if s.startswith("RAC"):
        # "RAC 12" or "RAC/12"
        parts = re.split(r'\s+/', s)

