                return {
                    "status": "WL",
                    "list": "RLWL",
                    "number": number
                }

    # Check for "WL 34" or "WL/34"
    if s.startswith("WL") and len(parts) >= 2:
        if parts[0] == "WL":
            try:
                number = int(parts[1])
                return {
