        # Check if exactly 11 digits remain after removing "0"
        if len(cleaned) == 11:
            cleaned = cleaned[1:]
        else:
            return None

    # Step 3: Validate the remaining digits
    if len(cleaned) == 10 and cleaned.isdigit() and cleaned[0] in '6789':
        return '+91' + cleaned

