    cleaned = re.sub(r'[ .()-]', '', s)

    # Check if it starts with +91 or 0091
    if cleaned.startswith('+91'):
        remaining = cleaned[3:]
    elif cleaned.startswith('0091'):
        remaining = cleaned[4:]
    else:
        remaining = cleaned

    # Strip leading 91 if exactly 12 digits remain
    if len(remaining) == 12 and remaining.startswith('91'):
        remaining = remaining[2:]

    # Strip leading 0 if exactly 11 digits remain
    if len(remaining) == 11 and remaining.startswith('0'):
        remaining = remaining[1:]

    # Check if exactly 10 digits remain, starting with 6, 7, 8, or 9
    if len(remaining) == 10 and re.match(r'^[6789]\d{9}$', remaining):
        return '+91' + remaining

    return None
