def msme_category(investment_cr: float, turnover_cr: float) -> str:
    """वर्गीकृत करता है कि उद्यम Micro, Small, Medium या Not MSME है।

    पैरामीटर:
        investment_cr (float): संयंत्र और मशीनरी/उपकरण में निवेश (करोड़ रुपये में)।
        turnover_cr (float): कुल टर्नओवर (करोड़ रुपये में)।

    रिटर्न:
        str: "Micro", "Small", "Medium", या "Not MSME"।
    """
    if investment_cr < 0 or turnover_cr < 0:
        raise ValueError("निवेश और टर्नओवर के मान ऋणात्मक नहीं हो सकते।")

    if investment_cr <= 2.5 and turnover_cr <= 10:
        return "Micro"
    elif investment_cr <= 25 and turnover_cr <= 100:
        return "Small"
    elif investment_cr <= 125 and turnover_cr <= 500:
        return "Medium"
    else:
        return "Not MSME"
```

