from datetime import date
from decimal import Decimal, ROUND_HALF_UP


def advance_tax_due(total_tax: int, on_date: date) -> int:
    """भारत में किसी दी गई तारीख़ तक कुल cumulative advance tax देय रकम की गणना करता है।"""
    if total_tax < 10000:
        return 0

    year = on_date.year
    month = on_date.month

    # भारतीय वित्त वर्ष 1 अप्रैल से 31 मार्च तक चलता है
    if month >= 4:
        fy_start_year = year
    else:
        fy_start_year = year - 1

    d_june = date(fy_start_year, 6, 15)
    d_sept = date(fy_start_year, 9, 15)
    d_dec = date(fy_start_year, 12, 15)
    d_march = date(fy_start_year + 1, 3, 15)

    if on_date >= d_march:
        rate = Decimal("1.00")
    elif on_date >= d_dec:
        rate = Decimal("0.75")
    elif on_date >= d_sept:
        rate = Decimal("0.45")
    elif on_date >= d_june:
        rate = Decimal("0.15")
    else:
        rate = Decimal("0.00")

    due_amount = Decimal(total_tax) * rate
    rounded_amount = due_amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP)

    return int(rounded_amount)
```

