import re
import math

def parse_indian_amount(s: str) -> int:
    s = s.strip()

    # Remove leading currency markers
    if s.lower().startswith('₹') or s.lower().startswith('rs.') or s.lower().startswith('rs') or s.lower().startswith('inr'):
        s = s[1:].strip()

    # Remove commas and spaces
    s = s.replace(',', '').replace(' ', '')

    # Pattern to match the number and optional unit
    pattern = r'^([+-]?\d*\.?\d+)(.*)$'
    match = re.match(pattern, s, re.IGNORECASE)

    if not match:
        raise ValueError(f"Cannot parse amount: {s!r}")

    number_str, unit_str = match.groups()

    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f"Invalid number: {number_str!r}")

    # Determine the multiplier based on the unit
    unit_str_lower = unit_str.lower()

    if unit_str_lower in ('crore', 'crores', 'cr'):
        multiplier = 10000000
    elif unit_str_lower in ('lakh', 'lakhs', 'lac', 'lacs', 'l'):
        multiplier = 100000
    elif unit_str_lower in ('k', 'thousand'):
        multiplier = 1000
    else:
        multiplier = 1

    # Calculate the final amount
    result = number * multiplier

    # Round to nearest rupee, with halves rounded up
    if result > 0:
        result = math.floor(result + 0.5)
    elif result < 0:
        result = math.ceil(result - 0.5)
    else:
        result = 0

    return int(result)
