import math

def gratuity(monthly_salary: int, years: int, months: int) -> int:
    if years < 5:
        return 0

    if months > 6:
        counted_years = years + 1
    else:
        counted_years = years

    gratuity_amount = 15 * monthly_salary * counted_years / 26

    # Round to nearest rupee, exact halves up
    gratuity_amount = math.floor(gratuity_amount + 0.5)

    # Cap at 20,00,000
    gratuity_amount = min(gratuity_amount, 2000000)

    return int(gratuity_amount)
