import math

def gst_reverse(inclusive_paise: int, rate_pct: float) -> tuple[int, int]:
    if rate_pct == 0:
        return (inclusive_paise, 0)

    # GST ke bina taxable value calculate karein
    # exact half upar round karne ke liye math.floor(x + 0.5) use karein
    exact_taxable = (inclusive_paise * 100) / (100 + rate_pct)
    taxable = int(math.floor(exact_taxable + 0.5))

    # GST amount calculate karein
    gst = inclusive_paise - taxable

    return (taxable, gst)
