        month_str = match.group(3).lower()
        year = int(match.group(5))
        if year < 100:
            year += 2000
        if month_str not in month_map:
            raise ValueError("Invalid month abbreviation")
        month = month_map[month_str]
        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError("Invalid date")

    # Pattern 3: DD/MonthName/YYYY or DD-MonthName-YYYY or DD.MonthName.YYYY or DD MonthName YYYY
    pattern3 = r'^(\d{1,2})([ /.-])([a-zA-Z]+) ([ /.-])(\d{4}|\d{2})$'
    match = re.match(pattern3, s)
    if match:
        day = int(match.group(1))
        month_str = match.group(3).lower()
        year = int(match.group(5))
        if year < 100:
            year += 2000
        if month_str not in month_map:
            raise ValueError("Invalid month name")
        month = month_map[month_str]
        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError("Invalid date")

    # Pattern 4: DD MonthName YYYY (space separated)
    pattern4 = r'^(\d{1,2}) ([a-zA-Z]+) (\d{4}|\d{2})$'
    match = re.match(pattern4, s)
    if match:
        day = int(match.group(1))
        month_str = match.group(2).lower()
        year = int(match.group(3))
        if year < 100:
            year += 2000
        if month_str not in month_map:
            raise ValueError("Invalid month name")
        month = month_map[month_str]
        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError("Invalid date")

    # Pattern 5: DD/MMM/YY or DD-MMM-YY (already covered by pattern2)
    # Pattern 6: DD MonthName YY
    pattern6 = r'^(\d{1,2}) ([a-zA-Z]+) (\d{2})$'
    match = re.match(pattern6, s)
    if match:
        day = int(match.group(1))
        month_str = match.group(2).lower()
        year = int(match.group(3))
        year += 2000
        if month_str not in month_map:
            raise ValueError("Invalid month name")
        month = month_map[month_str]
        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError("Invalid date")

    # If no pattern matched
    raise ValueError(f"Invalid date format: {s}")
