def cheque_amount_words(paise: int) -> str:
    if not isinstance(paise, int) or paise < 0 or paise > 99999999999:
        raise ValueError("Invalid amount: paise must be between 0 and 99999999999")

    rupees = paise // 100
    paisa = paise % 100

    def convert_hundreds(n: int) -> str:
        if n == 0:
            return "Zero"

        ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
                "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
                "Seventeen", "Eighteen", "Nineteen"]
        tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

        if n < 20:
            return ones[n]

        result = ""
        hundreds = n // 100
        remainder = n % 100

        if hundreds > 0:
            result += ones[hundreds] + " Hundred"

        if remainder > 0:
            if result:
                result += " "
            if remainder < 20:
                result += ones[remainder]
            else:
                ten = remainder // 10
                unit = remainder % 10
                if unit == 0:
                    result += tens[ten]
                else:
                    result += tens[ten] + "-" + ones[unit]

        return result

    rupee_words = convert_hundreds(rupees)

    if rupees == 0:
        rupee_words = "Zero"

    if paisa == 0:
        return f"Rupees {rupee_words} Only"
    else:
        paisa_words = convert_hundreds(paisa)
        if paisa < 100 and paisa > 0:
            paisa_words = "Zero" + paisa_words
        return f"Rupees {rupee_words} and {paisa_words} Paise Only"
