import math

def format_compact_inr(rupees: int) -> str:
    if rupees == 0:
        return "0"

    sign = "-" if rupees < 0 else ""
    amount = abs(rupees)

    # Determine the unit based on the value before rounding
    if amount >= 10000000:
        unit = "cr"
        value = amount / 10000000.0
    elif amount >= 100000:
        unit = "l"
        value = amount / 100000.0
    else:
        unit = ""
        value = float(amount)

    # Round to 2 decimal places (round half up)
    if unit:
        rounded_value = math.floor(value + 0.005)
    else:
        rounded_value = value

    if unit == "cr":
        # Remove trailing zeros and trailing dot
        formatted = f"{rounded_value:g} Cr"
    elif unit == "l":
        # Remove trailing zeros and trailing dot
        formatted = f"{rounded_value:g} L"
    else:
        # Indian digit grouping
        s = str(int(rounded_value))
        if len(s) <= 3:
            formatted = s
        else:
            # Last 3 digits, then groups of 2
