import re


def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    gstin = gstin.strip().upper()

    if len(gstin) != 15:
        return None

    state_code = gstin[:2]
    valid_states = {f"{i:02d}" for i in range(1, 39)} | {"97"}
    if state_code not in valid_states:
        return None

    pan = gstin[2:12]
    if not re.fullmatch(r"[A-Z]{5}[0-9]{4}[A-Z]", pan):
        return None

    entity_number = gstin[12]
    if not re.fullmatch(r"[1-9A-Z]", entity_number):
        return None

    if gstin[13] != "Z":
        return None

    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    char_map = {char: idx for idx, char in enumerate(alphabet)}

    total_sum = 0
    for i in range(14):
        char = gstin[i]
        if char not in char_map:
            return None
        val = char_map[char]
        multiplier = 1 if i % 2 == 0 else 2
        product = val * multiplier
        total_sum += (product // 36) + (product % 36)

    check_val = (36 - (total_sum % 36)) % 36
    expected_check_char = alphabet[check_val]

    if gstin[14] != expected_check_char:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
