import re

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
CHAR_MAP = {char: idx for idx, char in enumerate(ALPHABET)}
GSTIN_PATTERN = re.compile(
    r"^(0[1-9]|[1-2][0-9]|3[0-8]|97)([A-Z]{5}[0-9]{4}[A-Z])([1-9A-Z])Z([0-9A-Z])$"
)


def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    cleaned = gstin.strip().upper()
    match = GSTIN_PATTERN.match(cleaned)
    if not match:
        return None

    state_code, pan, entity_number, check_char = match.groups()

    checksum = 0
    for i in range(14):
        val = CHAR_MAP[cleaned[i]]
        factor = 1 if i % 2 == 0 else 2
        product = val * factor
        checksum += (product // 36) + (product % 36)

    expected_check = ALPHABET[(36 - (checksum % 36)) % 36]
    if check_char != expected_check:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
```

