def advance_tax_due(total_tax: int, on_date: datetime.date) -> int:
    if total_tax < 10000:
        return 0

    # Determine the start of the financial year containing on_date
    if on_date.month >= 4:
        fy_start = on_date.replace(month=4, day=1)
    else:
        fy_start = on_date.replace(month=4, day=1, year=on_date.year - 1)

    # Key installment dates in the financial year
    june_15 = fy_start.replace(month=6, day=15)
    sept_15 = fy_start.replace(month=9, day=15)
    dec_15 = fy_start.replace(month=12, day=15)
    mar_15 = fy_start.replace(month=3, day=15)

    # Determine the cumulative percentage due
    if on_date < june_15:
        percentage = 0
    elif on_date < sept_15:
        percentage = 15
    elif on_date < dec_15:
        percentage = 45
    elif on_date < mar_15:
        percentage = 75
    else:
