def inr_words_en(n: int) -> str:
    """Convert a non-negative integer (0 <= n < 1,000,000,000) into English words

    using the Indian numbering system.
    """
    if not isinstance(n, int) or isinstance(n, bool) or n < 0 or n >= 1_000_000_000:
        raise ValueError("n must be an integer such that 0 <= n < 1,000,000,000")

    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def two_digits_to_words(val: int) -> str:
        if val < 20:
            return ones[val]
        t = val // 10
        o = val % 10
        if o == 0:
            return tens[t]
        return f"{tens[t]}-{ones[o]}"

    crores = n // 10_000_000
    lakhs = (n % 10_000_000) // 100_000
    thousands = (n % 100_000) // 1_000
    hundreds = (n % 1_000) // 100
    remainder = n % 100

    parts = []
    if crores:
        parts.append(f"{two_digits_to_words(crores)} crore")
    if lakhs:
        parts.append(f"{two_digits_to_words(lakhs)} lakh")
    if thousands:
        parts.append(f"{two_digits_to_words(thousands)} thousand")
    if hundreds:
        parts.append(f"{ones[hundreds]} hundred")
    if remainder:
        parts.append(two_digits_to_words(remainder))

    return " ".join(parts)
