    if supplier_state == place_of_supply:
        half_rate = rate / Decimal(2)
        cgst = int(
            (taxable * half_rate / Decimal(100)).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )
        sgst = int(
            (taxable * half_rate / Decimal(100)).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )
        return {
            "cgst": cgst,
            "sgst": sgst,
            "igst": 0,
        }
    else:
        igst = int(
            (taxable * rate / Decimal(100)).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )
        return {
            "cgst": 0,
            "sgst": 0,
            "igst": igst,
