from decimal import Decimal, ROUND_HALF_UP


def gst_split(
    taxable_paise: int,
    rate_pct: float,
    supplier_state: str,
    place_of_supply: str,
) -> dict:
    taxable = Decimal(taxable_paise)
    rate = Decimal(str(rate_pct))

    # Intra-state supply: CGST and SGST apply equally
    if supplier_state.strip() == place_of_supply.strip():
        half_tax = (taxable * rate / Decimal(200)).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        tax_amount = int(half_tax)
        return {"cgst": tax_amount, "sgst": tax_amount, "igst": 0}

    # Inter-state supply: IGST applies at full rate
    full_tax = (taxable * rate / Decimal(100)).quantize(
        Decimal("1"), rounding=ROUND_HALF_UP
    )
    return {"cgst": 0, "sgst": 0, "igst": int(full_tax)}
