def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    """
    Reducing-balance முறையில் மாதாந்திர EMI-ஐக் கணக்கிடுகிறது.

    :param principal: கடன் தொகை (ரூபாயில்)
    :param annual_rate_pct: ஆண்டு வட்டி விகிதம் (சதவீதத்தில்)
    :param months: திருப்பிச் செலுத்தும் காலம் (மாதங்களில்)
    :return: மாதாந்திர தவணைத் தொகை (EMI) float வடிவில் (2 தசம இடங்கள்)
    :raises ValueError: months <= 0, principal < 0 அல்லது annual_rate_pct < 0 எனில்
    """
    if months <= 0:
        raise ValueError("மாதங்களின் எண்ணிக்கை பூஜ்ஜியத்தை விட அதிகமாக இருக்க வேண்டும் (months > 0).")
    if principal < 0:
        raise ValueError("அசல் தொகை எதிர்மறையாக இருக்க முடியாது (principal >= 0).")
    if annual_rate_pct < 0:
        raise ValueError("வட்டி விகிதம் எதிர்மறையாக இருக்க முடியாது (annual_rate_pct >= 0).")

    if principal == 0:
        return 0.0

    if annual_rate_pct == 0:
        return round(float(principal / months), 2)

    r = annual_rate_pct / 12 / 100
    compound_factor = (1 + r) ** months
    emi_val = principal * r * compound_factor / (compound_factor - 1)

    return round(float(emi_val), 2)
