import re


def is_valid_upi_id(vpa: str) -> bool:
    try:
        if not isinstance(vpa, str):
            return False

        cleaned = vpa.strip()

        if cleaned.count("@") != 1:
            return False

        prefix, handle = cleaned.split("@")

        # Prefix rules: 2-64 chars, starts/ends with alphanumeric, allowed chars: [a-zA-Z0-9._-], no consecutive dots
        if ".." in prefix:
            return False

        prefix_pattern = r"^[a-zA-Z0-9][a-zA-Z0-9._-]{0,62}[a-zA-Z0-9]$"
        if not re.fullmatch(prefix_pattern, prefix):
            return False

        # Handle rules: 3-32 chars, starts with a letter, alphanumeric only
        handle_pattern = r"^[a-zA-Z][a-zA-Z0-9]{2,31}$"
        if not re.fullmatch(handle_pattern, handle):
            return False

        return True
    except Exception:
        return False
