    "telugu": 0x0C66,
    "kannada": 0x0CE6,
    "malayalam": 0x0D66,
}

_TRANSLATION_TABLES = {
    script: str.maketrans(_ASCII_DIGITS, "".join(chr(base + i) for i in range(10)))
    for script, base in _SCRIPT_BASES.items()
}


def ascii_to_indic_digits(text: str, script: str) -> str:
    """Replace ASCII digits 0-9 in text with native digits of the specified script."""
    key = script.lower()
    table = _TRANSLATION_TABLES.get(key)
    if table is None:
        raise ValueError(
            f"Unsupported script: {script!r}. Expected one of: {', '.join(_SCRIPT_BASES.keys())}."
        )
    return text.translate(table)
