def card_info(number: str) -> tuple[str, bool] | None:
    cleaned = number.replace(" ", "").replace("-", "")

    if not (12 <= len(cleaned) <= 19 and cleaned.isascii() and cleaned.isdigit()):
        return None

    # Identify network
    if cleaned.startswith(("34", "37")):
        network = "Amex"
    elif cleaned.startswith("4"):
        network = "Visa"
    elif (51 <= int(cleaned[:2]) <= 55) or (2221 <= int(cleaned[:4]) <= 2720):
        network = "Mastercard"
    elif cleaned.startswith(("60", "65", "81", "82", "508")):
        network = "RuPay"
    else:
        network = "Unknown"

    # Luhn checksum validation
    total = 0
    for idx, char in enumerate(reversed(cleaned)):
        digit = int(char)
        if idx % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    luhn_ok = total % 10 == 0

    return (network, luhn_ok)
