import re


def normalize_mobile(s: str) -> str | None:
    if not isinstance(s, str):
        return None

    # spaces, hyphens, dots மற்றும் parentheses-ஐ நீக்குதல்
    cleaned = re.sub(r"[\s\-\.()]", "", s)

    # ஒரு country/trunk prefix-ஐ நீக்குதல்
    if cleaned.startswith("+91"):
        cleaned = cleaned[3:]
    elif cleaned.startswith("0091"):
        cleaned = cleaned[4:]
    elif len(cleaned) == 12 and cleaned.startswith("91"):
        cleaned = cleaned[2:]
    elif len(cleaned) == 11 and cleaned.startswith("0"):
        cleaned = cleaned[1:]

    # 6, 7, 8, 9-இல் தொடங்கும் சரியாக 10 ASCII இலக்கங்கள் உள்ளதா என சரிபார்த்தல்
    if re.fullmatch(r"[6-9][0-9]{9}", cleaned):
        return f"+91{cleaned}"

    return None
