def inr_words_en(n: int) -> str:
    """
    Convert a non-negative integer < 1_000_000_000 into English words
    using the Indian numbering system: crore, lakh, thousand, hundred.
    """
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must be in the range 0 <= n < 1_000_000_000")

    ALL_ONES = [
        "zero", "one", "two", "three", "four", "five",
        "six", "seven", "eight", "nine", "ten",
        "eleven", "twelve", "thirteen", "fourteen", "fifteen",
        "sixteen", "seventeen", "eighteen", "nineteen",
    ]

    tens_words = [
        "",
        "",
        "twenty",
        "thirty",
        "forty",
        "fifty",
        "sixty",
        "seventy",
        "eighty",
        "ninety",
    ]

    def _under_100(x: int) -> str:
        """Words for an integer in the inclusive range 0..99."""
        if x < 20:
            return ALL_ONES[x]
        ten, unit = divmod(x, 10)
        if unit:
            return f"{tens_words[ten]}-{ALL_ONES[unit]}"
        return tens_words[ten]

    def _under_1000(x: int) -> str:
        """Words for an integer in the inclusive range 0..999."""
        if x < 100:
            return _under_100(x)
        hundred, rest = divmod(x, 100)
        words = [ALL_ONES[hundred], "hundred"]
        if rest:
            if rest < 100:
                words.append(_under_100(rest))
            else:
                words.append(_under_1000(rest))
        return " ".join(words)

    if n == 0:
        return "zero"

    parts = []
    crore = n // 10_000_000
    if crore:
        parts.append(f"{_under_100(crore)} crore")
    n %= 10_000_000

    lakh = n // 100_000
    if lakh:
        parts.append(f"{_under_100(lakh)} lakh")
    n %= 100_000

    thousand = n // 1_000
    if thousand:
        parts.append(f"{_under_100(thousand)} thousand")
    n %= 1_000

    if n:
        parts.append(_under_1000(n))

    return " ".join(parts)
