def inr_words_en(n: int) -> str:
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must be a non-negative integer less than 1,000,000,000")

    if n == 0:
        return "zero"

    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]

    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
        "eighty", "ninety"
    ]

    def words_small(x: int) -> str:
        if x < 20:
            return ones[x]
        ten = x // 10
        one = x % 10
        if one == 0:
            return tens[ten]
        return tens[ten] + "-" + ones[one]

    def words_hundreds(x: int) -> str:
        if x < 100:
            return words_small(x)
        hundreds = x // 100
        remainder = x % 100
        if remainder == 0:
            return ones[hundreds] + " hundred"
        return ones[hundreds] + " hundred " + words_small(remainder)

    crore = n // 10_000_000
    remainder = n % 10_000_000
    lakh = remainder // 100_000
    remainder2 = remainder % 100_000
    thousand = remainder2 // 1_000
    unit = remainder2 % 1_000

    parts = []
    if crore:
        parts.append(words_small(crore) + " crore")
    if lakh:
        parts.append(words_small(lakh) + " lakh")
    if thousand:
        parts.append(words_small(thousand) + " thousand")
    if unit:
        parts.append(words_hundreds(unit))

    return " ".join(parts)
