from decimal import Decimal, ROUND_HALF_UP


def gratuity(monthly_salary: int, years: int, months: int) -> int:
    if years < 5:
        return 0

    counted_years = years + 1 if months > 6 else years

    # Gratuity = 15 * monthly_salary * counted_years / 26
    raw_amount = (
        Decimal(15) * Decimal(monthly_salary) * Decimal(counted_years)
    ) / Decimal(26)
    rounded_amount = int(
        raw_amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    )

    ceiling = 20_00_000
    return min(rounded_amount, ceiling)
