def epf_contribution(basic_da: int) -> dict:
    wage = Decimal(basic_da)
    eps_wage = Decimal(min(basic_da, 15000))

    employee = int(
        (wage * Decimal("0.12")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    )
    employer_eps = int(
        (eps_wage * Decimal("0.0833")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
    )
    employer_epf = employee - employer_eps

    return {
        "employee": employee,
        "employer_eps": employer_eps,
        "employer_epf": employer_epf,
    }
