def fd_maturity(principal: int, annual_rate_pct: float, months: int) -> float:
    if months <= 0 or months % 3 != 0:
        raise ValueError("months must be a positive multiple of 3.")

    maturity = principal * (1 + annual_rate_pct / 400) ** (months / 3)
    return round(float(maturity), 2)
