import re

VALID_TYPES = {"PLC", "PTC", "GOI", "SGC", "FLC", "GAP", "NPL", "ULL", "ULT", "OPC"}
CIN_PATTERN = re.compile(r"^([LU])(\d{5})([A-Z]{2})(\d{4})([A-Z]{3})(\d{6})$")


def parse_cin(cin: str) -> dict | None:
    if not isinstance(cin, str):
        return None

    cleaned_cin = cin.strip().upper()
    match = CIN_PATTERN.match(cleaned_cin)
    if not match:
        return None

    listed_char, industry, state, year_str, comp_type, reg_no = match.groups()

    year = int(year_str)
    if not (1850 <= year <= 2100):
        return None

    if comp_type not in VALID_TYPES:
        return None

    return {
        "listed": listed_char == "L",
        "industry": industry,
        "state": state,
        "year": year,
        "type": comp_type,
        "reg_no": reg_no,
    }
