def inr_words_en(n: int) -> str:
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must satisfy 0 <= n < 1_000_000_000")

    units = [
        "zero", "one", "two", "three", "four", "five",
        "six", "seven", "eight", "nine"
    ]
    teens = [
        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety"
    ]

    def word_lt_1000(x: int) -> str:
        if x < 10:
            return units[x]
        if x < 20:
            return teens[x - 10]
        if x < 100:
            t = tens[x // 10 - 2]
            if x % 10 == 0:
                return t
            return t + "-" + units[x % 10]
        # 100 <= x < 1000
        hundred = units[x // 100] + " hundred"
        rest = x % 100
        if rest == 0:
            return hundred
        return hundred + " " + word_lt_1000(rest)

    def group_words(value: int, suffix: str) -> str:
        if value == 0:
            return ""
        return word_lt_1000(value) + (" " + suffix if suffix else "")

    crores = n // 10_000_000
    n %= 10_000_000
    lakhs = n // 100_000
    n %= 100_000
    thousands = n // 1_000
    units_part = n % 1_000

    parts = [
        group_words(crores, "crore"),
        group_words(lakhs, "lakh"),
        group_words(thousands, "thousand"),
        group_words(units_part, "")
    ]

    return " ".join(p for p in parts if p)
