def inr_words_en(n: int) -> str:
    if not isinstance(n, int) or n < 0 or n >= 1_000_000_000:
        raise ValueError("n must satisfy 0 <= n < 1_000_000_000")

    if n == 0:
        return "zero"

    units = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def _hundreds(num: int) -> str:
        if num < 20:
            return units[num]
        if num < 100:
            ten, unit = num // 10, num % 10
            if unit:
                return f"{tens[ten]}-{units[unit]}"
            return tens[ten]
        hundred = f"{units[num // 100]} hundred"
        rem = num % 100
        if rem:
            return f"{hundred} {_hundreds(rem)}"
        return hundred

    crore = n // 10_000_000
    n %= 10_000_000
    lakh = n // 100_000
    n %= 100_000
    thousand = n // 1_000
    remainder = n % 1_000

    parts = []
    if crore:
        parts.append(f"{_hundreds(crore)} crore")
    if lakh:
        parts.append(f"{_hundreds(lakh)} lakh")
    if thousand:
        parts.append(f"{_hundreds(thousand)} thousand")
    if remainder:
        parts.append(_hundreds(remainder))

    return " ".join(parts)
