import datetime


def bank_working_days(
    start: datetime.date, end: datetime.date, holidays: list[datetime.date]
) -> int:
    if start > end:
        return 0

    holiday_set = set(holidays)
    working_days = 0
    current = start
    one_day = datetime.timedelta(days=1)

    while current <= end:
        weekday = current.weekday()  # Monday = 0, ..., Saturday = 5, Sunday = 6

        if weekday == 6:
            # रविवार (Sunday) - बैंक बंद रहता है
            pass
        elif weekday == 5:
            # शनिवार (Saturday) - दूसरा (8-14 तारीख़) और चौथा (22-28 तारीख़) बंद रहता है
            is_closed_saturday = (8 <= current.day <= 14) or (
                22 <= current.day <= 28
            )
            if not is_closed_saturday and current not in holiday_set:
                working_days += 1
        else:
            # सोमवार से शुक्रवार (Monday to Friday)
            if current not in holiday_set:
                working_days += 1

        current += one_day

    return working_days
```

