def cheque_amount_words(paise: int) -> str:
    """
    தொகையை (paise) இந்திய cheque முறைப்படி சொற்களாக மாற்றுகிறது.
    ரூபாய்ப் பகுதி n < 1,000,000,000 ஆக இருக்க வேண்டும்.
    """
    if paise < 0:
        raise ValueError("தொகை எதிர்மறையாக (negative) இருக்கக்கூடாது.")

    rupees = paise // 100
    p = paise % 100

    if rupees >= 1_000_000_000:
        raise ValueError("ரூபாய்ப் பகுதி 1,000,000,000-க்கு குறைவாக இருக்க வேண்டும்.")

    ones = {
        1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
        6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten",
        11: "Eleven", 12: "Twelve", 13: "Thirteen", 14: "Fourteen", 15: "Fifteen",
        16: "Sixteen", 17: "Seventeen", 18: "Eighteen", 19: "Nineteen"
    }
    tens = {
        20: "Twenty", 30: "Thirty", 40: "Forty", 50: "Fifty",
        60: "Sixty", 70: "Seventy", 80: "Eighty", 90: "Ninety"
    }

    def two_digits_to_words(n: int) -> str:
        if n < 20:
            return ones.get(n, "")
        ten_part = (n // 10) * 10
        unit_part = n % 10
        if unit_part == 0:
            return tens[ten_part]
        return f"{tens[ten_part]}-{ones[unit_part]}"

    def number_to_words(n: int) -> str:
        if n == 0:
            return "Zero"

        crore = n // 10_000_000
        lakh = (n // 100_000) % 100
        thousand = (n // 1_000) % 100
        hundred = (n // 100) % 10
        remainder = n % 100

        parts = []
        if crore > 0:
            parts.append(f"{two_digits_to_words(crore)} Crore")
        if lakh > 0:
            parts.append(f"{two_digits_to_words(lakh)} Lakh")
        if thousand > 0:
            parts.append(f"{two_digits_to_words(thousand)} Thousand")
        if hundred > 0:
            parts.append(f"{ones[hundred]} Hundred")
        if remainder > 0:
            parts.append(two_digits_to_words(remainder))

        return " ".join(parts)

    rupee_words = number_to_words(rupees)

    if p == 0:
        return f"Rupees {rupee_words} Only"
    else:
        paise_words = two_digits_to_words(p)
        return f"Rupees {rupee_words} and {paise_words} Paise Only"
