def cheque_amount_words(paise: int) -> str:
    if paise < 0 or paise // 100 >= 1_000_000_000:
        raise ValueError("Amount in paise must be non-negative and rupees < 1,000,000,000")

    ones = {
        1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
        6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten",
        11: "Eleven", 12: "Twelve", 13: "Thirteen", 14: "Fourteen",
        15: "Fifteen", 16: "Sixteen", 17: "Seventeen", 18: "Eighteen",
        19: "Nineteen",
    }
    tens = {
        2: "Twenty", 3: "Thirty", 4: "Forty", 5: "Fifty",
        6: "Sixty", 7: "Seventy", 8: "Eighty", 9: "Ninety",
    }

    def two_digit_words(n: int) -> str:
        if n in ones:
            return ones[n]
        if n >= 20:
            t, r = divmod(n, 10)
            if r == 0:
                return tens[t]
            return f"{tens[t]}-{ones[r]}"
        return ""

    def number_to_words(n: int) -> str:
        if n == 0:
            return "Zero"

        crore, rem = divmod(n, 10_000_000)
        lakh, rem = divmod(rem, 100_000)
        thousand, rem = divmod(rem, 1_000)
        hundred, rem = divmod(rem, 100)

        parts = []
        if crore:
            parts.append(f"{two_digit_words(crore)} Crore")
        if lakh:
            parts.append(f"{two_digit_words(lakh)} Lakh")
        if thousand:
            parts.append(f"{two_digit_words(thousand)} Thousand")
        if hundred:
            parts.append(f"{two_digit_words(hundred)} Hundred")
        if rem:
            parts.append(two_digit_words(rem))

        return " ".join(parts)

    rupees, paise_part = divmod(paise, 100)
    rupee_words = number_to_words(rupees)

    if paise_part == 0:
        return f"Rupees {rupee_words} Only"
    else:
        paise_words = number_to_words(paise_part)
        return f"Rupees {rupee_words} and {paise_words} Paise Only"
