import datetime


def next_invoice_number(prev: str | None, d: datetime.date) -> str:
    # நடப்பு தேதிக்கான நிதியாண்டைக் (Financial Year) கண்டறிதல் (ஏப்ரல் 1 - மார்ச் 31)
    if d.month >= 4:
        start_year = d.year
    else:
        start_year = d.year - 1

    end_year_short = (start_year + 1) % 100
    current_fy = f"{start_year}-{end_year_short:02d}"

    seq = 1

    # முந்தைய invoice எண் கொடுக்கப்பட்டு, அது நடப்பு FY-இல் இருந்தால் sequence-ஐ அதிகரித்தல்
    if prev is not None:
        parts = prev.split("/")
        if len(parts) == 3 and parts[0] == "INV":
            prev_fy = parts[1]
            if prev_fy == current_fy:
                try:
                    seq = int(parts[2]) + 1
                except ValueError:
                    seq = 1

    # குறைந்தது 4 இலக்கங்கள் கொண்ட zero-padded sequence
    return f"INV/{current_fy}/{seq:04d}"
```

