import datetime


def next_invoice_number(prev: str | None, d: datetime.date) -> str:
    # Determine Indian Financial Year (1 April - 31 March)
    if d.month >= 4:
        start_year = d.year
        end_year = (d.year + 1) % 100
    else:
        start_year = d.year - 1
        end_year = d.year % 100

    current_fy = f"{start_year}-{end_year:02d}"

    seq = 1
    if prev is not None:
        parts = prev.split("/")
        if len(parts) == 3 and parts[0] == "INV":
            prev_fy, prev_seq = parts[1], parts[2]
            if prev_fy == current_fy:
                seq = int(prev_seq) + 1

    return f"INV/{current_fy}/{seq:04d}"
