import datetime
from decimal import Decimal, ROUND_HALF_UP


def advance_tax_due(total_tax: int, on_date: datetime.date) -> int:
    # இந்தியாவில் கணக்கிடப்பட்ட வரி ₹10,000-க்குக் குறைவு எனில் advance tax தேவையில்லை
    if total_tax < 10000:
        return 0

    # நிதியாண்டு ஏப்ரல் 1 முதல் மார்ச் 31 வரை (மாதம் 4 முதல் 3 வரை)
    m, d = on_date.month, on_date.day
    fy_key = (m if m >= 4 else m + 12, d)

    # தவணை வாரியாக சதவீதங்கள்
    if fy_key < (6, 15):
        rate = 0
    elif fy_key < (9, 15):
        rate = 15
    elif fy_key < (12, 15):
        rate = 45
    elif fy_key < (15, 15):
        rate = 75
    else:
        rate = 100

    if rate == 0:
        return 0

    # சரியாகப் பாதி என்றால் மேல்நோக்கி round செய்தல் (ROUND_HALF_UP)
    due_amount = (Decimal(total_tax) * Decimal(rate) / Decimal(100)).quantize(
        Decimal("1"), rounding=ROUND_HALF_UP
    )

    return int(due_amount)
