import datetime
from decimal import Decimal, ROUND_HALF_UP


def advance_tax_due(total_tax: int, on_date: datetime.date) -> int:
    if total_tax < 10000:
        return 0

    # Determine financial year start year (April 1 to March 31)
    if on_date.month >= 4:
        fy_start_year = on_date.year
    else:
        fy_start_year = on_date.year - 1

    d_june = datetime.date(fy_start_year, 6, 15)
    d_sept = datetime.date(fy_start_year, 9, 15)
    d_dec = datetime.date(fy_start_year, 12, 15)
    d_march = datetime.date(fy_start_year + 1, 3, 15)

    if on_date < d_june:
        rate = Decimal("0.00")
    elif on_date < d_sept:
        rate = Decimal("0.15")
    elif on_date < d_dec:
        rate = Decimal("0.45")
    elif on_date < d_march:
        rate = Decimal("0.75")
    else:
        rate = Decimal("1.00")

    due_amount = Decimal(total_tax) * rate
    rounded_amount = due_amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP)

    return int(rounded_amount)
