def inr_words_hi(n: int) -> str:
    if n == 0:
        return "शून्य"

    words = {
        1: "एक", 2: "दो", 3: "तीन", 4: "चार", 5: "पाँच",
        6: "छह", 7: "सात", 8: "आठ", 9: "नौ",
        10: "दस"
    }

    tens = {
        20: "बीस", 30: "तीस", 40: "चालीस",
        50: "पचास", 60: "साठ", 70: "सत्तर",
        80: "अस्सी", 90: "नब्बे"
    }

    units = ["", "**", "***", "चतुर्थ", "पंचम", "षष्ठ्", "सप्तम", "अष्टम", "नवम", "**"]

    def convert_hundreds(d):
        word = units[d]
        mapping = {
            1: "एक", 2: "दो", 3: "तीन", 4: "चार", 5: "पाँच",
            6: "छह", 7: "सात", 8: "आठ", 9: "नौ"
        }
        if d == 0:
            return ""
        elif d == 1:
            return "एक"
        else:
            return units[d] + "hundred"

    def convert_tens(num):
        if num == 0:
            return ""
        elif num not in tens:
            if num < 10:
                return words[num]
            else:
                # Handle numbers 11-19
                return "दस" + words[num - 10]
        else:
            return tens[num]

    parts = []

    # Extract crore part
    crore = n // 10**7
    if crore > 0:
        parts.append(f"{convert_tens(crore)} करोड़")

    # Extract lakh part (next 5 digits)
    n %= 10**7
    lakh = (n // 10**5) % 100
    if lakh > 0:
        parts.append(f"{convert_tens(lakh)} लाख")

    # Extract thousand part (next 3 digits)
    n %= 10**5
    thousand = (n // 10**2) % 100
    if thousand > 0:
        parts.append(f"{convert_tens(thousand)} हज़ार")

    # Extract hundreds digit
    remainder = n % 10**2
    hundreds = remainder // 10
    if hundreds > 0:
        parts.append(f"{hundreds} सौ")

    # Extract last two digits
    last_two = remainder % 100
    if last_two > 0:
        parts.append(convert_tens(last_two))

    return " ".join(parts)
