from decimal import Decimal, ROUND_HALF_UP

def income_tax_new_regime(gross_salary: int) -> int:
    # Standard deduction (not below zero)
    taxable = max(0, gross_salary - 75_000)

    # Rebate: tax is zero if taxable income is 12,00,000 or less
    if taxable <= 1_200_000:
        tax = Decimal('0')
    else:
        if taxable > 2_400_000:
            tax = Decimal('300000') + (taxable - 2_400_000) * Decimal('30') / Decimal('100')
        elif taxable > 2_000_000:
            tax = Decimal('200000') + (taxable - 2_000_000) * Decimal('25') / Decimal('100')
        elif taxable > 1_600_000:
            tax = Decimal('120000') + (taxable - 1_600_000) * Decimal('20') / Decimal('100')
        elif taxable > 1_200_000:
            tax = Decimal('60000') + (taxable - 1_200_000) * Decimal('15') / Decimal('100')
        elif taxable > 800_000:
            tax = Decimal('20000') + (taxable - 800_000) * Decimal('10') / Decimal('100')
        elif taxable > 400_000:
            tax = (taxable - 400_000) * Decimal('5') / Decimal('100')
        else:
            tax = Decimal('0')

    # Add 4% health and education cess
    total = tax + tax * Decimal('4') / Decimal('100')

    # Round to nearest rupee, exact halves rounded up
    rounded = total.quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    return int(rounded)
