def indic_digits_to_ascii(text: str) -> str:
    # இந்தோ-ஆரிய எழுத்துமுறைகளில் உள்ள இலக்க எழுத்துகளை ASCII இலக்கங்களான '0'–'9' ஆக மாற்றவும்.
    digit_map = {}

    # தேவநாகரி: U+0966–U+096F
    for code in range(0x0966, 0x096F + 1):
        digit_map[chr(code)] = str(code - 0x0966)
    # பெங்காலி: U+09E6–U+09EF
    for code in range(0x09E6, 0x09EF + 1):
        digit_map[chr(code)] = str(code - 0x09E6)
    # குர்முகி: U+0A66–U+0A6F
    for code in range(0x0A66, 0x0A6F + 1):
        digit_map[chr(code)] = str(code - 0x0A66)
    # குஜராத்தி: U+0AE6–U+0AEF
    for code in range(0x0AE6, 0x0AEF + 1):
        digit_map[chr(code)] = str(code - 0x0AE6)
    # ஒடியா: U+0B66–U+0B6F
    for code in range(0x0B66, 0x0B6F + 1):
        digit_map[chr(code)] = str(code - 0x0B66)
    # தமிழ்: U+0B80–U+0B89
    for code in range(0x0B80, 0x0B89 + 1):
        digit_map[chr(code)] = str(code - 0x0B80)
    # தெலுங்கு: U+0C66–U+0C6F
    for code in range(0x0C66, 0x0C6F + 1):
        digit_map[chr(code)] = str(code - 0x0C66)
    # கன்னட: U+0CE6–U+0CEF
    for code in range(0x0CE6, 0x0CEF + 1):
        digit_map[chr(code)] = str(code - 0x0CE6)
    # மலையாளம்: U+0D66–U+0D6F
    for code in range(0x0D66, 0x0D6F + 1):
        digit_map[chr(code)] = str(code - 0x0D66)

    return text.translate(str.maketrans(digit_map))
