def pincode_state(pincode: str, table: dict[str, str]) -> str | None:
    p = pincode.replace(' ', '')

    if len(p) != 6 or not p.isascii() or any(not ('0' <= ch <= '9') for ch in p):
        return None

    if p[0] == '0':
        return None

    longest_prefix = None
    longest_len = 0
    for prefix in table:
        if len(prefix) > longest_len and p.startswith(prefix):
            longest_prefix = prefix
            longest_len = len(prefix)

    return table.get(longest_prefix)
