import re

def parse_booking_status(status: str) -> dict | None:
    """இந்திய ரயில்வே டிக்கெட் புக்கிங் ஸ்டேட்டஸ் ஸ்ட்ரிங்குகளை பார்ஸ் (Parse) செய்யவும்.

    இது அந்தந்த கேட்டகரிக்கான தகவல்களைக் கொண்ட ஒரு டிக்‌ஷனரியை (dictionary) திருப்பித் தரும்
    (கன்ஃபார்ம்ட், RAC அல்லது வெயிட்லிஸ்ட்). சரியில்லாத ஃபார்மேட்கள் அல்லது எண்கள் அல்லாத
    பர்த்/நம்பர் ஃபீல்டுகளுக்கு None-ஐ திருப்பித் தரும்.
    """
    if not isinstance(status, str):
        return None

    # இருபுறமும் உள்ள இடைவெளிகளை (whitespace) நீக்கவும்
    s = status.strip()
    if not s:
        return None

    # இடைவெளி மற்றும் '/' எழுத்துகளின் எந்தவொரு காம்பினேஷனிலும் பிரிக்கவும்
    tokens = [t for t in re.split(r"[\\s/]+", s) if t]
    if not tokens:
        return None

    # கேஸ்-இன்சென்சிட்டிவ் (case-insensitive) ஒப்பீட்டிற்காக முதல் டோக்கனை நார்மலைஸ் (Normalise) செய்யவும்
    token0 = tokens[0].upper()

    # --------------------------------------------------------------------
    # கன்ஃபார்ம் செய்யப்பட்ட புக்கிங்: CNF <coach> <berth> [berth_type]
    # --------------------------------------------------------------------
    if token0 == "CNF":
        if len(tokens) == 3:
            # CNF <coach> <berth>
            coach = tokens[1].upper()
            berth_token = tokens[2]
            try:
                berth = int(berth_token)
            except ValueError:
                return None
            return {"status": "CNF", "coach": coach, "berth": berth, "berth_type": None}
        elif len(tokens) == 4:
            # CNF <coach> <berth> <berth_type>
            coach = tokens[1].upper()
            berth_token = tokens[2]
            berth_type = tokens[3].upper()
            try:
                berth = int(berth_token)
            except ValueError:
                return None
            return {"status": "CNF", "coach": coach, "berth": berth, "berth_type": berth_type}
        else:
            # எதிர்பாராத எண்ணிக்கையிலான பகுதிகள்
            return None

    # --------------------------------------------------------------------
    # RAC புக்கிங்: RAC <number>
    # --------------------------------------------------------------------
    if token0 == "RAC":
        if len(tokens) != 2:
            return None
        number_token = tokens[1]
        try:
            number = int(number_token)
        except ValueError:
            return None
        return {"status": "RAC", "number": number}

    # --------------------------------------------------------------------
    # வெயிட்லிஸ்ட் புக்கிங்: WL|GNWL|RLWL|PQWL|TQWL <number>
    # --------------------------------------------------------------------
    waitlist_codes = {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}
    if token0 in waitlist_codes:
        if len(tokens) != 2:
            return None
        list_code = token0   # ஏற்கனவே அப்பர்கேஸில் (uppercase) உள்ளது
        number_token = tokens[1]
        try:
            number = int(number_token)
        except ValueError:
            return None
        return {"status": "WL", "list": list_code, "number": number}

    # --------------------------------------------------------------------
    # வேறு எதுவாக இருந்தாலும் அது புரியவில்லை
    # --------------------------------------------------------------------
    return None
