import re

def parse_booking_status(status: str) -> dict | None:
    """
    இந்திய ரயில்வே புக்கிங் ஸ்டேட்டஸ் ஸ்ட்ரிங்குகளை பார்ஸ் செய்யவும்.

    எதிர்பார்க்கப்படும் ஃபார்மேட்கள்:
      - கன்ஃபார்ம்ட்: "CNF/B2/45" அல்லது "CNF/B2/45/LB"
                 -> {"status": "CNF", "coach": "B2", "berth": 45, "berth_type": "LB"}
      - RAC: "RAC 12" அல்லது "RAC/12"
                 -> {"status": "RAC", "number": 12}
      - வெயிட்லிஸ்ட்: "WL 34", "GNWL 34", "RLWL/5", "PQWL 2", "TQWL 9"
                 -> {"status": "WL", "list": "GNWL", "number": 34}

    கொடுக்கப்பட்ட ஸ்ட்ரிங்கை பார்ஸ் செய்ய முடியவில்லை என்றால் (தவறான செப்பரேட்டர்கள், எண்கள் அல்லாத பெர்த்/நம்பர் போன்றவை) None-ஐ ரிட்டர்ன் செய்யும்.
    """
    # இன்புட்டை வேலிடேட் செய்யவும்
    if not isinstance(status, str):
        return None

    # முன்னும் பின்னும் உள்ள ஸ்பேஸ்களை ட்ரிம் செய்யவும்
    s = status.strip()
    if not s:
        return None

    # ஸ்பேஸ் அல்லது '/' எழுத்துகளின் எந்தவொரு கலவையிலும் பிரிக்கவும்,
    # காலியான பகுதிகளை வடிகட்டவும்.
    tokens = [t for t in re.split(r'[\s/]+', s) if t]
    if not tokens:
        return None

    # முதல் டோக்கன் கேஸ்-இன்சென்சிட்டிவ் ஆக ஏற்றுக்கொள்ளப்படும்
    token0 = tokens[0].upper()

    # --------------------------------------------------------------------
    # கன்ஃபார்ம்ட் புக்கிங்
    # --------------------------------------------------------------------
    if token0 == "CNF":
        # 3 அல்லது 4 டோக்கன்கள் இருக்க வேண்டும்
        if len(tokens) not in (3, 4):
            return None
        coach = tokens[1].upper()
        # பெர்த் numeric ஆக இருக்க வேண்டும்
        try:
            berth = int(tokens[2])
        except ValueError:
            return None
        berth_type = None
        if len(tokens) == 4:
            berth_type = tokens[3].upper()
        return {
            "status": "CNF",
            "coach": coach,
            "berth": berth,
            "berth_type": berth_type,
        }

    # --------------------------------------------------------------------
    # RAC புக்கிங்
    # --------------------------------------------------------------------
    if token0 == "RAC":
        if len(tokens) != 2:
            return None
        try:
            number = int(tokens[1])
        except ValueError:
            return None
        return {"status": "RAC", "number": number}

    # --------------------------------------------------------------------
    # வெயிட்லிஸ்ட் புக்கிங்
    # --------------------------------------------------------------------
    waitlist_codes = {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}
    if token0 in waitlist_codes:
        if len(tokens) != 2:
            return None
        try:
            number = int(tokens[1])
        except ValueError:
            return None
        return {"status": "WL", "list": token0, "number": number}

    # --------------------------------------------------------------------
    # மத்த எந்த ஸ்ட்ரிங்கும் சப்போர்ட் செய்யப்படாது
    # --------------------------------------------------------------------
    return None
