import re
from datetime import datetime, timezone, timedelta

def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError
    s = s.strip()
    if not s:
        raise ValueError
    m = re.fullmatch(
        r'(\d{2})/(\d{2})/(\d{4})\s+([0-9]{1,2}):([0-5][0-9])\s+([AP]M)',
        s,
        re.IGNORECASE,
    )
    if not m:
        raise ValueError
    day, month, year, hour, minute, ampm = m.groups()
    try:
        day_int = int(day)
        month_int = int(month)
        year_int = int(year)
        hour_int = int(hour)
        minute_int = int(minute)
    except ValueError:
        raise ValueError
    if not (1 <= month_int <= 12):
        raise ValueError
    if not (1 <= day_int <= 31):
        raise ValueError
    if not (1 <= hour_int <= 12):
        raise ValueError
    if ampm.upper() == 'AM':
        hour_24 = 0 if hour_int == 12 else hour_int
    else:
        hour_24 = 12 if hour_int == 12 else hour_int + 12
    try:
        dt_ist = datetime(year_int, month_int, day_int, hour_24, minute_int)
    except ValueError:
        raise ValueError
    dt_ist = dt_ist.replace(
        tzinfo=timezone(timedelta(hours=5, minutes=30))
    )
    dt_utc = dt_ist.astimezone(timezone.utc)
    return dt_utc.strftime('%Y-%m-%dT%H:%M:00Z')
