def card_info(number: str) -> tuple[str, bool] | None:
    # Remove spaces and hyphens
    s = number.replace(" ", "").replace("-", "")

    # Must be 12-19 ASCII digits only
    if not (12 <= len(s) <= 19) or not all("0" <= ch <= "9" for ch in s):
        return None

    # Luhn checksum
    digits = [int(ch) for ch in s]
    total = 0
    for i in range(len(digits) - 1, -1, -1):
        d = digits[i]
        if (len(digits) - i) % 2 == 0:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    luhn_ok = (total % 10) == 0

    # Network detection (prioritize RuPay prefixes, which overlap Visa/Mastercard ranges)
    if s.startswith(("60", "65", "81", "82", "508")):
        network = "RuPay"
    elif s.startswith("4"):
        network = "Visa"
    elif s.startswith(("34", "37")):
        network = "Amex"
    elif (
        (int(s[:2]) >= 51 and int(s[:2]) <= 55)
        or (int(s[:4]) >= 2221 and int(s[:4]) <= 2720)
    ):
        network = "Mastercard"
    else:
        network = "Unknown"

    return (network, luhn_ok)
