import datetime

def ist_to_utc(s: str) -> str:
    s = s.strip()
    if not s:
        raise ValueError("Invalid input string")

    parts = s.split(None, 2)
    if len(parts) != 3:
        raise ValueError("Invalid format")

    date_str, time_str, ampm = (p.strip() for p in parts)

    if len(date_str) != 10 or date_str[2] != '/' or date_str[5] != '/':
        raise ValueError("Invalid date format")

    d_str, m_str, y_str = date_str[0:2], date_str[3:5], date_str[6:10]
    if len(d_str) != 2 or len(m_str) != 2 or len(y_str) != 4:
        raise ValueError("Invalid date format")

    try:
        d = int(d_str)
        m = int(m_str)
        y = int(y_str)
    except ValueError:
        raise ValueError("Invalid date components")

    if time_str.count(':') != 1:
        raise ValueError("Invalid time format")

    h_str, mm_str = time_str.split(':')
    if len(mm_str) != 2:
        raise ValueError("Invalid time format")

    try:
        hour = int(h_str)
        minute = int(mm_str)
    except ValueError:
        raise ValueError("Invalid time components")

    if not (1 <= hour <= 12):
        raise ValueError("Hour must be between 1 and 12")
    if not (0 <= minute <= 59):
        raise ValueError("Minute must be between 00 and 59")

    ampm = ampm.upper()
    if ampm not in ('AM', 'PM'):
        raise ValueError("Period must be AM or PM")

    try:
        datetime.date(y, m, d)
    except ValueError:
        raise ValueError("Invalid date")

    if ampm == 'AM':
        hour_24 = 0 if hour == 12 else hour
    else:
        hour_24 = 12 if hour == 12 else hour + 12

    try:
        ist_dt = datetime.datetime(y, m, d, hour_24, minute)
    except ValueError:
        raise ValueError("Invalid datetime")

    utc_dt = ist_dt - datetime.timedelta(hours=5, minutes=30)

    return utc_dt.strftime('%Y-%m-%dT%H:%M:00Z')
