```python
def parse_indian_amount(s: str) -> int:
    import re
    from decimal import Decimal, ROUND_HALF_UP

    s = s.strip()
    if not s:
        raise ValueError("Empty input")

    # Remove a leading currency marker (₹, Rs, Rs., INR), case-insensitive.
    s = re.sub(r'^[\s₹]*(?:Rs\.?|INR|₹)', '', s, flags=re.IGNORECASE)
    s = s.strip()
    if not s:
        raise ValueError("No amount found")

    # Remove commas and spaces.
    s = s.replace(',', '').replace(' ', '')
    if not s:
        raise ValueError("No amount found")

    # Match the numeric part and the optional unit.
    m = re.match(r'^(\d+(?:\.\d*)?)([a-zA-Z]*)$', s)
    if not m:
        raise ValueError(f"Cannot parse amount: {s!r}")

    num_str, unit_str = m.groups()

    multiplier = 1
    if unit_str:
        unit_lower = unit_str.lower()
        if unit_lower in ('crore', 'crores', 'cr'):
            multiplier = 10_000_000
        elif unit_lower in ('lakh', 'lakhs', 'lac', 'lacs', 'l'):
            multiplier = 100_000
        elif unit_lower in ('k', 'thousand'):
            multiplier = 1_000
        else:
            raise ValueError(f"Unknown unit: {unit_str!r}")

    try:
        total = Decimal(num_str) * Decimal(multiplier)
    except Exception:
        raise ValueError(f"Invalid number: {num_str!r}")

    return int(total.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
