from decimal import Decimal, ROUND_HALF_UP

def _round_half_up(value: Decimal) -> int:
    return int(value.to_integral_value(rounding=ROUND_HALF_UP))

def epf_contribution(basic_da: int) -> dict:
    employee = _round_half_up(Decimal('12') * Decimal(basic_da) / Decimal('100'))
    capped_wage = min(basic_da, 15000)
    employer_eps = _round_half_up(Decimal('8.33') * Decimal(capped_wage) / Decimal('100'))
    employer_epf = _round_half_up(Decimal(employee) - Decimal(employer_eps))
    return {
        "employee": employee,
        "employer_eps": employer_eps,
        "employer_epf": employer_epf,
    }
