def parse_cin(cin: str) -> dict | None:
    cin = cin.strip().upper()
    if len(cin) != 21:
        return None

    if cin[0] not in ("L", "U"):
        return None

    industry = cin[1:6]
    state = cin[6:8]
    year_str = cin[8:12]
    type_code = cin[12:15]
    reg_no = cin[15:21]

    if not (industry.isdigit() and state.isalpha() and year_str.isdigit() and reg_no.isdigit()):
        return None

    try:
        year = int(year_str)
    except ValueError:
        return None

    if not (1850 <= year <= 2100):
        return None

    valid_types = {
        "PLC", "PTC", "GOI", "SGC", "FLC",
        "GAP", "NPL", "ULL", "ULT", "OPC",
    }

    if type_code not in valid_types:
        return None

    return {
        "listed": cin[0] == "L",
        "industry": industry,
        "state": state,
        "year": year,
        "type": type_code,
        "reg_no": reg_no,
    }
