        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety"
    ]

    def _words(x: int) -> str:
        """Convert 1 <= x <= 999 to words.

        Returns empty string for 0.
        """
        if x == 0:
            return ""
        if x < 10:
            return units[x]
        if x < 20:
            return teens[x - 10]
        if x < 100:
            t = x // 10
            u = x % 10
            if u == 0:
                return tens[t]
            return f"{tens[t]}-{units[u]}"

        h = x // 100
        rest = x % 100
        if rest == 0:
            return f"{units[h]} hundred"
        return f"{units[h]} hundred {_words(rest)}"

    crore = n // 10_000_000
    n %= 10_000_000
    lakh = n // 1_00_000
    n %= 1_00_000
    thousand = n // 1_000
    n %= 1_000

    parts = []
    if crore:
        parts.append(f"{_words(crore)} crore")
    if lakh:
        parts.append(f"{_words(lakh)} lakh")
    if thousand:
        parts.append(f"{_words(thousand)} thousand")
    if n:
        parts.append(_words(n))

    return " ".join(parts)
