def inr_words_en(n: int) -> str:
    """
    Convert a non‑negative integer (0 ≤ n < 1,000,000,000) into English words
    using the Indian numbering system (crore, lakh, thousand).
    All output is lower‑case, uses single spaces between words, numbers 21‑99
    that are not multiples of ten are hyphenated, and “and” never appears.
    0 → “zero”.
    Raises ValueError for out‑of‑range inputs.
    """
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must be non‑negative and less than 1,000,000,000")
    if n == 0:
        return "zero"

    _ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven",
        "eight", "nine", "ten", "eleven", "twelve", "thirteen",
        "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
        "nineteen"
    ]
    _tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty",
        "seventy", "eighty", "ninety"
    ]

    def _num_to_words(num: int) -> str:
        """Convert num (0 ≤ num < 1000) to words; no trailing spaces."""
        if num < 20:
            return _ones[num]
        if num < 100:
            tens, below = divmod(num, 10)
            if below == 0:
                return _tens[tens]
            # hyphen for 21‑99 that aren’t multiples of ten
            return f"{_tens[tens]}-{_ones[below]}"
        # num < 1000
        hundreds, below = divmod(num, 100)
        if below == 0:
            return f"{_ones[hundreds]} hundred"
        if hundreds == 1:
            return f"one hundred {_num_to_words(below)}"
        else:
            return f"{_ones[hundreds]} hundred {_num_to_words(below)}"

    parts = []
    crore, n = divmod(n, 10_000_000)   # 10 million = 1 crore
    if crore:
        parts.append(f"{_num_to_words(crore)} crore")

    lakh, n = divmod(n, 100_000)       # 100 000 = 1 lakh
    if lakh:
        parts.append(f"{_num_to_words(lakh)} lakh")

    thousand, n = divmod(n, 1_000)     # 1 000 = 1 thousand
    if thousand:
        parts.append(f"{_num_to_words(thousand)} thousand")

    if n:
        parts.append(_num_to_words(n))

    return " ".join(parts)
