def inr_words_hi(n: int) -> str:
    """
    Convert a non-negative integer (0 <= n < 1,000,000,000) into Hindi words 
    in Devanagari using the Indian system.

    Args:
        n: A non-negative integer to convert

    Returns:
        String representation of the number in Hindi words
    """

    # Handle zero case
    if n == 0:
        return "शून्य"

    # Number words
    unit_words = [
        '', 'एक', 'दो', 'तीन', 'चार', 'पाँच', 'छह', 'सात', 'आठ', 'नौ'
    ]

    teen_words = [
        '', 'दस', 'ग्यारह', 'बारह', 'तेरह', 'चौदह', 'पंद्रह', 
        'सोलह', 'सतरह', 'अठारह', 'उनीस'
    ]

    tens_words = {
        2: 'बीस', 3: 'तीस', 4: 'चालीस', 5: 'पचास',
        6: 'साठ', 7: 'सत्तर', 8: 'अस्सी', 9: 'नब्बे'
    }

    # Extract parts
    crore = n // 10000000  # n // 10^7
    remaining_after_crore = n % 10000000

    lakh = remaining_after_crore // 100000  # Two digits
    remaining_after_lakh = remaining_after_crore % 100000

    thousand = remaining_after_lakh // 1000  # Two digits
    remaining_after_thousand = remaining_after_lakh % 1000

    hundreds = remaining_after_thousand // 100
    last_two = remaining_after_thousand % 100

    # Convert each part
    parts = []

    # Crore part
    if crore > 0:
        parts.append(unit_words[crore] + " करोड़")

    # Lakh part (two digits)
    if lakh > 0:
        parts.append(_parse_two_digit(lakh))

    # Thousand part (two digits)
    if thousand > 0:
        parts.append(_parse_two_digit(thousand) + " हज़ार")

    # Hundreds digit
    if hundreds > 0:
        parts.append(unit_words[hundreds] + " सौ")

    # Last two digits
    if last_two > 0:
        parts.append(_parse_two_digit(last_two))

    return ' '.join(parts)


def _parse_two_digit(num: int) -> str:
    """
    Parse a two-digit number (1-99) into Hindi words.
    Only numbers 10-90 as specified are handled.
    For single digits, returns the word for that digit.
    """
    if num == 0:
        return "शून्य"
    elif num < 10:
        return ['','एक','दो','तीन','चार','पाँच','छह','सात','आठ','नौ'][num]
    elif num < 20:
        return teen_words[num]
    else:
        tens = num // 10
        units = num % 10

        if tens == 1 and num > 19:
            # 11-19 cases
            return teen_words[num]
        elif tens in tens_words:
            if tens == 2:
                return 'एक' + tens_words[tens]
            elif tens == 3:
                return 'दो' + tens_words[tens]
            elif tens == 4:
                return 'तीन' + tens_words[tens]
            elif tens == 5:
                return 'चार' + tens_words[tens]
            elif tens == 6:
                return 'पाँच' + tens_words[tens]
            elif tens == 7:
                return 'छह' + tens_words[tens]
            elif tens == 8:
                return 'सात' + tens_words[tens]
            elif tens == 9:
                return 'आठ' + tens_words[tens]

        # Handle 21-99 with units
        if tens in [2, 3, 4, 5, 6, 7, 8, 9]:
            tens_word = tens_words[tens]
            if num % 10 == 0:
                return tens_word
            else:
                return unit_words[num % 10] + ' ' + tens_word

        return ''
