def inr_words_hi(n: int) -> str:
    """
    ஒரு நெகட்டிவ் அல்லாத இன்டிஜர் n-ஐ (0 <= n < 1,000,000,000) இந்திய முறையிலான தேவநாகிரி ஹிந்தி வார்த்தைகளாக மாற்றவும்.

    Args:
        n (int): மாற்ற வேண்டிய நெகட்டிவ் அல்லாத இன்டிஜர்.

    Returns:
        str: n-ன் இந்திய முறை ஹிந்தி வார்த்தை வடிவம்.
    """
    if n == 0:
        return "शून्य"

    one_digit = {
        1: "एक", 2: "दो", 3: "तीन", 4: "चार", 5: "पाँच",
        6: "छह", 7: "सात", 8: "आठ", 9: "नौ"
    }

    ten_map = {
        10: "दस", 20: "बीस", 30: "तीस", 40: "चालीस",
        50: "पचास", 60: "साठ", 70: "सत्तर", 80: "अस्सी", 90: "नब्बे"
    }

    unit_words = ["करोड़", "लाख", "हज़ार", "सौ"]

    crore = n // 10**7
    rem = n % 10**7

    lakh = rem // 10**5
    rem = rem % 10**5

    thousand = rem // 10**3
    rem = rem % 10**3

    hundreds = rem // 100
    last_two = rem % 100

    def get_number_word(num):
        if num in one_digit:
            return one_digit[num]
        elif num in ten_map:
            return ten_map[num]
        else:
            raise ValueError(f"Number {num} not in the allowed values")

    parts = []

    if crore > 0:
        parts.append(get_number_word(crore) + " " + unit_words[0])

    if lakh > 0:
        parts.append(get_number_word(lakh) + " " + unit_words[1])

    if thousand > 0:
        parts.append(get_number_word(thousand) + " " + unit_words[2])

    if hundreds > 0:
        parts.append(get_number_word(hundreds) + " " + unit_words[3])

    if last_two > 0:
        parts.append(get_number_word(last_two))

    return " ".join(parts)
