def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    if months <= 0:
        raise ValueError("months must be positive")
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if annual_rate_pct < 0:
        raise ValueError("annual rate must be non-negative")

    n = months
    r = annual_rate_pct / 12 / 100.0

    if r == 0:
        emi_val = principal / n
    else:
        emi_val = principal * r * (1 + r) ** n / ((1 + r) ** n - 1)

    return round(emi_val, 2)
