                berth_type = tokens[3].upper()
            except ValueError:
                return None
            return {
                "status": first,
                "coach": coach,
                "berth": berth,
                "berth_type": berth_type,
            }
        return None

    if first == "RAC":
        if len(tokens) == 2:
            try:
                number = int(tokens[1])
            except ValueError:
                return None
            return {"status": first, "number": number}
        return None

    if first in ("WL", "GNWL", "RLWL", "PQWL", "TQWL"):
