    lower_parts = [p.lower() for p in parts]

    # ---- Confirmed -------------------------------------------------------
    if lower_parts[0] == 'cnf':
        # Umeed hai: CNF [coach] [berth] [berth_type]
        if len(parts) not in (3, 4):
