        return {
            "status": "CNF",
            "coach": coach.upper(),
            "berth": berth,
            "berth_type": berth_type
        }

    # ---- RAC -------------------------------------------------------------
    elif lower_parts[0] == 'rac':
        if len(parts) != 2:
            return None
        number_str = parts[1]
        if not number_str.isdigit():
            return None
        return {
            "status": "RAC",
            "number": int(number_str)
        }

    # ---- Waitlist ---------------------------------------------------------
    elif lower_parts[0] in {'wl', 'gnwl', 'rlwl', 'pqwl', 'tqwl'}:
