def parse_booking_status(status: str) -> dict | None:
    """
    Parse an Indian Railways ticket booking status string.

    Returns a dictionary with the parsed details or None if the format
    is not supported.
    """
    # Non‑string input or empty → reject
    if not isinstance(status, str):
        return None

    # Trim surrounding whitespace
    s = status.strip()
    if not s:
        return None

    # Split on "/" or any whitespace (one or more characters)
    parts = re.split(r'[/\s]+', s)

    # Any empty part (e.g., leading/trailing delimiter) makes it invalid
    if any(p == '' for p in parts):
        return None

    if not parts:
        return None

    first = parts[0].upper()

    # -----------------
    # Confirmed: CNF coach berth [berth_type]
    # -----------------
    if first == 'CNF':
        if len(parts) not in (3, 4):
            return None
        coach = parts[1].upper()
        berth_str = parts[2]
        try:
            berth = int(berth_str)
        except ValueError:
            return None
        berth_type = None
        if len(parts) == 4:
            berth_type = parts[3].upper()
            # Only the supported berth type is allowed
            if berth_type != 'LB':
                return None
        return {"status": "CNF", "coach": coach, "berth": berth, "berth_type": berth_type}

    # -----------------
    # RAC: RAC number
    # -----------------
    if first == 'RAC':
        if len(parts) != 2:
            return None
        try:
            number = int(parts[1])
        except ValueError:
            return None
        return {"status": "RAC", "number": number}

    # -----------------
    # Waitlist: WL/GNWL/RLWL/PQWL/TQWL number
    # -----------------
    waitlist_codes = ('WL', 'GNWL', 'RLWL', 'PQWL', 'TQWL')
    if first in waitlist_codes:
        if len(parts) != 2:
            return None
        try:
            number = int(parts[1])
        except ValueError:
            return None
        return {"status": "WL", "list": first, "number": number}

    # Anything else is not supported
    return None
