def card_info(number: str) -> tuple[str, bool] | None:
    cleaned = number.replace(" ", "").replace("-", "")

    if not cleaned.isdigit() or not (12 <= len(cleaned) <= 19):
        return None

    if cleaned.startswith("34") or cleaned.startswith("37"):
        network = "Amex"
    elif cleaned.startswith("4"):
        network = "Visa"
    elif (12 <= int(cleaned[:2]) <= 15) or (51 <= int(cleaned[:2]) <= 55):
        network = "Mastercard"
    elif int(cleaned[:4]) >= 2221 and int(cleaned[:4]) <= 2720:
        network = "Mastercard"
    elif cleaned.startswith("60") or cleaned.startswith("65") or cleaned.startswith("81") or cleaned.startswith("82") or cleaned.startswith("508"):
        network = "RuPay"
    else:
        network = "Unknown"

    luhn_sum = 0
    for i, ch in enumerate(reversed(cleaned)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        luhn_sum += d

    luhn_ok = luhn_sum % 10 == 0

    return network, luhn_ok
