        total = 0
        reversed_digits = digits[::-1]
        for i, ch in enumerate(reversed_digits):
            d = ord(ch) - 48
            if i % 2 == 1:  # Theek daayin or se doosra, aadi
                d *= 2
                if d > 9:
                    d -= 9
            total += d
        return total % 10 == 0

    luhn_ok = _luhn_ok(cleaned)

    # Network pehchanein
    network = "Unknown"
    if len(cleaned) >= 2 and (cleaned.startswith('34') or cleaned.startswith('37')):
