import re

_VALID_STATES = {
    "AN", "AP", "AR", "AS", "BR", "CH", "CG", "DD", "DL", "GA", "GJ",
    "HP", "HR", "JH", "JK", "KA", "KL", "LA", "LD", "MH", "ML", "MN",
    "MP", "MZ", "NL", "OD", "PB", "PY", "RJ", "SK", "TN", "TR", "TS",
    "UK", "UP", "WB",
}

_REGULAR_RE = re.compile(r'^([A-Z]{2})([0-9]{1,2})([A-Z]{1,3})([0-9]{1,4})$')
_BHARAT_RE = re.compile(r'^([0-9]{2})BH([0-9]{4})([A-Z]{1,2})$')


def parse_vehicle_reg(plate: str) -> dict | None:
    s = plate.upper().replace(' ', '').replace('-', '')

    m = _REGULAR_RE.match(s)
    if m:
        state, rto, series, number = m.groups()
        if state in _VALID_STATES:
            return {
                "type": "regular",
                "state": state,
                "rto": rto.zfill(2),
                "series": series,
                "number": number.zfill(4),
            }

    m = _BHARAT_RE.match(s)
    if m:
        year_two, number, series = m.groups()
        yr = int(year_two)
        if yr > 50:
            year = 1900 + yr
        else:
            year = 2000 + yr
        return {
            "type": "BH",
            "year": year,
            "number": number,
            "series": series,
        }

    return None
