def cheque_amount_words(paise: int) -> str:
    """दी गई रकम (paise में) को भारतीय नंबरिंग सिस्टम का उपयोग करके एक भारतीय चेक के लिए शब्दों में बदलें।"""

    def number_to_words(n: int) -> str:
        """0 ≤ n ≤ 999 के लिए शब्दों में बदलें।"""
        if n == 0:
            return "Zero"
        if n < 20:
            ones = [
                "Zero", "One", "Two", "Three", "Four", "Five", "Six",
                "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve",
                "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen",
                "Eighteen", "Nineteen"
            ]
            return ones[n]
        if n < 100:
            tens_word = [
                "", "", "Twenty", "Thirty", "Forty", "Fifty",
                "Sixty", "Seventy", "Eighty", "Ninety"
            ]
            tens_digit = n // 10
            ones_digit = n % 10
            if ones_digit == 0:
                return tens_word[tens_digit]
            else:
                return tens_word[tens_digit] + "-" + number_to_words(ones_digit)
        # 100 ≤ n ≤ 999
        hundreds = n // 100
        remainder = n % 100
        if remainder == 0:
            return number_to_words(hundreds) + " Hundred"
        else:
            return number_to_words(hundreds) + " Hundred " + number_to_words(remainder)

    def rupees_to_words(num: int) -> str:
        """भारतीय ग्रुपिंग (crore, lakh, thousand, units) का उपयोग करके रुपये की रकम (0 < num < 1 000 000 000) को शब्दों में बदलें।"""
        if num == 0:
            return "Zero"
        # करोड़, लाख, हज़ार, इकाई
        crore = num // 10_000_000
        rem = num % 10_000_000
        lakh = rem // 100_000
        rem %= 100_000
        thousand = rem // 1_000
        units = rem % 1_000

        parts = []
        if crore:
            parts.append(number_to_words(crore) + " Crore")
        if lakh:
            parts.append(number_to_words(lakh) + " Lakh")
        if thousand:
            parts.append(number_to_words(thousand) + " Thousand")
        if units:
            parts.append(number_to_words(units))
        return " ".join(parts)

    # रुपये और आने वाले paise को अलग करें
    rupees = paise // 100
    paise_part = paise % 100

    rupee_word = rupees_to_words(rupees)
    paise_word = number_to_words(paise_part)

    if paise_part == 0:
        return f"Rupees {rupee_word} Only"
    else:
        return f"Rupees {rupee_word} and {paise_word} Paise Only"
