def cheque_amount_words(paise: int) -> str:
    if not 0 <= paise < 1_000_000_000:
        raise ValueError

    rupee = paise // 100
    paisa = paise % 100

    number_to_words = {
        0: 'Zero', 1: 'One', 2: 'Two', 3: 'Three', 4: 'Four', 5: 'Five',
        6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine', 10: 'Ten',
        11: 'Eleven', 12: 'Twelve', 13: 'Thirteen', 14: 'Fourteen',
        15: 'Fifteen', 16: 'Sixteen', 17: 'Seventeen', 18: 'Eighteen',
        19: 'Nineteen', 20: 'Twenty', 30: 'Thirty', 40: 'Forty',
        50: 'Fifty', 60: 'Sixty', 70: 'Seventy', 80: 'Eighty', 90: 'Ninety'
    }

    def two_digit_to_words(n):
        if n == 0:
            return ''
        if n < 20:
            return number_to_words[n]
        tens, ones = divmod(n, 10)
        return f"{number_to_words[tens*10]}-{number_to_words[ones]}"

    def three_digit_to_words(n):
        if n == 0:
            return ''
        hundreds, rem = divmod(n, 100)
        words = []
        if hundreds > 0:
            words.append(f"{number_to_words[hundreds]} Hundred")
        if rem > 0:
            words.append(two_digit_to_words(rem))
        return ' '.join(words)

    def rupee_to_words(n):
        if n == 0:
            return 'Zero'

        crore, n = divmod(n, 100)
        lakh, n = divmod(n, 10)
        thousand, n = divmod(n, 10)

        parts = []
        if crore > 0:
            parts.append(f"{number_to_words[crore]} Crore")
        if lakh > 0:
            parts.append(f"{number_to_words[lakh]} Lakh")
        if thousand > 0:
            rest = thousand * 10
            if rest > 0:
                if rest >= 100:
                    parts.append(three_digit_to_words(rest))
                else:
                    parts.append(two_digit_to_words(rest))

        return ' '.join(parts)

    rupee_words = rupee_to_words(rupee)
    paisa_words = two_digit_to_words(paisa)

    result = f"Rupees {rupee_words}"
    if paisa_words:
        result += f" and {paisa_words} Paise"
    result += " Only"

    return result
