import datetime

def next_invoice_number(prev: str | None, d: datetime.date) -> str:
    # दी गई तारीख के लिए फाइनेंसियल ईयर (FY) तय करें
    if d.month < 4:
        fy_start = d.year - 1
    else:
        fy_start = d.year
    fy_end = fy_start + 1
    fy_str = f"{fy_start}-{fy_end % 100:02d}"

    # अगर कोई पिछला इनवॉइस नहीं है या FY मैच नहीं करता है, तो 0001 से शुरू करें
    if not prev or not prev.startswith("INV/"):
        seq = "0001"
    else:
        parts = prev.split("/")
        if len(parts) < 3 or parts[0] != "INV" or parts[1] != fy_str:
            seq = "0001"
        else:
            try:
                seq_num = int(parts[2])
            except ValueError:
                seq = "0001"
            else:
                seq_num += 1
                # कम से कम 4 डिजिट्स तक जीरो-पैड करें; लंबे नंबर वैसे ही दिखेंगे।
                seq = f"{seq_num:0>4}"

    return f"INV/{fy_str}/{seq}"
