import datetime
from decimal import Decimal, ROUND_HALF_UP

def advance_tax_due(total_tax: int, on_date: datetime.date) -> int:
    """
    Return the cumulative advance tax due by `on_date`.
    """
    if total_tax < 10_000:
        return 0

    # Financial year runs from 1 April to 31 March.
    # `end_year` is the calendar year in which the financial year ends.
    if on_date.month < 4:
        end_year = on_date.year
    else:
        end_year = on_date.year + 1

    due_june  = datetime.date(end_year - 1, 6, 15)
    due_sept  = datetime.date(end_year - 1, 9, 15)
    due_dec   = datetime.date(end_year - 1, 12, 15)
    due_march = datetime.date(end_year, 3, 15)

    if on_date < due_june:
        pct = 0
    elif on_date < due_sept:
        pct = 15
    elif on_date < due_dec:
        pct = 45
    elif on_date < due_march:
        pct = 75
    else:
        pct = 100

    due = (Decimal(total_tax) * Decimal(pct) / Decimal(100)).quantize(
        Decimal("0"), rounding=ROUND_HALF_UP
    )
    return int(due)
