def parse_gstin(gstin: str) -> dict | None:
    if not gstin:
        return None

    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    gstin = gstin.strip().upper()

    if len(gstin) != 15:
        return None

    state_code = gstin[0:2]
    pan = gstin[2:12]
    entity_number = gstin[12]
    check_char = gstin[14]

    if state_code not in [f"{i:02d}" for i in range(1, 39)] + ["97"]:
        return None

    if not (len(pan) == 10 and pan[0:5].isalpha() and pan[5:9].isdigit() and pan[9].isalpha()):
        return None

    if not (len(entity_number) == 1 and entity_number.isdigit() or entity_number.isalpha()):
        return None

    if check_char not in alphabet:
        return None

    total_sum = 0
    for i in range(14):
        value = alphabet.index(gstin[i])
        multiplier = 1 if i % 2 == 0 else 2
        product = value * multiplier
        total_sum += (product // 36) + (product % 36)

    check_index = (36 - (total_sum % 36)) % 36
    calculated_check = alphabet[check_index]

    if calculated_check != check_char:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number
    }
