def parse_ifsc(code: str) -> tuple[str, str] | None:
    if code is None:
        return None

    # Pehle whitespace strip karo aur uppercase karo
    code = code.strip().upper()

    # IFSC exactly 11 characters ka hona chahiye
    if len(code) != 11:
        return None

    bank_code = code[:4]
    digit = code[4]
    branch_code = code[5:]

    # Bank code: 4 letters
    if not bank_code.isalpha():
        return None

    # Digit 0
    if digit != '0':
        return None

    # Branch code: 6 letters ya digits
    if not branch_code.isalnum():
        return None

    return (bank_code, branch_code)
