        one = num % 10
        if one == 0:
            return tens[ten]
        return f"{tens[ten]}-{ones[one]}"

    def three_digits(num: int) -> str:
        if num == 0:
            return ""
        if num < 100:
            return two_digits(num)
        if num < 1000:
            hundred = num // 100
            remainder = num % 100
            if remainder == 0:
                return f"{ones[hundred]} hundred"
            return f"{ones[hundred]} hundred {two_digits(remainder)}"

    def convert(num: int) -> str:
        if num == 0:
            return ""

        if num < 1000:
            return three_digits(num)

        for i in range(6, 0, -1):
            unit = units[i]
            divisor = 10 ** (2 * i)
            if num >= divisor:
                current_unit_value = num // divisor
                remainder = num % divisor
                if remainder == 0:
                    return f"{convert(current_unit_value)} {unit}"
                return f"{convert(current_unit_value)} {unit} {convert(remainder)}"

    return convert(n).strip()
