def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    # Return 0 for invalid lines
    if not isinstance(taxable_paise, int) or taxable_paise < 0 or not isinstance(rate_pct, (int, float)):
        return {"cgst": 0, "sgst": 0, "igst": 0}
    if not isinstance(supplier_state, str) or not isinstance(place_of_supply, str):
        return {"cgst": 0, "sgst": 0, "igst": 0}

    # Convert 2-digit GST state codes to integers for comparison
    try:
        supplier_state_code = int(supplier_state.strip())
        place_of_supply_code = int(place_of_supply.strip())
    except (ValueError, TypeError):
        return {"cgst": 0, "sgst": 0, "igst": 0}

    # Determine if intra-state supply
    is_intra_state = (supplier_state_code == place_of_supply_code)

    # Calculate tax amount
    tax_amount = taxable_paise * rate_pct / 100.0

    # Round to nearest paise using round half up (do not use round())
    def round_half_up(value):
        if value >= 0:
            return int(value + 0.5)
        else:
            return int(value - 0.5)

    total_tax_rounded = round_half_up(tax_amount)

    if is_intra_state:
        # Intra-state: split equally into CGST and SGST
        cgst = round_half_up(tax_amount / 2.0)
        sgst = round_half_up(tax_amount / 2.0)
        igst = 0
    else:
        # Inter-state: full amount as IGST
        cgst = 0
        sgst = 0
        igst = total_tax_rounded

    return {"cgst": cgst, "sgst": sgst, "igst": igst}
```

