        if taxable_income > 400000:
            tax += (min(taxable_income, 800000) - 400000) * 5 // 100
        if taxable_income > 800000:
            tax += (min(taxable_income, 1200000) - 800000) * 10 // 100
        if taxable_income > 1200000:
            tax += (min(taxable_income, 1600000) - 1200000) * 15 // 100
        if taxable_income > 1600000:
            tax += (min(taxable_income, 2000000) - 1600000) * 20 // 100
        if taxable_income > 2000000:
            tax += (min(taxable_income, 2400000) - 2000000) * 25 // 100
        if taxable_income > 2400000:
            tax += (taxable_income - 2400000) * 30 // 100

    cess = tax * 4 // 100

    final_tax = tax + cess

    # Round to nearest rupee, exact halves rounded up
    rounded = (final_tax * 2 + 1) // 2

    return int(rounded)
