import math

def income_tax_new_regime(gross_salary: int) -> int:
    # स्टेप 1: Taxable income कैलकुलेट करें (75,000 standard deduction के साथ)
    taxable_income = gross_salary - 75000
    if taxable_income < 0:
        taxable_income = 0

    # स्टेप 2: Slab tax कैलकुलेट करें
    tax = 0
    if taxable_income > 400000:
        tax += (min(taxable_income, 800000) - 400000) * 0.05
    if taxable_income > 800000:
        tax += (min(taxable_income, 1200000) - 800000) * 0.10
    if taxable_income > 1200000:
        tax += (min(taxable_income, 1600000) - 1200000) * 0.15
    if taxable_income > 1600000:
        tax += (min(taxable_income, 2000000) - 1600000) * 0.20
    if taxable_income > 2000000:
        tax += (min(taxable_income, 2400000) - 2000000) * 0.25
    if taxable_income > 2400000:
        tax += (taxable_income - 2400000) * 0.30

    # स्टेप 3: Rebate अप्लाई करें (अगर taxable income <= 12,00,000 तो tax = 0)
    if taxable_income <= 1200000:
        tax = 0

    # स्टेप 4: 4% health and education cess जोड़ें
    cess = tax * 0.04
    total_tax = tax + cess

    # स्टेप 5: Round to nearest rupee, 0.5 up
    result = math.floor(total_tax + 0.5)

    return int(result)
