def is_valid_upi_id(vpa: str) -> bool:
    vpa = vpa.strip()

    if '@' not in vpa or vpa.count('@') != 1:
        return False

    local_part, domain_part = vpa.split('@')

    if not (2 <= len(local_part) <= 64):
        return False

    if not (3 <= len(domain_part) <= 32):
        return False

    if not domain_part[0].isalpha():
        return False

    if not all(c.isalnum() for c in domain_part):
        return False

    if not (local_part[0].isalnum() and local_part[-1].isalnum()):
        return False

    if '..' in local_part:
        return False

    if not all(c.isalnum() or c in ".-_" for c in local_part):
        return False

    return True
