def pincode_state(pincode: str, table: dict[str, str]) -> str | None:
    # Step 1: Remove spaces from the pincode
    cleaned_pincode = pincode.replace(" ", "")

    # Step 2: Validate the cleaned pincode
    # Must be exactly 6 ASCII digits and must not start with 0
    if len(cleaned_pincode) != 6 or not cleaned_pincode.isdigit() or cleaned_pincode.startswith("0"):
        return None

    # Step 3: Find the longest matching prefix
    matching_prefix = None

    for key in table.keys():
        if cleaned_pincode.startswith(key):
            if matching_prefix is None or len(key) > len(matching_prefix):
                matching_prefix = key

    # Step 4: Return the state if a match was found
    if matching_prefix is not None:
        return table[matching_prefix]

    return None
