import re

def parse_booking_status(status: str) -> dict | None:
    if not isinstance(status, str):
        return None

    # Strip leading/trailing whitespace and convert to uppercase
    s = status.strip().upper()

    # Remove any extra spaces
    s = re.sub(r'\s+', ' ', s)

    # Parse Confirmed status
    # Format: CNF/B2/45 or CNF/B2/45/LB
    if s.startswith('CNF'):
        parts = re.split(r'[\s/]+', s)
        if len(parts) >= 3:
            try:
                coach = parts[1]
                berth = int(parts[2])
                berth_type = parts[3] if len(parts) >= 4 else None
                return {"status": "CNF", "coach": coach, "berth": berth, "berth_type": berth_type}
            except (ValueError, IndexError):
                pass

    # Parse RAC status
    # Format: RAC 12 or RAC/12
    if s.startswith('RAC'):
        parts = re.split(r'[\s/]+', s)
        if len(parts) >= 2:
            try:
                number = int(parts[1])
                return {"status": "RAC", "number": number}
            except (ValueError, IndexError):
                pass

    # Parse Waitlist status
    # Supported: WL 34, GNWL 34, RLWL 5, PQWL 2, TQWL 9
    # Format: GNWL 34, RLWL/5, PQWL 2, TQWL 9
    # Also: WL 34
    waitlist_patterns = [
        r'^WL\s+(\d+)$',           # WL 34
        r'^(GNWL|RLWL|PQWL|TQWL)\s+(\d+)$',  # GNWL 34
        r'^(GNWL|RLWL|PQWL|TQWL)/(\d+)$'      # RLWL/5
    ]

    for pattern in waitlist_patterns:
        match = re.match(pattern, s)
        if match:
            if pattern == r'^WL\s+(\d+)$':
                list_type = "WL"
                number = int(match.group(1))
            else:
                list_type = match.group(1)
                number = int(match.group(2))

            # Validate list type
            if list_type in ("WL", "GNWL", "RLWL", "PQWL", "TQWL"):
                return {"status": "WL", "list": list_type, "number": number}

    return None
