def parse_booking_status(status: str) -> dict | None:
    # Aage aur peeche ka whitespace hatayein aur string ko normalize karein
    # Alag-alag separators (/, space/s) ko ek single space mein badlein
    normalized = status.strip()
    # Multiple spaces ya slashes ko single space mein replace karein
    while '  ' in normalized or '//' in normalized or ' / ' in normalized:
        normalized = normalized.replace('  ', ' ').replace(' // ', ' / ').replace(' / ', ' ')
        if '/ ' in normalized:
            normalized = normalized.replace('/ ', ' ')

    parts = [p for p in normalized.split(' ') if p]

    # Check for Confirmed
    if parts and parts[0].upper() == 'CNF':
        if len(parts) >= 3:
            coach = parts[1].upper()
            berth_str = parts[2]
            if berth_str.isdigit():
                berth = int(berth_str)
                # Agar extra part hai jaise LB, toh use berth_type lein
                if len(parts) >= 4:
                    berth_type = parts[3].upper()
                    return {"status": "CNF", "coach": coach, "berth": berth, "berth_type": berth_type}
                else:
                    return {"status": "CNF", "coach": coach, "berth": berth}

    # Check for RAC
    if parts and parts[0].upper() == 'RAC':
        if len(parts) >= 2:
            num_str = parts[1]
            if num_str.isdigit():
                return {"status": "RAC", "number": int(num_str)}

    # Check for Waitlist (WL forms)
    wl_list = ["WL", "GNWL", "RLWL", "PQWL", "TQWL"]
    for i, part in enumerate(parts):
        if part.upper() in wl_list:
            # List part mil gaya
            current_list = part.upper()
            # Number check karein next part mein
            if i + 1 < len(parts) and parts[i+1].isdigit():
                return {"status": "WL", "list": current_list, "number": int(parts[i+1])}
            # Agar WL bina number ke hai (jaise sirf "WL" - par spec ke hisaab se number chahiye)
            # Lekin "WL 34" mein WL pehle part mein hai, toh WL list ke liye
            # "WL" wale case mein (spec mein nahi hai par safety)
            if current_list == "WL":
                # Agar WL ke baad koi number nahi hai toh invalid
                return None

    return None
