    parts = s.rsplit(' ', 1)
    if len(parts) != 2:
        raise ValueError(f"Invalid input format: {s}")

    date_part = parts[0]
    time_part = parts[1].upper().strip()

    # Split time into components
    time_components = time_part.split(':')
    if len(time_components) != 2:
        raise ValueError(f"Invalid time format: {time_part}")

    hour_str = time_components[0].strip()
    minute_str = time_components[1].strip()

    # Extract AM/PM
    if not time_part.endswith('AM') and not time_part.endswith('PM'):
        raise ValueError(f"Invalid time format, missing AM/PM: {time_part}")

    period = time_part[-2:]

    # Split date
    date_components = date_part.split('/')
    if len(date_components) != 3:
        raise ValueError(f"Invalid date format: {date_part}")

    day_str, month_str, year_str = date_components

    # Validate all components
    if not (day_str.isdigit() and month_str.isdigit() and year_str.isdigit()):
        raise ValueError(f"Date or time contains non-numeric values: {s}")

    day = int(day_str)
    month = int(month_str)
    year = int(year_str)

    if not (1 <= month <= 12):
        raise ValueError(f"Invalid month: {month}")

    if not (1 <= day <= 31):
        raise ValueError(f"Invalid day: {day}")

    if not hour_str.isdigit():
        raise ValueError(f"Invalid hour: {hour_str}")

    hour = int(hour_str)
    if not minute_str.isdigit() or len(minute_str) != 2:
        raise ValueError(f"Invalid minute: {minute_str}")

    minute = int(minute_str)

    if not (0 <= minute <= 59):
        raise ValueError(f"Invalid minute: {minute}")

    # Convert to 24-hour format
    if period == 'AM':
        if hour == 12:
            hour_24 = 0
        elif 1 <= hour <= 9:
            hour_24 = hour
        else:
            raise ValueError(f"Invalid hour for AM: {hour}")
    else:  # PM
        if hour == 12:
            hour_24 = 12
        elif 1 <= hour <= 11:
            hour_24 = hour + 12
        else:
            raise ValueError(f"Invalid hour for PM: {hour}")

    if not (0 <= hour_24 <= 23):
        raise ValueError(f"Invalid hour: {hour_24}")

    # Create IST datetime
    try:
        ist_dt = datetime(year, month, day, hour_24, minute, 0, tzinfo=timezone(timedelta(hours=5, minutes=30)))
    except ValueError as e:
        raise ValueError(f"Invalid date/time: {s}") from e

    # Convert to UTC
    utc_dt = ist_dt.astimezone(timezone.utc)

    # Format as ISO 8601 with Z suffix
    return utc_dt.strftime("%Y-%m-%dT%H:%M:00Z")
