def card_info(number: str) -> tuple[str, bool] | None:
    # Spaces and hyphens remove करें
    cleaned = number.replace(" ", "").replace("-", "")

    # Check length: 12-19 ASCII digits
    if not (12 <= len(cleaned) <= 19):
        return None

    # Check if all characters are digits
    if not cleaned.isdigit():
        return None

    # Luhn checksum check
    def luhn_check(n: str) -> bool:
        total = 0
        reverse_digits = [int(d) for d in n[::-1]]
        for i, d in enumerate(reverse_digits):
            if i % 2 == 1:
                d *= 2
                if d > 9:
                    d -= 9
            total += d
        return total % 10 == 0

    luhn_ok = luhn_check(cleaned)

    # Network identify करें
    network = "Unknown"
    first_two = int(cleaned[:2])
    first_four = int(cleaned[:4])
    first_three = int(cleaned[:3])

    if cleaned.startswith("34") or cleaned.startswith("37"):
        network = "Amex"
    elif cleaned.startswith("4"):
        network = "Visa"
    elif first_two >= 51 and first_two <= 55:
        network = "Mastercard"
    elif 2221 <= first_four <= 2720:
        network = "Mastercard"
    elif cleaned.startswith("60") or cleaned.startswith("65") or cleaned.startswith("81") or cleaned.startswith("82") or cleaned.startswith("508"):
        network = "RuPay"

    return (network, luhn_ok)
