def normalize_mobile(s: str) -> str | None:
    # Remove spaces, hyphens, dots, and parentheses
    s = s.replace(" ", "").replace("-", "").replace(".", "").replace("(", "").replace(")", "")

    # Check if the remaining string is purely digits
    if not s.isdigit():
        return None

    # The final digits must be exactly 10
    if len(s) != 10:
        return None

    # The first digit must be 6, 7, 8, or 9
    if s[0] not in "6789":
        return None

    # Check for trunk prefix "0"
    if len(s) == 11 and s.startswith("0"):
        s = s[1:]
    # Check for country code "91"
    elif len(s) == 12 and s.startswith("91"):
        s = s[2:]
    # Check for "0091"
    elif len(s) == 13 and s.startswith("0091"):
        s = s[4:]
    # Check for "+91"
    elif len(s) == 13 and s.startswith("+91"):
        s = s[3:]
    else:
        return None

    return "+91" + s
