                rto_end = 1 if len(rest) >= 3 else 2
                rto = rest[:rto_end]
                if rto.isdigit():
                    rest = rest[rto_end:]

                    # Series: 1 से 3 letters
                    series_len = 1
                    if len(rest) >= 2:
                        series_len = 2
                    if len(rest) >= 3:
                        series_len = 3

                    series = rest[:series_len]
                    if len(series) <= 3 and series.isalpha():
                        rest = rest[series_len:]

                        # Number: 1 से 4 digits
                        if len(rest) >= 1 and len(rest) <= 4 and rest.isdigit():
                            number = rest

                            # Format को validate करें
                            if state in valid_states:
                                # RTO को 2 digits तक pad करें
                                rto_padded = rto.zfill(2)
                                # Number को 4 digits तक pad करें
                                number_padded = number.zfill(4)

                                # Check करें कि remaining का कोई extra part न हो (max length के हिसाब से)
                                if len(cleaned) == 9 and len(rest) == 4:
                                    # यह सही regular format है
