    # 3. Bharat series format try करें: 2 digits year + 2 letters "BH" + number + series
    # Pattern: \d{2}BH\d{4}[A-Z]{1,2}
    if len(cleaned) >= 8 and cleaned[2:4] == "BH":
        year_part = cleaned[:2]
