def parse_vehicle_reg(plate: str) -> dict | None:
    # Normalize the input: uppercase and remove spaces and hyphens
    normalized = plate.upper().replace(" ", "").replace("-", "")

    # Valid Indian state codes
    valid_states = {"AN", "AP", "AR", "AS", "BR", "CH", "CG", "DD", "DL", "GA", "GJ", "HP", "HR", "JH", "JK", "KA", "KL", "LA", "LD", "MH", "ML", "MN", "MP", "MZ", "NL", "OD", "PB", "PY", "RJ", "SK", "TN", "TR", "TS", "UK", "UP", "WB"}

    # Try to match Regular format: 2 letters (state), 1-2 digits (RTO), 1-3 letters (series), 1-4 digits (number)

    # Try regular format with state at position 0
    for rto_len in [1, 2]:
        if rto_len > len(normalized) - 5:
            break

        state = normalized[0:2]
        if state not in valid_states:
            continue

        rto = normalized[2:2+rto_len]
        if not rto.isdigit():
            continue

        # Try different series lengths (1 to 3 letters)
        for series_len in [1, 2, 3]:
            if 2 + rto_len + series_len >= len(normalized):
