import datetime
import re

def parse_indian_date(s: str) -> datetime.date:
    if not isinstance(s, str) or not s.strip():
        raise ValueError("Invalid date format")

    # Normalize spaces
    s = s.strip()

    # Check for year only (2-digit or 4-digit)
    year_only_match = re.fullmatch(r'(\d{2}|\d{4})\s*$', s)
    if year_only_match:
        year_str = year_match.group(1)
        year = int(year_str)
        if year < 100:
            year += 2000
            if not (2000 <= year <= 2099):
                raise ValueError("Year out of valid range (2000-2099)")
        else:
            if not (1000 <= year <= 9999):
                raise ValueError("Year must be 4 digits")

        # Default to January 1st
        return datetime.date(year, 1, 1)

    # Normalize separators to /
    normalized = re.sub(r'([.\- ])', r'/\1', s)
    # Collapse multiple spaces and normalize
    normalized = re.sub(r'/\s*/', '/', normalized)
    normalized = re.sub(r'\s*/', '/', normalized)
    normalized = normalized.strip('/')

    # Split by /
    parts = normalized.split('/')

    if len(parts) != 3:
        raise ValueError("Invalid date format")

    day_str, month_str, year_str = parts

    # Parse day
    if not re.fullmatch(r'\d{1,2}', day_str):
        raise ValueError(f"Invalid day: {day_str}")
    day = int(day_str)

    # Parse year
    if len(year_str) == 2:
        year = int(year_str)
        if not (0 <= year <= 99):
            raise ValueError("Year must be 2 digits")
        year += 2000
        if not (2000 <= year <= 2099):
            raise ValueError("Year out of valid range (2000-2099)")
    elif len(year_str) == 4:
        year = int(year_str)
        if not (1000 <= year <= 9999):
            raise ValueError("Year must be 4 digits")
    else:
        raise ValueError("Invalid year")

    # Parse month
