def parse_cin(cin: str) -> dict | None:
    """
    Indian Corporate Identification Number (CIN) validate aur parse kare.
    CIN 21 characters ka hota hai:
    1 letter "L" (listed) ya "U" (unlisted);
    5 digits industry code;
    2 letters state code;
    4 digits incorporation year (1850-2100);
    3 letters company type (PLC, PTC, GOI, SGC, FLC, GAP, NPL, ULL, ULT, OPC);
    6 digits registration number.
    """
    if not isinstance(cin, str):
        return None

    # Pehle strip aur uppercase karo
    cin = cin.strip().upper()

    # Length check
    if len(cin) != 21:
        return None

    # 1. Listed/Unlisted check
    listed = cin[0]
    if listed not in ("L", "U"):
        return None

    # 2. 5 digits industry code
    industry = cin[1:6]
    if not industry.isdigit():
        return None

    # 3. 2 letters state code
    state = cin[6:8]
    if not state.isalpha():
        return None

    # 4. 4 digits incorporation year (1850-2100)
    year = int(cin[8:12])
    if not (1850 <= year <= 2100):
        return None

    # 5. 3 letters company type
    valid_types = {"PLC", "PTC", "GOI", "SGC", "FLC", "GAP", "NPL", "ULL", "ULT", "OPC"}
    type_str = cin[12:15]
    if type_str not in valid_types:
        return None

    # 6. 6 digits registration number
    reg_no = cin[15:21]
    if not reg_no.isdigit():
        return None

    # Strip leading zeros from industry, state, and reg_no for output
    industry_clean = industry.lstrip("0")
    if industry_clean == "":
        industry_clean = "0"

    state_clean = state.lstrip("0")
    if state_clean == "":
        state_clean = "0"

    reg_no_clean = reg_no.lstrip("0")
    if reg_no_clean == "":
        reg_no_clean = "0"

    return {
        "listed": listed == "L",
        "industry": industry_clean,
        "state": state_clean,
        "year": year,
        "type": type_str,
        "reg_no": reg_no_clean
    }
