import urllib.parse

def upi_pay_link(vpa: str, name: str, amount_paise: int, note: str | None = None) -> str:
    if amount_paise <= 0:
        raise ValueError("amount_paise must be greater than 0")

    amount = f"{amount_paise / 100:.2f}"

    query = {
        "pa": vpa,
        "pn": name,
        "am": amount,
        "cu": "INR",
    }

    if note is not None and note != "":
        query["tn"] = note

    def quote(s):
        return urllib.parse.quote(str(s), safe="@")

    encoded_query = urllib.parse.urlencode(query, quote_via=quote)

    return f"upi://pay?{encoded_query}"
