def parse_indian_date(s: str) -> datetime.date:
    # Remove extra spaces
    s = s.strip()

    # Try numeric formats first: "15/08/2024", "15-08-2024", "15.08.2024", "5.9.24", "03/04/2025"
    # Pattern: day (1-2 digits), separator, month (1-2 digits), separator, year (2-4 digits)
    numeric_match = re.match(r'^(\d{1,2})([/.\-])(\d{1,2})\2(\d{2,4})$', s)
    if numeric_match:
        day = int(numeric_match.group(1))
        month = int(numeric_match.group(3))
        year = int(numeric_match.group(4))
        if len(str(year)) == 2:
            year += 2000
        if month < 1 or month > 12:
            raise ValueError(f"Invalid month: {month}")
        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"Invalid date: {s}")

    # Try space-separated formats: "1 January 2025", "15 Aug 2024"
    parts = s.split()
    if len(parts) == 3:
        day_str, month_str, year_str = parts

        # Validate year
        try:
            year = int(year_str)
        except ValueError:
            raise ValueError(f"Invalid year format: {year_str}")
        if len(year_str) == 2:
            year += 2000

        # Validate day
        if not re.match(r'^\d{1,2}$', day_str):
            raise ValueError(f"Invalid day format: {day_str}")
        day = int(day_str)

        # Parse month
        month_map = {
            'jan': 1, 'january': 1,
            'feb': 2, 'february': 2,
