            'oct': 10, 'october': 10,
            'nov': 11, 'november': 11,
            'dec': 12, 'december': 12
        }
        month_lower = month_str.lower()
        if month_lower not in month_map:
            raise ValueError(f"Invalid month: {month_str}")
        month = month_map[month_lower]

        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"Invalid date: {s}")

    # Try formats with separators and month name: "15/Aug/2024", "15-Aug-2024", "15.Aug.2024"
    # Pattern: day, separator, 3-letter or full month name, separator, year
    separator_match = re.match(r'^(\d{1,2})([/.\-])([A-Za-z]{3,9})\2(\d{2,4})$', s)
    if separator_match:
        day = int(separator_match.group(1))
        year_str = separator_match.group(4)
        year = int(year_str)
        if len(year_str) == 2:
            year += 2000

        month_str = separator_match.group(3)
        month_lower = month_str.lower()
        if month_lower not in month_map:
            raise ValueError(f"Invalid month: {month_str}")
        month = month_map[month_lower]

        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"Invalid date: {s}")

    raise ValueError(f"Invalid date format: {s}")
