import datetime

def bank_working_days(start: datetime.date, end: datetime.date, holidays: list[datetime.date]) -> int:
    if start > end:
        return 0

    count = 0
    current = start

    while current <= end:
        # Check if current date is a Saturday or Sunday
        if current.weekday() < 5:
            # Check if current date is not in holidays
            if current not in holidays:
                count += 1
        current += datetime.timedelta(days=1)

    return count
