def electricity_bill(units: int, sanctioned_load_kw: float) -> float:
    # Input validation
    if units <= 0 or sanctioned_load_kw <= 0:
        return 0.0

    # Calculate energy charge based on slabs
    energy_charge = 0.0
    remaining_units = units

    if remaining_units > 0:
        if units <= 100:
            energy_charge += units * 3.00
        else:
            energy_charge += 100 * 3.00
            remaining_units -= 100

        if remaining_units > 0:
            if units <= 200:
                energy_charge += remaining_units * 4.50
                remaining_units -= remaining_units
            else:
                energy_charge += 100 * 4.50
                remaining_units -= 100

        if remaining_units > 0:
            if units <= 500:
                energy_charge += remaining_units * 6.00
            else:
                energy_charge += 300 * 6.00
                remaining_units -= 300

        if remaining_units > 0:
            energy_charge += remaining_units * 7.50
            remaining_units -= remaining_units

    # Calculate fixed charge (round up to whole kW, minimum 1 kW)
    import math
    fixed_load_kw = math.ceil(sanctioned_load_kw)
    if fixed_load_kw < 1:
        fixed_load_kw = 1
    fixed_charge = fixed_load_kw * 50.0

    # Calculate electricity duty (5% of energy charge only)
    duty = energy_charge * 0.05

    # Total bill
    total = energy_charge + fixed_charge + duty

    # Round to 2 decimals (exact half up)
    total = round(total + 1e-9, 2)

    return float(total)
