import datetime

def next_invoice_number(prev: str | None, d: datetime.date) -> str:
    # Determine the financial year
    if d.month <= 3:
        fy_start = d.year - 1
        fy_end = d.year
    else:
        fy_start = d.year
        fy_end = d.year + 1

    # Properly format the end year with two digits
    fy_end_str = f"{fy_end % 100:02d}"
    fy_str = f"{fy_start}-{fy_end_str}"

    # If prev is None or has different FY, start from 0001
    if prev is None:
        seq = 1
    else:
        # Parse prev to extract FY
        try:
            prev_fy = prev.split("/")[1]
        except IndexError:
            prev_fy = None

        if prev_fy != fy_str:
            seq = 1
        else:
            # Extract sequence from prev
            try:
                seq_part = prev.split("/")[-1]
                seq = int(seq_part) + 1
            except (IndexError, ValueError):
                seq = 1

    # Format sequence with at least 4 digits
    seq_str = str(seq).zfill(4)

    return f"INV/{fy_str}/{seq_str}"
