import datetime

def next_invoice_number(prev: str | None, d: datetime.date) -> str:
    # Helper function to get FY (Financial Year) from a date
    def get_fy(date_obj: datetime.date) -> str:
        if date_obj.month >= 4:
            return f"{date_obj.year}-{str(date_obj.year + 1)[-2:]}"
        else:
            return f"{date_obj.year - 1}-{str(date_obj.year)[-2:]}"

    # Get current FY from the provided date
    current_fy = get_fy(d)

    # If prev is None or its FY doesn't match current FY, start with 0001
    if prev is None:
        seq = 1
    else:
        # Extract previous invoice's FY from the string
        prev_fy = prev[4:10]

        if prev_fy != current_fy:
            seq = 1
        else:
            # Extract sequence part after the last '/'
            seq_part = prev.split('/')[-1]
            # Extract numeric part
            seq = int(seq_part.split('_')[-1])

            # If sequence is 9999, reset to 1; otherwise increment
            if seq >= 9999:
                seq = 1
            else:
                seq = seq + 1

    # Format sequence with zero padding to 4 digits
    seq_str = f"{seq:04d}"

    return f"INV/{current_fy}/{seq_str}"
