def advance_tax_due(total_tax: int, on_date: datetime.date) -> int:
    """
    Return the cumulative advance tax that must have been paid by `on_date`
    for the financial year (1 April - 31 March) containing `on_date`.
    """
    if total_tax < 10_000:
        return 0

    # Financial year starts on 1 April; if on_date is before April, it belongs
    # to the preceding financial year.
    if on_date.month >= 4:
        fy_start_year = on_date.year
    else:
        fy_start_year = on_date.year - 1
    fy_start = datetime.date(fy_start_year, 4, 1)

    # Instalment dates within that financial year.
    due_june = datetime.date(fy_start.year, 6, 15)   # 15 June
    due_sept = datetime.date(fy_start.year, 9, 15)   # 15 September
    due_dec = datetime.date(fy_start.year, 12, 15)   # 15 December
    due_mar = datetime.date(fy_start.year, 3, 15)    # 15 March

    if on_date < due_june:
        return 0
    if on_date < due_sept:
        return _round_half_up(total_tax * 0.15)
    if on_date < due_dec:
        return _round_half_up(total_tax * 0.45)
    if on_date < due_mar:
        return _round_half_up(total_tax * 0.75)

    return total_tax
