        return 0

    if on_date < datetime.date(on_date.year, 6, 15):
        fraction = Fraction(0, 1)
    elif on_date < datetime.date(on_date.year, 9, 15):
        fraction = Fraction(3, 20)
    elif on_date < datetime.date(on_date.year, 12, 15):
        fraction = Fraction(9, 20)
    elif on_date < datetime.date(on_date.year, 3, 15):
        fraction = Fraction(3, 4)
    else:
        fraction = Fraction(1, 1)

