    hundred_part = (n % 1000) // 100
    last_two_digits = n % 100

    words = []

    # Process crore part
    if crore_part > 0:
        words.append(ones[crore_part] + " करोड़")

    # Process lakh part
    if lakh_part > 0:
        words.append(ones[lakh_part] + " लाख")

    # Process thousand part
    if thousand_part > 0:
        words.append(ones[thousand_part] + " हज़ार")

    # Process hundreds and last two digits
    if hundred_part > 0:
        words.append(ones[hundred_part] + " सौ")

    if last_two_digits > 0:
        if last_two_digits in tens:
            words.append(tens[last_two_digits])
        else:
            words.append(ones[last_two_digits])

    return ' '.join(words)
