        rate = rate_pct / 2
        cgst = round_half_up(taxable_paise * rate / 100)
        sgst = cgst  # They are equal
        igst = 0
    else:
        # Inter-state: IGST
        igst = round_half_up(taxable_paise * rate_pct / 100)
        cgst = 0
        sgst = 0

    return {"cgst": cgst, "sgst": sgst, "igst": igst}
