import datetime
from decimal import Decimal, ROUND_HALF_UP


def advance_tax_due(total_tax: int, on_date: datetime.date) -> int:
    """Return cumulative advance tax due in India on or by on_date."""
    if total_tax < 10000:
        return 0

    # Determine earlier calendar year of the financial year
    if on_date.month >= 4:
        fy = on_date.year
    else:
        fy = on_date.year - 1

    # Installment due dates within this financial year
    due_jun = datetime.date(fy, 6, 15)
    due_sep = datetime.date(fy, 9, 15)
    due_dec = datetime.date(fy, 12, 15)
    due_mar = datetime.date(fy + 1, 3, 15)

    if on_date < due_jun:
        return 0
    elif on_date < due_sep:
        return int((Decimal(total_tax) * Decimal("0.15")).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    elif on_date < due_dec:
        return int((Decimal(total_tax) * Decimal("0.45")).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    elif on_date < due_mar:
        return int((Decimal(total_tax) * Decimal("0.75")).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    else:
        return int(Decimal(total_tax))
