```python
import re

def parse_indian_amount(s: str) -> int:
    s = s.strip()
    # Remove leading currency marker
    currency_pattern = re.compile(r'^(?:₹|Rs\.?|INR)\s*', re.IGNORECASE)
    s = currency_pattern.sub('', s)

    # Remove commas and spaces
    s = s.replace(',', '').replace(' ', '')

    # Match number and unit
    match = re.fullmatch(r'(\d+(?:\.\d+)?)\s*(crore|crores|cr|lakh|lakhs|lac|lacs|l|k|thousand)', s, re.IGNORECASE)
    if not match:
        # If no unit, check if it's just a number
        if re.fullmatch(r'\d+(?:\.\d+)?', s):
            return int(round(float(s)))
        else:
            raise ValueError("Invalid format")

    number_str, unit = match.groups()
    number = float(number_str)

    unit = unit.lower()
    if unit in ['crore', 'crores', 'cr']:
        multiplier = 10**7
    elif unit in ['lakh', 'lakhs', 'lac', 'lacs', 'l']:
        multiplier = 10**5
    elif unit in ['k', 'thousand']:
        multiplier = 10**3
    else:
        raise ValueError("Unknown unit")

    return int(round(number * multiplier))
