import re
from datetime import date

def parse_indian_date(s: str) -> date:
    # Define regex pattern for day, month, year
    # Day: 1-31
    # Month: 1-12 as number, or 3-letter/fully spelled month name (case-insensitive)
    # Year: 4-digit or 2-digit (interpreted as 20xx)
    pattern = r"""
        ^\s*
        (?P<day>\d{1,2})\s*[-/. ]\s*
        (?P<month>(?:\d{1,2})|(?i:[a-zA-Z]{3,9}))\s*[-/. ]\s*
        (?P<year>\d{1,4})
        \s*$
    """
    match = re.fullmatch(pattern, s, re.VERBOSE)
    if not match:
        raise ValueError("Invalid date format")

    day_str = match.group('day')
    month_str = match.group('month')
    year_str = match.group('year')

    # Parse day
    try:
        day = int(day_str)
    except ValueError:
        raise ValueError("Invalid day")

    # Parse month
    month = None
    if re.fullmatch(r'\d{1,2}', month_str):
        try:
            month = int(month_str)
        except ValueError:
            raise ValueError("Invalid month")
    else:
        # Convert month name to number
        month_name = month_str.lower()
        if month_name in ['jan', 'january']:
            month = 1
        elif month_name in ['feb', 'february']:
            month = 2
        elif month_name in ['mar', 'march']:
            month = 3
        elif month_name in ['apr', 'april']:
            month = 4
        elif month_name in ['may', 'may']:
            month = 5
        elif month_name in ['jun', 'june']:
            month = 6
        elif month_name in ['jul', 'july']:
            month = 7
        elif month_name in ['aug', 'august']:
            month = 8
        elif month_name in ['sep', 'september']:
            month = 9
        elif month_name in ['oct', 'october']:
            month = 10
        elif month_name in ['nov', 'november']:
            month = 11
        elif month_name in ['dec', 'december']:
            month = 12
        else:
            raise ValueError("Invalid month name")

    # Parse year
    try:
        year = int(year_str)
    except ValueError:
        raise ValueError("Invalid year")

    # Handle 2-digit year (20xx)
    if 0 <= year <= 99:
        year += 2000

    # Validate day, month, year
    if not (1 <= month <= 12):
        raise ValueError("Invalid month")
    if not (1 <= day <= 31):
        raise ValueError("Invalid day")
    if not (1900 <= year <= 2100):
        raise ValueError("Invalid year")

    # Check if the date is valid
    try:
        return date(year, month, day)
    except ValueError:
        raise ValueError("Invalid date")
