def cheque_amount_words(paise: int) -> str:
    if paise < 0:
        raise ValueError("Paise cannot be negative.")

    # Define word mappings
    ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine']
    teens = ['Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']
    tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety']
    scales = ['', 'Thousand', 'Lakh', 'Crore']

    def convert_less_than_hundred(n: int) -> str:
        if n < 10:
            return ones[n]
        elif 10 <= n < 20:
            return teens[n - 10]
        else:
            ten_digit = n // 10
            one_digit = n % 10
            if one_digit == 0:
                return tens[ten_digit]
            else:
                return f"{tens[ten_digit]}-{ones[one_digit]}"

    def convert_less_than_thousand(n: int) -> str:
        if n == 0:
            return ''
        elif n < 100:
            return convert_less_than_hundred(n)
        else:
            hundred_digit = n // 100
            remainder = n % 100
            if remainder == 0:
                return f"{ones[hundred_digit]} Hundred"
            else:
                return f"{ones[hundred_digit]} Hundred {convert_less_than_hundred(remainder)}"

    def convert_amount(n: int) -> str:
        if n == 0:
            return 'Zero'
        words = []
        scale_index = 0
        while n > 0:
            chunk = n % 1000
            if chunk != 0:
                chunk_words = convert_less_than_thousand(chunk)
                if scale_index > 0:
                    chunk_words += ' ' + scales[scale_index]
                words.append(chunk_words)
            n //= 1000
            scale_index += 1
        return ' '.join(reversed(words))

    rupees = paise // 100
    paisa = paise % 100

    rupees_words = convert_amount(rupees)
    paisa_words = convert_less_than_hundred(paisa) if paisa != 0 else 'Zero'

    if paisa == 0:
        return f"Rupees {rupees_words} Only"
    else:
        return f"Rupees {rupees_words} and {paisa_words} Paise Only"
