import re


def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    s = gstin.strip().upper()
    if len(s) != 15:
        return None

    # Structure: 2 digits state, 5 letters, 4 digits, 1 letter (PAN),
    # 1 entity char, 'Z', 1 check char
    if not re.fullmatch(r"\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]", s):
        return None

    state_code = s[:2]
    if not (1 <= int(state_code) <= 38 or state_code == "97"):
        return None

    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    total = 0
    for i, ch in enumerate(s[:14]):
        value = alphabet.index(ch)
        product = value * (1 if i % 2 == 0 else 2)
        total += (product // 36) + (product % 36)

    expected_check = alphabet[(36 - total % 36) % 36]
    if s[14] != expected_check:
        return None

    return {
        "state_code": state_code,
        "pan": s[2:12],
        "entity_number": s[12],
    }
