def inr_words_en(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must satisfy 0 <= n < 1,000,000,000")
    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
    ]

    def two_digit(x: int) -> str:
        if x < 20:
            return ones[x]
        t, o = divmod(x, 10)
        if o == 0:
            return tens[t]
        return f"{tens[t]}-{ones[o]}"

    def three_digit(x: int) -> str:
        h, rest = divmod(x, 100)
        parts = []
        if h:
            parts.append(f"{ones[h]} hundred")
        if rest:
            parts.append(two_digit(rest))
        return " ".join(parts)

    groups = [
        (10_000_000, "crore"),
        (100_000, "lakh"),
        (1_000, "thousand"),
    ]

    words = []
    remaining = n
    for value, name in groups:
        q, remaining = divmod(remaining, value)
        if q:
            words.append(f"{three_digit(q) if q >= 100 else two_digit(q)} {name}")

    if remaining:
