import datetime


def fy_quarter(d: datetime.date) -> tuple[str, str]:
    # Financial year starts in April. Dates Jan-Mar belong to the previous FY's start year.
    if d.month >= 4:
        start_year = d.year
    else:
        start_year = d.year - 1
    end_year_suffix = (start_year + 1) % 100
    label = f"FY{start_year}-{end_year_suffix:02d}"

    # Quarter mapping based on month
    if 4 <= d.month <= 6:
        quarter = "Q1"
    elif 7 <= d.month <= 9:
        quarter = "Q2"
    elif 10 <= d.month <= 12:
        quarter = "Q3"
    else:
        quarter = "Q4"

    return label, quarter
