from decimal import Decimal, ROUND_HALF_UP


def _round_half_up(value: Decimal) -> int:
    """Round a Decimal to the nearest integer, with exact halves rounded up."""
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    taxable = Decimal(taxable_paise)
    # Convert via str to avoid float binary representation errors (e.g. 0.1 -> 0.1000000000000000055...)
    rate = Decimal(str(rate_pct))

    if supplier_state == place_of_supply:
        half_rate = rate / 2
        cgst = _round_half_up(taxable * half_rate / 100)
        sgst = _round_half_up(taxable * half_rate / 100)
        return {"cgst": cgst, "sgst": sgst, "igst": 0}

    igst = _round_half_up(taxable * rate / 100)
    return {"cgst": 0, "sgst": 0, "igst": igst}
