from decimal import Decimal, ROUND_HALF_UP


def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    """
    Compute GST split on a taxable value in paise.

    Returns:
        {
            "cgst": int,  # in paise
            "sgst": int,  # in paise
            "igst": int,  # in paise
        }
    """
    taxable = Decimal(taxable_paise)
    rate = Decimal(str(rate_pct))

    def round_half_up_to_int(x: Decimal) -> int:
        return int(x.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    if supplier_state == place_of_supply:
        half_rate = rate / Decimal("2")
        tax = taxable * half_rate / Decimal("100")
        amt = round_half_up_to_int(tax)
        return {"cgst": amt, "sgst": amt, "igst": 0}
    else:
        tax = taxable * rate / Decimal("100")
        amt = round_half_up_to_int(tax)
        return {"cgst": 0, "sgst": 0, "igst": amt}
