def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    if months <= 0:
        raise ValueError("months 0 se zyada hone chahiye")
    if principal < 0:
        raise ValueError("principal negative nahi ho sakta")
    if annual_rate_pct < 0:
        raise ValueError("rate negative nahi ho sakta")

    if annual_rate_pct == 0:
        result = principal / months
    else:
        r = annual_rate_pct / 12 / 100
        factor = (1 + r) ** months
        result = principal * r * factor / (factor - 1)

    return round(result, 2)
