        return False

    vpa = vpa.strip()

    # Exactly one "@"
    if vpa.count("@") != 1:
        return False

    local, handle = vpa.split("@", 1)

    # Validate local part: 2 to 64 chars, allowed chars only,
    # starts/ends with alphanumeric, no consecutive dots.
    if not (2 <= len(local) <= 64):
        return False
    if not re.fullmatch(r"[A-Za-z0-9._-]+", local):
        return False
    if not (local[0].isalnum() and local[-1].isalnum()):
        return False
    if ".." in local:
        return False

    # Validate handle: 3 to 32 chars, letters/digits only, starts with a letter.
    if not (3 <= len(handle) <= 32):
        return False
    if not re.fullmatch(r"[A-Za-z][A-Za-z0-9]{2,31}", handle):
        return False

    return True
