def indic_digits_to_ascii(text: str) -> str:
    # Unicode decimal digits for the specified Indian scripts:
    # Devanagari, Bengali, Gurmukhi, Gujarati, Odia, Tamil, Telugu, Kannada, Malayalam
    digit_ranges = (
        (0x0966, 0x096F),  # Devanagari
        (0x09E6, 0x09EF),  # Bengali
        (0x0A66, 0x0A6F),  # Gurmukhi
        (0x0AE6, 0x0AEF),  # Gujarati
        (0x0B66, 0x0B6F),  # Odia
        (0x0BE6, 0x0BEF),  # Tamil
        (0x0C66, 0x0C6F),  # Telugu
        (0x0CE6, 0x0CEF),  # Kannada
        (0x0D66, 0x0D6F),  # Malayalam
    )

    def convert_char(ch: str) -> str:
        code = ord(ch)
        for start, end in digit_ranges:
            if start <= code <= end:
                return chr(ord("0") + (code - start))
        return ch

    return "".join(convert_char(ch) for ch in text)
