import re


def parse_booking_status(status: str) -> dict | None:
    if not isinstance(status, str):
        return None

    text = status.strip().upper()
    if not text:
        return None

    # Split on "/" or one-or-more whitespace characters
    parts = [p for p in re.split(r"\s*/\s*|\s+", text) if p]
    if not parts:
        return None

    head = parts[0]

    # Confirmed: CNF/<coach>/<berth>[/<berth_type>]
    if head == "CNF":
        if len(parts) not in (3, 4):
            return None
        coach = parts[1]
        berth_str = parts[2]
        if not berth_str.isdigit():
            return None
        berth_type = parts[3] if len(parts) == 4 else None
        return {
            "status": "CNF",
            "coach": coach,
            "berth": int(berth_str),
            "berth_type": berth_type,
        }

    # RAC: RAC <n> or RAC/<n>
    if head == "RAC":
        if len(parts) != 2:
            return None
        number_str = parts[1]
        if not number_str.isdigit():
            return None
        return {"status": "RAC", "number": int(number_str)}

    # Waitlist: WL, GNWL, RLWL, PQWL, TQWL followed by a number
    if head in ("WL", "GNWL", "RLWL", "PQWL", "TQWL"):
        if len(parts) != 2:
            return None
        number_str = parts[1]
        if not number_str.isdigit():
            return None
        return {"status": "WL", "list": head, "number": int(number_str)}

    return None
