import re

_CONFIRMED_RE = re.compile(
    r"^CNF[\s/]+([A-Z0-9]+)[\s/]+(\d+)(?:[\s/]+([A-Z]+))?$"
)
_RAC_RE = re.compile(r"^RAC[\s/]+(\d+)$")
_WL_RE = re.compile(r"^(WL|GNWL|RLWL|PQWL|TQWL)[\s/]+(\d+)$")


def parse_booking_status(status: str) -> dict | None:
    if not isinstance(status, str):
        return None

    text = status.strip().upper()
    if not text:
        return None

    m = _CONFIRMED_RE.match(text)
    if m:
        coach, berth, berth_type = m.group(1), m.group(2), m.group(3)
        return {
            "status": "CNF",
            "coach": coach,
            "berth": int(berth),
            "berth_type": berth_type,
        }

    m = _RAC_RE.match(text)
    if m:
        return {"status": "RAC", "number": int(m.group(1))}

    m = _WL_RE.match(text)
    if m:
        return {"status": "WL", "list": m.group(1), "number": int(m.group(2))}

    return None
