import re
from datetime import datetime, timedelta, timezone

_IST = timezone(timedelta(hours=5, minutes=30))
_PATTERN = re.compile(
    r"^\s*(\d{2})/(\d{2})/(\d{4})\s+(\d{1,2}):(\d{2})\s*([AaPp][Mm])\s*$"
)


def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    m = _PATTERN.match(s)
    if not m:
        raise ValueError(f"invalid format: {s!r}")

    day, month, year, hour, minute, meridiem = m.groups()
    day, month, year = int(day), int(month), int(year)
    hour, minute = int(hour), int(minute)
    meridiem = meridiem.upper()

    if not (1 <= hour <= 12):
        raise ValueError(f"invalid hour: {hour}")
    if not (0 <= minute <= 59):
        raise ValueError(f"invalid minute: {minute}")

    # 12-घंटे से 24-घंटे में बदलना
    if meridiem == "AM":
        hour24 = 0 if hour == 12 else hour
    else:  # PM
        hour24 = 12 if hour == 12 else hour + 12

    try:
        local_dt = datetime(year, month, day, hour24, minute, tzinfo=_IST)
    except ValueError as exc:
        raise ValueError(f"invalid date/time: {s!r}") from exc

    utc_dt = local_dt.astimezone(timezone.utc)
    return utc_dt.strftime("%Y-%m-%dT%H:%M:00Z")
