import re


def card_info(number: str) -> tuple[str, bool] | None:
    cleaned = number.replace(" ", "").replace("-", "")

    if not re.fullmatch(r"[0-9]{12,19}", cleaned):
        return None

    if cleaned.startswith(("34", "37")):
        network = "Amex"
    elif cleaned.startswith("4"):
        network = "Visa"
    elif (51 <= int(cleaned[:2]) <= 55) or (2221 <= int(cleaned[:4]) <= 2720):
        network = "Mastercard"
    elif cleaned.startswith(("60", "65", "81", "82", "508")):
        network = "RuPay"
    else:
        network = "Unknown"

    # Luhn checksum: double every second digit from the right
    total = 0
    for i, ch in enumerate(reversed(cleaned)):
        digit = int(ch)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    luhn_ok = total % 10 == 0

    return (network, luhn_ok)
