import re
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation


_CURRENCY_PREFIX = re.compile(r"^(?:₹|rs\.?|inr)", re.IGNORECASE)

_UNITS = [
    (("crores", "crore", "cr"), 10_000_000),
    (("lakhs", "lakh", "lacs", "lac", "l"), 100_000),
    (("thousand", "k"), 1_000),
]


def parse_indian_amount(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    text = s.strip()
    text = _CURRENCY_PREFIX.sub("", text, count=1).strip()
    text = text.replace(",", "").replace(" ", "")

    multiplier = 1
    lowered = text.lower()
    for names, value in _UNITS:
        matched = False
        for name in names:
            if lowered.endswith(name):
                number_part = text[: len(text) - len(name)]
                if number_part and re.fullmatch(r"\d+(?:\.\d+)?|\.\d+", number_part):
                    text = number_part
                    multiplier = value
                    matched = True
                break
        if matched:
            break

    if not re.fullmatch(r"\d+(?:\.\d+)?|\.\d+", text):
        raise ValueError(f"Cannot parse amount: {s!r}")

    try:
        amount = Decimal(text) * multiplier
    except InvalidOperation as exc:
        raise ValueError(f"Cannot parse amount: {s!r}") from exc

    return int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
