```python
import re
from decimal import Decimal, ROUND_HALF_UP

def parse_indian_amount(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    text = s.strip()
    if not text:
        raise ValueError("Cannot parse empty amount")

    # Remove leading currency marker if present
    currency_re = re.compile(r'^(₹|rs\.?|inr)\s*', re.IGNORECASE)
    text = currency_re.sub('', text, count=1).strip()

    # Remove commas and spaces anywhere
    text = text.replace(',', '').replace(' ', '')

    if not text:
        raise ValueError("Cannot parse empty amount")

    m = re.fullmatch(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))(?:([a-zA-Z]+))?', text)
    if not m:
        raise ValueError(f"Cannot parse amount: {s!r}")

    number_str, unit_str = m.groups()
    try:
        value = Decimal(number_str)
    except Exception as e:
        raise ValueError(f"Cannot parse amount: {s!r}") from e

    multiplier = Decimal(1)
    if unit_str:
        unit = unit_str.lower()
        if unit in {"crore", "crores", "cr"}:
            multiplier = Decimal("10000000")
        elif unit in {"lakh", "lakhs", "lac", "lacs", "l"}:
            multiplier = Decimal("100000")
        elif unit in {"k", "thousand"}:
            multiplier = Decimal("1000")
        else:
            raise ValueError(f"Cannot parse amount: {s!r}")

    rupees = (value * multiplier).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    return int(rupees)
