import datetime
import re

_MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10,
    "november": 11, "december": 12,
}

_DATE_PATTERN = re.compile(
    r"""
    ^\s*
    (?P<day>\d{1,2})
    \s*[/\-. ]\s*
    (?P<month>\d{1,2}|[A-Za-z]+)
    \s*[/\-. ]\s*
    (?P<year>\d{4}|\d{2})
    \s*$
    """,
    re.VERBOSE,
)


def parse_indian_date(s: str) -> datetime.date:
    if not isinstance(s, str):
        raise ValueError("Date must be a string")

    match = _DATE_PATTERN.match(s)
    if not match:
        raise ValueError(f"Invalid date format: {s!r}")

    day_str = match.group("day")
    month_str = match.group("month")
    year_str = match.group("year")

    if month_str.isdigit():
        if len(month_str) > 2:
            raise ValueError(f"Invalid month: {month_str!r}")
        month = int(month_str)
    else:
        month = _MONTHS.get(month_str.lower())
        if month is None:
            raise ValueError(f"Invalid month name: {month_str!r}")

    if len(year_str) == 2:
        year = 2000 + int(year_str)
    else:
        year = int(year_str)
        if not (2000 <= year <= 2099):
            raise ValueError(f"Year out of supported range: {year}")

    try:
        return datetime.date(year, month, int(day_str))
    except ValueError as exc:
        raise ValueError(f"Invalid date: {s!r}") from exc
