import re


_VALID_TYPES = {"PLC", "PTC", "GOI", "SGC", "FLC", "GAP", "NPL", "ULL", "ULT", "OPC"}

_CIN_PATTERN = re.compile(
    r"^([LU])(\d{5})([A-Z]{2})(\d{4})([A-Z]{3})(\d{6})$"
)


def parse_cin(cin: str) -> dict | None:
    if not isinstance(cin, str):
        return None

    cin = cin.strip().upper()
    if len(cin) != 21:
        return None

    match = _CIN_PATTERN.match(cin)
    if not match:
        return None

    listed_flag, industry, state, year_str, company_type, reg_no = match.groups()

    year = int(year_str)
    if not (1850 <= year <= 2100):
        return None

    if company_type not in _VALID_TYPES:
        return None

    return {
        "listed": listed_flag == "L",
        "industry": industry,
        "state": state,
        "year": year,
        "type": company_type,
        "reg_no": reg_no,
    }
