import datetime


def bank_working_days(start: datetime.date, end: datetime.date, holidays: list[datetime.date]) -> int:
    if start > end:
        return 0

    holiday_set = set(holidays)
    count = 0
    current = start
    one_day = datetime.timedelta(days=1)

    while current <= end:
        weekday = current.weekday()  # Monday=0, ..., Saturday=5, Sunday=6
        if weekday == 6:
            # रविवार: बैंक बंद
            pass
        elif weekday == 5:
            # शनिवार: महीने का कौन सा शनिवार है (1-आधारित)
            saturday_number = (current.day - 1) // 7 + 1
            # दूसरा और चौथा शनिवार बंद; पहला, तीसरा, पाँचवाँ कामकाजी
            if saturday_number not in (2, 4) and current not in holiday_set:
                count += 1
        else:
            if current not in holiday_set:
                count += 1
        current += one_day

    return count
