def cheque_amount_words(paise: int) -> str:
    if not isinstance(paise, int) or isinstance(paise, bool):
        raise TypeError("paise must be an integer")
    if paise < 0:
        raise ValueError("amount must be non-negative")

    rupees, paise_part = divmod(paise, 100)
    if rupees >= 1_000_000_000:
        raise ValueError("rupees must be less than 1,000,000,000")

    ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
            "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
            "Seventeen", "Eighteen", "Nineteen"]
    tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]

    def two_digit(n: int) -> str:
        if n < 20:
            return ones[n]
        t, o = divmod(n, 10)
        if o == 0:
            return tens[t]
        return f"{tens[t]}-{ones[o]}"

    def three_digit(n: int) -> str:
        h, rest = divmod(n, 100)
        parts = []
        if h:
            parts.append(f"{ones[h]} Hundred")
        if rest:
            parts.append(two_digit(rest))
        return " ".join(parts)

    def number_words(n: int) -> str:
        if n == 0:
            return "Zero"
        # Indian grouping: last 3 digits, then 2-digit groups
        groups = []
        groups.append(n % 1000)
        n //= 1000
        scale_names = ["", "Thousand", "Lakh", "Crore"]
        scales = []
        idx = 0
        while n > 0:
            if idx == 0:
                chunk = n % 100
                n //= 100
            else:
                chunk = n % 100
                n //= 100
            groups.append(chunk)
            idx += 1
        # groups[0] = hundreds group (0-999), groups[1] = thousands (0-99), etc.
        words = []
        for i in range(len(groups) - 1, -1, -1):
            g = groups[i]
            if g == 0:
                continue
            if i == 0:
                text = three_digit(g)
            else:
                text = two_digit(g)
            if i < len(scale_names):
                scale = scale_names[i]
                if i == 0:
                    words.append(text)
                else:
                    words.append(f"{text} {scale}")
            else:
                words.append(text)
        # Handle: thousands group must be 0-99 (already), lakh 0-99, crore 0-99
        return " ".join(words)

    rupee_words = number_words(rupees)
    if paise_part == 0:
        return f"Rupees {rupee_words} Only"
    paise_words = two_digit(paise_part)
    return f"Rupees {rupee_words} and {paise_words} Paise Only"
