```python
def cheque_amount_words(paise: int) -> str:
    """
    Convert an amount in paise to words in the Indian numbering system.

    Format:
    - "Rupees <rupee words> Only" if paise part is 0
    - "Rupees <rupee words> and <paise words> Paise Only" otherwise
    """

    if not isinstance(paise, int):
        raise TypeError("paise must be an integer")
    if paise < 0:
        raise ValueError("paise must be non-negative")

    def two_digit_words(n: int) -> str:
        ones = [
            "Zero", "One", "Two", "Three", "Four", "Five",
            "Six", "Seven", "Eight", "Nine"
        ]
        teens = [
            "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen",
            "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"
        ]
        tens = [
            "", "", "Twenty", "Thirty", "Forty", "Fifty",
            "Sixty", "Seventy", "Eighty", "Ninety"
        ]

        if n < 10:
            return ones[n]
        if n < 20:
            return teens[n - 10]
        t, o = divmod(n, 10)
        if o == 0:
            return tens[t]
        return f"{tens[t]}-{ones[o]}"

    def three_digit_words(n: int) -> str:
        if n == 0:
            return ""
        if n < 100:
            return two_digit_words(n)
        h, rem = divmod(n, 100)
        if rem == 0:
            return f"{two_digit_words(h)} Hundred"
        return f"{two_digit_words(h)} Hundred {two_digit_words(rem)}"

    def number_to_words(n: int) -> str:
        if n == 0:
            return "Zero"

        parts = []

        crore, n = divmod(n, 10000000)
        lakh, n = divmod(n, 100000)
        thousand, n = divmod(n, 1000)
        hundred_and_below = n

        if crore:
            parts.append(f"{number_to_words(crore)} Crore")
        if lakh:
            parts.append(f"{number_to_words(lakh)} Lakh")
        if thousand:
            parts.append(f"{number_to_words(thousand)} Thousand")
        if hundred_and_below:
            parts.append(three_digit_words(hundred_and_below))

        return " ".join(parts)

    rupees, paise_part = divmod(paise, 100)

    if rupees >= 1_000_000_000:
        raise ValueError("rupee part must be less than 1,000,000,000")

    rupee_words = number_to_words(rupees)

    if paise_part == 0:
        return f"Rupees {rupee_words} Only"
    paise_words = number_to_words(paise_part)
    return f"Rupees {rupee_words} and {paise_words} Paise Only"
