from decimal import Decimal, ROUND_HALF_UP


def _strip_zeros(s: str) -> str:
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


def _indian_group(n: int) -> str:
    s = str(n)
    if len(s) <= 3:
        return s
    head, tail = s[:-3], s[-3:]
    parts = []
    while len(head) > 2:
        parts.insert(0, head[-2:])
        head = head[:-2]
    if head:
        parts.insert(0, head)
    return ",".join(parts) + "," + tail


def format_compact_inr(rupees: int) -> str:
    sign = "-" if rupees < 0 else ""
    value = abs(int(rupees))

    if value >= 10_000_000:
        unit, divisor = " Cr", 10_000_000
    elif value >= 100_000:
        unit, divisor = " L", 100_000
    else:
        return sign + _indian_group(value)

    rounded = (Decimal(value) / Decimal(divisor)).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )
    return sign + _strip_zeros(format(rounded, "f")) + unit
