from decimal import Decimal, ROUND_HALF_UP


def format_compact_inr(rupees: int) -> str:
    sign = "-" if rupees < 0 else ""
    amount = abs(rupees)

    def _compact(value: Decimal, unit: str) -> str:
        rounded = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        text = format(rounded, "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        return f"{sign}{text} {unit}"

    def _group_indian(n: int) -> str:
        s = str(n)
        if len(s) <= 3:
            return s
        head, tail = s[:-3], s[-3:]
        parts = []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        return ",".join(parts) + "," + tail

    if amount >= 10_000_000:
        return _compact(Decimal(amount) / Decimal(10_000_000), "Cr")

    if amount >= 100_000:
        lakh_value = Decimal(amount) / Decimal(100_000)
        # 9999999 -> "100 L": if rounding reaches 100 L, the spec keeps "L" unit
        return _compact(lakh_value, "L")

    return f"{sign}{_group_indian(amount)}"
