def cheque_amount_words(paise: int) -> str:
    """
    Convert an amount in paise to Indian cheque words.

    Rules:
    - Rupees part must be < 1,000,000,000
    - If paise part is 0: "Rupees <rupee words> Only"
    - Else: "Rupees <rupee words> and <paise words> Paise Only"
    - Capitalized words
    - Use hyphen for 21-99 non-multiples of 10, e.g. Forty-Two
    - No "and" inside number words
    - 0 => Zero
    """
    if not isinstance(paise, int):
        raise TypeError("paise must be an int")
    if paise < 0:
        raise ValueError("paise must be non-negative")

    rupees, paise_part = divmod(paise, 100)
    if rupees >= 1_000_000_000:
        raise ValueError("rupee part must be less than 1,000,000,000")

    ones = [
        "Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven",
        "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen",
        "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"
    ]
    tens = [
        "", "", "Twenty", "Thirty", "Forty", "Fifty",
        "Sixty", "Seventy", "Eighty", "Ninety"
    ]

    def under_100(n: int) -> str:
        if n < 20:
            return ones[n]
        t, r = divmod(n, 10)
        return tens[t] if r == 0 else f"{tens[t]}-{ones[r]}"

    def under_1000(n: int) -> str:
        if n < 100:
            return under_100(n)
        h, r = divmod(n, 100)
        return f"{ones[h]} Hundred" if r == 0 else f"{ones[h]} Hundred {under_100(r)}"

    def indian_number_words(n: int) -> str:
        if n == 0:
            return "Zero"

        parts = []
        crore, n = divmod(n, 10_000_000)
        lakh, n = divmod(n, 100_000)
        thousand, n = divmod(n, 1_000)
        rest = n

        if crore:
            parts.append(f"{under_1000(crore)} Crore")
        if lakh:
            parts.append(f"{under_1000(lakh)} Lakh")
        if thousand:
            parts.append(f"{under_1000(thousand)} Thousand")
        if rest:
            parts.append(under_1000(rest))

        return " ".join(parts)

    rupee_words = indian_number_words(rupees)

    if paise_part == 0:
        return f"Rupees {rupee_words} Only"
    return f"Rupees {rupee_words} and {under_100(paise_part)} Paise Only"
```

