from decimal import Decimal, ROUND_HALF_UP

def format_compact_inr(rupees: int) -> str:
    """
    Format an INR amount compactly for Indian news/dashboard style display.

    Rules:
    - abs(amount) >= 1,00,00,000: show in crores with suffix " Cr"
    - abs(amount) >= 1,00,000: show in lakhs with suffix " L"
    - otherwise: show with Indian digit grouping
    - Rounding is half-up to 2 decimals for crore/lakh
    - Remove trailing zeros and trailing decimal point
    - Negative values get a leading "-"
    """
    sign = "-" if rupees < 0 else ""
    amount = abs(rupees)

    def _fmt_scaled(value: int, divisor: int, suffix: str) -> str:
        scaled = Decimal(value) / Decimal(divisor)
        rounded = scaled.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        text = format(rounded, "f").rstrip("0").rstrip(".")
        return f"{sign}{text} {suffix}"

    def _fmt_indian_grouping(value: int) -> str:
        s = str(value)
        if len(s) <= 3:
            return f"{sign}{s}"
        last3 = s[-3:]
        rest = s[:-3]
        groups = []
        while len(rest) > 2:
            groups.append(rest[-2:])
            rest = rest[:-2]
        if rest:
            groups.append(rest)
        return f"{sign}{','.join(reversed(groups))},{last3}"

    if amount >= 10_000_000:
        return _fmt_scaled(amount, 10_000_000, "Cr")
    elif amount >= 100_000:
        return _fmt_scaled(amount, 100_000, "L")
    else:
        return _fmt_indian_grouping(amount)
