def gstin_check_char(first14: str) -> str:
    ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    INDEX = {ch: i for i, ch in enumerate(ALPHABET)}

    if not isinstance(first14, str):
        raise ValueError("Input must be a string of exactly 14 characters.")
    if len(first14) != 14:
        raise ValueError("Input must be exactly 14 characters long.")

    total = 0
    for i, ch in enumerate(first14):
        if ch not in INDEX:
            raise ValueError(f"Invalid character {ch!r} at position {i}; only uppercase A-Z and 0-9 are allowed.")
        value = INDEX[ch]
        factor = 1 if i % 2 == 0 else 2
        product = value * factor
        total += (product // 36) + (product % 36)

    check_value = (36 - total % 36) % 36
    return ALPHABET[check_value]
