    def get_two_digits(val: int) -> str:
        if val < 20:
            return ones[val]
        t, o = divmod(val, 10)
        if o == 0:
            return tens[t]
        return f"{tens[t]}-{ones[o]}"

    parts = []

    crores, n = divmod(n, 10000000)
    lakhs, n = divmod(n, 100000)
    thousands, n = divmod(n, 1000)
    hundreds, n = divmod(n, 100)

    if crores > 0:
        parts.append(get_two_digits(crores))
        parts.append("crore")
    if lakhs > 0:
        parts.append(get_two_digits(lakhs))
        parts.append("lakh")
    if thousands > 0:
        parts.append(get_two_digits(thousands))
        parts.append("thousand")
    if hundreds > 0:
        parts.append(get_two_digits(hundreds))
        parts.append("hundred")
    if n > 0:
        parts.append(get_two_digits(n))

