import re

_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
_GSTIN_PATTERN = re.compile(
    r"(?P<state_code>[0-9]{2})"
    r"(?P<pan>[A-Z]{5}[0-9]{4}[A-Z])"
    r"(?P<entity_number>[1-9A-Z])"
    r"Z"
    r"(?P<check>[0-9A-Z])"
)


def _valid_state_code(code: str) -> bool:
    if code == "97":
        return True
    return code.isdigit() and 1 <= int(code) <= 38 and len(code) == 2


def _check_character(first14: str) -> str:
    total = 0
    for i, ch in enumerate(first14):
        value = _ALPHABET.index(ch)
        factor = 1 if i % 2 == 0 else 2
        product = value * factor
        total += product // 36 + product % 36
    return _ALPHABET[(36 - total % 36) % 36]


def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    gstin = gstin.strip().upper()
    if len(gstin) != 15:
        return None

    match = _GSTIN_PATTERN.fullmatch(gstin)
    if match is None:
        return None

    state_code = match.group("state_code")
    if not _valid_state_code(state_code):
        return None

    if _check_character(gstin[:14]) != gstin[14]:
        return None

    return {
        "state_code": state_code,
        "pan": match.group("pan"),
        "entity_number": match.group("entity_number"),
    }
