def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    gstin = gstin.strip().upper()
    if len(gstin) != 15:
        return None

    valid_state_codes = {f"{i:02d}" for i in range(1, 39)} | {"97"}
    state_code = gstin[:2]
    if state_code not in valid_state_codes:
        return None

    pan = gstin[2:12]
    if not (
        all("A" <= ch <= "Z" for ch in pan[:5])
        and all("0" <= ch <= "9" for ch in pan[5:9])
        and "A" <= pan[9] <= "Z"
    ):
        return None

    entity_number = gstin[12]
    if not ("1" <= entity_number <= "9" or "A" <= entity_number <= "Z"):
        return None

    if gstin[13] != "Z":
        return None

    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    value_map = {ch: i for i, ch in enumerate(alphabet)}

    total = 0
    for i, ch in enumerate(gstin[:14]):
        value = value_map.get(ch)
        if value is None:
            return None
        product = value * (1 if i % 2 == 0 else 2)
        total += (product // 36) + (product % 36)

    check_char = alphabet[(36 - (total % 36)) % 36]
    if gstin[14] != check_char:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
