def inr_words_en(n: int) -> str:
    """
    0 <= n < 1,000,000,000 ஆன எதிர்மறையல்லாத integer-ஐ
    இந்திய எண் முறையில் (crore, lakh, thousand) lowercase ஆங்கிலச் சொற்களாக மாற்றும்.

    எடுத்துக்காட்டு:
        12345678 -> "one crore twenty-three lakh forty-five thousand six hundred seventy-eight"

    Raises:
        ValueError: n எதிர்மறையாக இருந்தாலோ அல்லது 1,000,000,000 அல்லது அதற்கு மேல் இருந்தாலோ.
    """
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must satisfy 0 <= n < 1,000,000,000")

    _ONES = [
        "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen",
    ]
    _TENS = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety",
    ]

    def two_digits(num: int) -> str:
        # 0 <= num < 100
        if num < 20:
            return _ONES[num]
        tens, ones = divmod(num, 10)
        if ones == 0:
            return _TENS[tens]
        return f"{_TENS[tens]}-{_ONES[ones]}"

    def three_digits(num: int) -> str:
        # 0 <= num < 1000
        hundreds, remainder = divmod(num, 100)
        parts = []
        if hundreds:
            parts.append(f"{_ONES[hundreds]} hundred")
        if remainder:
            parts.append(two_digits(remainder))
        return " ".join(parts)

    if n == 0:
        return "zero"

    crore = n // 10_000_000            # 0 - 99
    lakh = (n // 100_000) % 100        # 0 - 99
    thousand = (n // 1_000) % 100      # 0 - 99
    rest = n % 1_000                   # 0 - 999

    parts = []
    for value, unit in ((crore, "crore"), (lakh, "lakh"), (thousand, "thousand")):
        if value:
            parts.append(f"{two_digits(value)} {unit}")
    if rest:
        parts.append(three_digits(rest))

    return " ".join(parts)
