def inr_words_en(n: int) -> str:
    """
    Convert a non-negative integer less than 1,000,000,000 into English words
    using the Indian numbering system (crore, lakh, thousand).

    Rules:
    - lowercase output
    - 21-99 non-multiples of ten use hyphen (e.g. "forty-two")
    - no "and"
    - single spaces between words
    - 0 -> "zero"
    - raise ValueError for n < 0 or n >= 1_000_000_000
    """
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must satisfy 0 <= n < 1_000_000_000")

    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven",
        "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety"
    ]

    def below_hundred(x: int) -> str:
        if x < 20:
            return ones[x]
        t, u = divmod(x, 10)
        if u == 0:
            return tens[t]
        return f"{tens[t]}-{ones[u]}"

    def below_thousand(x: int) -> str:
        if x < 100:
            return below_hundred(x)
        h, rem = divmod(x, 100)
        if rem == 0:
            return f"{ones[h]} hundred"
        return f"{ones[h]} hundred {below_hundred(rem)}"

    if n == 0:
        return "zero"

    parts = []

    crore, rem = divmod(n, 10_000_000)
    if crore:
        parts.append(f"{below_hundred(crore)} crore")

    lakh, rem = divmod(rem, 100_000)
    if lakh:
        parts.append(f"{below_hundred(lakh)} lakh")

    thousand, rem = divmod(rem, 1_000)
    if thousand:
        parts.append(f"{below_hundred(thousand)} thousand")

    if rem:
        parts.append(below_thousand(rem))

    return " ".join(parts)
