    crore = n // 10**7               # 0-99
    lakh = (n // 10**5) % 100        # two digits
    thousand = (n // 1000) % 100     # two digits
    hundred = (n // 100) % 10        # single digit
    last = n % 100                   # last two digits (no unit)

    parts = []
    if crore:
        parts.append(f"{WORDS[crore]} करोड़")
    if lakh:
        parts.append(f"{WORDS[lakh]} लाख")
    if thousand:
        parts.append(f"{WORDS[thousand]} हज़ार")
    if hundred:
        parts.append(f"{WORDS[hundred]} सौ")
    if last:
        parts.append(WORDS[last])

    return " ".join(parts)
