from fractions import Fraction


def _round_half_up(value: Fraction) -> int:
    """Round a Fraction to the nearest integer, with exact halves rounded
    away from zero (round half up in magnitude). Avoids float error and
    does not use Python's round()."""
    if value >= 0:
        return (value + Fraction(1, 2)).__floor__()
    return -((-value + Fraction(1, 2)).__floor__())


def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    # Convert rate via its decimal string form so values like 0.25 or 1.5
    # are represented exactly rather than as binary floats.
    rate = Fraction(str(rate_pct))
    taxable = Fraction(int(taxable_paise))

    if supplier_state == place_of_supply:
        # Intra-state: CGST and SGST each at half the rate.
        half_rate = rate / 2
        tax = _round_half_up(taxable * half_rate / 100)
        return {"cgst": tax, "sgst": tax, "igst": 0}

    # Inter-state: IGST at the full rate.
    igst = _round_half_up(taxable * rate / 100)
    return {"cgst": 0, "sgst": 0, "igst": igst}
