def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    """
    भारतीय बैंकों के reducing-balance तरीके से मासिक EMI निकालता है।

    EMI = P * r * (1 + r)^n / ((1 + r)^n - 1)
    जहाँ r = annual_rate_pct / 12 / 100 और n = months।
    दर 0 होने पर EMI = P / n।
    परिणाम 2 दशमलव स्थान (paise) तक round करके float के रूप में लौटाया जाता है।
    """
    if months <= 0:
        raise ValueError("months 0 से अधिक होना चाहिए")
    if principal < 0:
        raise ValueError("principal ऋणात्मक नहीं हो सकता")
    if annual_rate_pct < 0:
        raise ValueError("दर ऋणात्मक नहीं हो सकती")

    r = annual_rate_pct / 12 / 100

    if r == 0:
        value = principal / months
    else:
        factor = (1 + r) ** months
        value = principal * r * factor / (factor - 1)

    return round(value, 2)
