        if not isinstance(vpa, str):
            return False

        vpa = vpa.strip()

        # Exactly one "@"
        if vpa.count("@") != 1:
            return False

        local, handle = vpa.split("@", 1)

        # Local part: 2-64 chars, allowed charset, alnum at both ends, no ".."
        if not (2 <= len(local) <= 64):
            return False
        if ".." in local:
            return False
        if _LOCAL_RE.fullmatch(local) is None:
            return False

        # Handle: 3-32 chars, ASCII letters/digits only, must start with a letter
        if not (3 <= len(handle) <= 32):
            return False
        if _HANDLE_RE.fullmatch(handle) is None:
            return False

        return True
    except Exception:
        return False
