def is_valid_upi_id(vpa: str) -> bool:
    if not isinstance(vpa, str):
        return False

    vpa = vpa.strip()

    if vpa.count("@") != 1:
        return False

    local, handle = vpa.split("@")

    # Validate local part: 2 to 64 chars, allowed chars, starts/ends alnum, no consecutive dots
    if not (2 <= len(local) <= 64):
        return False
    if not local[0].isalnum() or not local[-1].isalnum():
        return False
    if ".." in local:
        return False
    for ch in local:
        if not (ch.isalnum() or ch in "._-"):
            return False

    # Validate handle: 3 to 32 chars, letters/digits only, must start with a letter
    if not (3 <= len(handle) <= 32):
        return False
    if not handle[0].isalpha():
        return False
    if not handle.isalnum():
        return False

    return True
