        return None

    normalized = status.strip().upper()
    if not normalized:
        return None

    # Parts may be separated by "/" or one or more spaces.
    parts = re.split(r"[/ ]+", normalized)

    code = parts[0]

    if code == "CNF":
        if len(parts) not in (3, 4):
            return None
        coach = parts[1]
        berth = _to_number(parts[2])
        if not coach or berth is None:
            return None
        berth_type = parts[3] if len(parts) == 4 else None
        if berth_type is not None and not berth_type:
            return None
        return {
            "status": "CNF",
            "coach": coach,
            "berth": berth,
            "berth_type": berth_type,
        }

    if code == "RAC":
        if len(parts) != 2:
            return None
        number = _to_number(parts[1])
        if number is None:
            return None
        return {"status": "RAC", "number": number}

    if code in _WAITLIST_CODES:
        if len(parts) != 2:
            return None
        number = _to_number(parts[1])
        if number is None:
            return None
        return {"status": "WL", "list": code, "number": number}

