from decimal import Decimal, ROUND_HALF_UP

def income_tax_new_regime(gross_salary: int) -> int:
    # 1. Standard deduction of 75,000, minimum taxable income is 0
    taxable_income = max(0, gross_salary - 75000)

    # 3. Rebate: If taxable income is 12,00,000 or less, tax is 0
    if taxable_income <= 1200000:
        return 0

    ti = Decimal(taxable_income)
    tax = Decimal('0')

    # 2. Slab calculation
    if ti > Decimal('400000'):
        tax += min(ti - Decimal('400000'), Decimal('400000')) * Decimal('0.05')
    if ti > Decimal('800000'):
        tax += min(ti - Decimal('800000'), Decimal('400000')) * Decimal('0.10')
    if ti > Decimal('1200000'):
        tax += min(ti - Decimal('1200000'), Decimal('400000')) * Decimal('0.15')
    if ti > Decimal('1600000'):
        tax += min(ti - Decimal('1600000'), Decimal('400000')) * Decimal('0.20')
    if ti > Decimal('2000000'):
        tax += min(ti - Decimal('2000000'), Decimal('400000')) * Decimal('0.25')
    if ti > Decimal('2400000'):
        tax += (ti - Decimal('2400000')) * Decimal('0.30')

    # 4. Add 4% Health and Education Cess
    total_tax = tax * Decimal('1.04')

    # 5. Round to the nearest integer, half up
    final_tax = total_tax.quantize(Decimal('1'), rounding=ROUND_HALF_UP)

    return int(final_tax)
