from decimal import Decimal, ROUND_HALF_UP

def income_tax_new_regime(gross_salary: int) -> int:
    # 1. Standard deduction (ஸ்டாண்டர்டு டிடக்‌ஷன்)
    taxable_income = max(0, gross_salary - 75000)

    # 3. Rebate (வரி தள்ளுபடி) - ரூ. 12,00,000 அல்லது அதற்குக் குறைவு என்றால் வரி 0
    if taxable_income <= 1200000:
        return 0

    taxable = Decimal(taxable_income)
    tax = Decimal('0')

    # 2. Slab வரியைக் கணக்கிடுதல்
    if taxable > 400000:
        tax += (min(taxable, Decimal('800000')) - Decimal('400000')) * Decimal('0.05')

    if taxable > 800000:
        tax += (min(taxable, Decimal('1200000')) - Decimal('800000')) * Decimal('0.10')

    if taxable > 1200000:
        tax += (min(taxable, Decimal('1600000')) - Decimal('1200000')) * Decimal('0.15')

    if taxable > 1600000:
        tax += (min(taxable, Decimal('2000000')) - Decimal('1600000')) * Decimal('0.20')

    if taxable > 2000000:
        tax += (min(taxable, Decimal('2400000')) - Decimal('2000000')) * Decimal('0.25')

    if taxable > 2400000:
        tax += (taxable - Decimal('2400000')) * Decimal('0.30')

    # 4. 4% Health and Education Cess சேர்ப்பது
    tax_with_cess = tax * Decimal('1.04')

    # 5. அருகிலுள்ள ரூபாய்க்கு ரவுண்ட் செய்தல் (சரியாகப் பாதி என்றால் மேல்நோக்கி - Round half up)
    final_tax = tax_with_cess.quantize(Decimal('1'), rounding=ROUND_HALF_UP)

