import re
from datetime import datetime, timedelta

_IST_OFFSET = timedelta(hours=5, minutes=30)
_PATTERN = re.compile(
    r"(\d{2})/(\d{2})/(\d{4}) (\d{1,2}):(\d{2}) (AM|PM)",
    re.IGNORECASE,
)


def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("इनपुट एक string होना चाहिए")

    m = _PATTERN.fullmatch(s)
    if not m:
        raise ValueError(f"अवैध format: {s!r}")

    day_s, month_s, year_s, hour_s, minute_s, ampm = m.groups()
    day, month, year = int(day_s), int(month_s), int(year_s)
    hour, minute = int(hour_s), int(minute_s)

    if not (1 <= hour <= 12):
        raise ValueError(f"अवैध घंटा: {hour}")
    if not (0 <= minute <= 59):
        raise ValueError(f"अवैध मिनट: {minute}")

    # 12 AM -> 0 (आधी रात), 12 PM -> 12 (दोपहर)
    hour24 = hour % 12
    if ampm.upper() == "PM":
        hour24 += 12

    try:
        local = datetime(year, month, day, hour24, minute)
    except ValueError as exc:
        raise ValueError(f"अवैध तारीख़/समय: {s!r}") from exc

    try:
        utc = local - _IST_OFFSET
    except OverflowError as exc:
        raise ValueError(f"समय सीमा से बाहर: {s!r}") from exc

    return (
        f"{utc.year:04d}-{utc.month:02d}-{utc.day:02d}"
        f"T{utc.hour:02d}:{utc.minute:02d}:00Z"
    )
