    r"([0-9]{2})/([0-9]{2})/([0-9]{4}) ([0-9]{1,2}):([0-9]{2}) ([AaPp][Mm])"
)
_IST_OFFSET = timedelta(hours=5, minutes=30)


def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("Input must be a string in 'DD/MM/YYYY hh:mm AM/PM' format")

    match = _IST_PATTERN.fullmatch(s)
    if not match:
        raise ValueError(f"Invalid format: {s!r}")

    day_s, month_s, year_s, hour_s, minute_s, meridiem = match.groups()
    day, month, year = int(day_s), int(month_s), int(year_s)
    hour, minute = int(hour_s), int(minute_s)

    if not 1 <= hour <= 12:
        raise ValueError(f"Hour must be between 1 and 12: {s!r}")
    if not 0 <= minute <= 59:
        raise ValueError(f"Minute must be between 0 and 59: {s!r}")

    meridiem = meridiem.upper()
    if hour == 12:
        hour = 0
    if meridiem == "PM":
        hour += 12

    try:
        ist_dt = datetime(year, month, day, hour, minute)
    except ValueError as exc:
        raise ValueError(f"Invalid date/time: {s!r}") from exc

    try:
        utc_dt = ist_dt - _IST_OFFSET
    except OverflowError as exc:
        raise ValueError(f"Date out of supported range: {s!r}") from exc

    return (
        f"{utc_dt.year:04d}-{utc_dt.month:02d}-{utc_dt.day:02d}"
        f"T{utc_dt.hour:02d}:{utc_dt.minute:02d}:00Z"
