            "berth": int(m.group("berth")),
            "berth_type": m.group("berth_type").upper() if m.group("berth_type") else None,
        }

    # RAC: RAC 12 or RAC/12
    m = re.fullmatch(r"RAC[ /]+(?P<number>\d+)", s, re.IGNORECASE)
    if m:
        return {"status": "RAC", "number": int(m.group("number"))}

    # Waitlist: WL 34, GNWL 34, RLWL/5, PQWL 2, TQWL 9
    m = re.fullmatch(r"(?P<list>WL|GNWL|RLWL|PQWL|TQWL)[ /]+(?P<number>\d+)", s, re.IGNORECASE)
    if m:
        return {
            "status": "WL",
            "list": m.group("list").upper(),
            "number": int(m.group("number")),
        }

    return None
