    cleaned = number.replace(" ", "").replace("-", "")

    if not (12 <= len(cleaned) <= 19):
        return None
    if not all(ch in _ASCII_DIGITS for ch in cleaned):
        return None

    prefix2 = int(cleaned[:2])
    prefix4 = int(cleaned[:4])

    if cleaned.startswith(("34", "37")):
        network = "Amex"
    elif cleaned.startswith("4"):
        network = "Visa"
    elif 51 <= prefix2 <= 55 or 2221 <= prefix4 <= 2720:
        network = "Mastercard"
    elif cleaned.startswith(("60", "65", "81", "82", "508")):
        network = "RuPay"
    else:
        network = "Unknown"

    total = 0
    for index, ch in enumerate(reversed(cleaned)):
        digit = int(ch)
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    luhn_ok = total % 10 == 0

