import re


def parse_booking_status(status: str) -> dict | None:
    if not isinstance(status, str):
        return None

    s = status.strip()
    if not s:
        return None

    tokens = [t for t in re.split(r"[/\s]+", s.upper()) if t]
    if not tokens:
        return None

    def is_digits(token: str) -> bool:
        return bool(re.fullmatch(r"\d+", token))

    def is_code(token: str) -> bool:
        return bool(re.fullmatch(r"[A-Z0-9]+", token))

    head = tokens[0]

    if head == "CNF":
        if len(tokens) not in (3, 4):
            return None

        coach = tokens[1]
        berth = tokens[2]

        if not is_code(coach) or not is_digits(berth):
            return None

        result = {
            "status": "CNF",
            "coach": coach,
            "berth": int(berth),
            "berth_type": None,
        }

        if len(tokens) == 4:
            berth_type = tokens[3]
            if not is_code(berth_type):
                return None
            result["berth_type"] = berth_type

        return result

    if head == "RAC":
        if len(tokens) != 2 or not is_digits(tokens[1]):
            return None
        return {"status": "RAC", "number": int(tokens[1])}

    waitlist_codes = {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}
    if head in waitlist_codes:
        if len(tokens) != 2 or not is_digits(tokens[1]):
            return None
        return {"status": "WL", "list": head, "number": int(tokens[1])}

    return None
```

