    # Prefix validation
    if not (2 <= len(prefix) <= 64):
        return False

    if '..' in prefix:
        return False

    if not re.fullmatch(r'[a-zA-Z0-9][a-zA-Z0-9._-]*[a-zA-Z0-9]', prefix):
        return False

    # Handle validation
    if not (3 <= len(handle) <= 32):
        return False

    if not re.fullmatch(r'[a-zA-Z][a-zA-Z0-9]*', handle):
        return False

