        if not re.match(r"^[a-zA-Z0-9][a-zA-Z0-9._\-]*[a-zA-Z0-9]$", prefix):
            return False

        # Handle checks ("@" ke baad wala part)
        if not (3 <= len(handle) <= 32):
            return False

        # Sirf letters aur digits, aur letter se start ho
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9]*$", handle):
            return False

        return True

    except Exception:
        # Kabhi raise nahi karna
        return False
