import re
import datetime

_MONTH_LOOKUP = {}
for _i, _name in enumerate(
    ["january", "february", "march", "april", "may", "june",
     "july", "august", "september", "october", "november", "december"],
    start=1,
):
    _MONTH_LOOKUP[_name] = _i
    _MONTH_LOOKUP[_name[:3]] = _i

# Groups: 1 = day, 2 = separator, 3 = month (name or number), 4 = year
_DATE_PATTERN = re.compile(
    r"([0-9]{1,2})([/.\- ])([A-Za-z]+|[0-9]{1,2})\2([0-9]{4}|[0-9]{2})"
)


def parse_indian_date(s: str) -> datetime.date:
    """
    Parse an Indian day-first date string into a datetime.date.

    Accepted forms:
      - Day: 1 or 2 digits
      - Separator: '/', '-', '.' or a space (the same one must be used twice)
      - Month: 1 or 2 digit number, 3-letter English abbreviation,
               or full English month name (case-insensitive)
      - Year: 4 digits, or 2 digits meaning 2000-2099

    Raises ValueError if the format or the date itself is invalid.
    """
    if not isinstance(s, str):
        raise ValueError(f"Date must be a string, got {type(s).__name__}")

    match = _DATE_PATTERN.fullmatch(s.strip())
    if match is None:
        raise ValueError(f"Invalid date format: {s!r}")

    day_str, _sep, month_str, year_str = match.groups()

    if month_str.isdigit():
        month = int(month_str)
        if not 1 <= month <= 12:
            raise ValueError(f"Invalid month in date: {s!r}")
    else:
        month = _MONTH_LOOKUP.get(month_str.lower())
        if month is None:
            raise ValueError(f"Invalid month name in date: {s!r}")

    year = int(year_str)
    if len(year_str) == 2:
        year += 2000

    day = int(day_str)

    try:
        return datetime.date(year, month, day)
    except ValueError as exc:
        raise ValueError(f"Invalid date: {s!r}") from exc
