def pincode_state(pincode: str, table: dict[str, str]) -> str | None:
    pincode = pincode.replace(" ", "")

    if len(pincode) != 6 or not pincode.isascii() or not pincode.isdigit() or pincode[0] == '0':
        return None

    best_state = None
    max_prefix_len = 0

    for prefix, state in table.items():
