from typing import List

_ONES = [
    "Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
    "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
    "Seventeen", "Eighteen", "Nineteen",
]
_TENS = [
    "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety",
]


def _two_digit_words(n: int) -> str:
    """0-99 तक की संख्या को शब्दों में बदलता है।"""
    if n < 20:
        return _ONES[n]
    tens, units = divmod(n, 10)
    if units == 0:
        return _TENS[tens]
    return f"{_TENS[tens]}-{_ONES[units]}"


def _three_digit_words(n: int) -> str:
    """0-999 तक की संख्या को शब्दों में बदलता है (Hundred सहित)।"""
    hundreds, rest = divmod(n, 100)
    parts: List[str] = []
    if hundreds:
        parts.append(f"{_ONES[hundreds]} Hundred")
    if rest:
        parts.append(_two_digit_words(rest))
    return " ".join(parts)


def _indian_int_words(n: int) -> str:
    """भारतीय प्रणाली (Crore, Lakh, Thousand) में 0 से 999,999,999 तक की संख्या।"""
    if n == 0:
        return "Zero"

    crore, rem = divmod(n, 10**7)
    lakh, rem = divmod(rem, 10**5)
    thousand, rem = divmod(rem, 10**3)

    parts: List[str] = []
    if crore:
        parts.append(f"{_two_digit_words(crore)} Crore")
    if lakh:
        parts.append(f"{_two_digit_words(lakh)} Lakh")
    if thousand:
        parts.append(f"{_two_digit_words(thousand)} Thousand")
    if rem:
        parts.append(_three_digit_words(rem))
    return " ".join(parts)


def cheque_amount_words(paise: int) -> str:
    """
    paise में दी गई रकम को भारतीय cheque के लिए शब्दों में बदलता है।

    उदाहरण:
        123456789 -> "Rupees Twelve Lakh Thirty-Four Thousand Five Hundred
                      Sixty-Seven and Eighty-Nine Paise Only"
    """
    if paise < 0:
        raise ValueError("रकम ऋणात्मक नहीं हो सकती।")

    rupees, paise_part = divmod(paise, 100)
    if rupees >= 10**9:
        raise ValueError("रुपये का हिस्सा 1,000,000,000 से कम होना चाहिए।")

    rupee_words = _indian_int_words(rupees)

    if paise_part == 0:
        return f"Rupees {rupee_words} Only"

    paise_words = _indian_int_words(paise_part)
    return f"Rupees {rupee_words} and {paise_words} Paise Only"
