    # Replace slashes with spaces and split on whitespace
    # This automatically handles multiple spaces, slashes, and surrounding whitespace
    parts = status.upper().replace('/', ' ').split()

    if not parts:
        return None

    code = parts[0]

    if code == "CNF":
        if len(parts) not in (3, 4):
            return None
        try:
            berth = int(parts[2])
        except ValueError:
            return None

        return {
            "status": "CNF",
            "coach": parts[1],
            "berth": berth,
            "berth_type": parts[3] if len(parts) == 4 else None
        }

    elif code == "RAC":
        if len(parts) != 2:
            return None
        try:
            number = int(parts[1])
        except ValueError:
            return None

        return {
            "status": "RAC",
            "number": number
        }

    elif code in {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}:
        if len(parts) != 2:
            return None
        try:
            number = int(parts[1])
        except ValueError:
            return None

        return {
            "status": "WL",
            "list": code,
            "number": number
        }

    return None
