def format_compact_inr(rupees: int) -> str:
    def _group_indian(n: int) -> str:
        # Indian grouping: last three digits, then pairs of two.
        s = str(n)
        if len(s) <= 3:
            return s
        head, tail = s[:-3], s[-3:]
        parts = []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        return ",".join(parts) + "," + tail

    n = abs(int(rupees))
    sign = "-" if rupees < 0 else ""

    # Choose the unit from the value before rounding.
    if n >= 10**7:
        divisor, unit = 10**7, " Cr"
    elif n >= 10**5:
        divisor, unit = 10**5, " L"
    else:
        return sign + _group_indian(n)

    # Round n / divisor to 2 decimal places, half up, using exact integer
    # arithmetic: result in hundredths = floor(n*100/divisor + 1/2).
    hundredths = (200 * n + divisor) // (2 * divisor)
    whole, frac = divmod(hundredths, 100)

    # Remove trailing zeros and a trailing decimal point.
    if frac == 0:
        num = str(whole)
    elif frac % 10 == 0:
        num = f"{whole}.{frac // 10}"
    else:
        num = f"{whole}.{frac:02d}"

    return sign + num + unit
