from decimal import Decimal, ROUND_HALF_UP


def _group_indian(n: int) -> str:
    """Format a non-negative integer with Indian digit grouping (e.g. 1234567 -> 12,34,567)."""
    s = str(n)
    if len(s) <= 3:
        return s
    head, tail = s[:-3], s[-3:]
    parts = []
    while len(head) > 2:
        parts.append(head[-2:])
        head = head[:-2]
    if head:
        parts.append(head)
    return ",".join(reversed(parts)) + "," + tail


def format_compact_inr(rupees: int) -> str:
    sign = "-" if rupees < 0 else ""
    amount = abs(rupees)

    def _compact(divisor: int, suffix: str) -> str:
        value = (Decimal(amount) / Decimal(divisor)).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        text = format(value, "f").rstrip("0").rstrip(".")
        return f"{sign}{text} {suffix}"

    if amount >= 10_000_000:
        return _compact(10_000_000, "Cr")
    if amount >= 100_000:
        return _compact(100_000, "L")
    return sign + _group_indian(amount)
