_MONTHS = {name.lower(): idx for idx, name in enumerate(calendar.month_name) if name}
_MONTHS.update({abbr.lower(): idx for idx, abbr in enumerate(calendar.month_abbr) if abbr})

_NUMERIC_RE = re.compile(
    r"^(?P<day>[0-9]{1,2})(?P<sep>[/\-.])(?P<month>[0-9]{1,2})(?P=sep)(?P<year>[0-9]{2}|[0-9]{4})$"
)
_SPACE_RE = re.compile(
    r"^(?P<day>[0-9]{1,2}) +(?P<month>[0-9]{1,2}|[A-Za-z]+) +(?P<year>[0-9]{2}|[0-9]{4})$"
)


def parse_indian_date(s: str) -> datetime.date:
    m = _NUMERIC_RE.fullmatch(s)
    if m:
        day = int(m.group("day"))
        month = int(m.group("month"))
        year_s = m.group("year")
    else:
        m = _SPACE_RE.fullmatch(s)
        if not m:
            raise ValueError(f"Invalid date format: {s!r}")

        day = int(m.group("day"))
        month_token = m.group("month")
        if month_token.isdigit():
            month = int(month_token)
        else:
            month = _MONTHS.get(month_token.lower())
            if month is None:
                raise ValueError(f"Invalid month: {month_token!r}")

        year_s = m.group("year")

    year = 2000 + int(year_s) if len(year_s) == 2 else int(year_s)

    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"Invalid date: {s!r}") from None
