from decimal import Decimal, ROUND_HALF_UP


def format_compact_inr(rupees: int) -> str:
    sign = "-" if rupees < 0 else ""
    a = abs(rupees)

    def _trim(value: Decimal) -> str:
        # 2 decimals tak half-up rounding, phir trailing zeros aur trailing "." hatao
        q = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        s = f"{q:.2f}"
        return s.rstrip("0").rstrip(".")

    def _indian_group(n: int) -> str:
        s = str(n)
        if len(s) <= 3:
            return s
        head, tail = s[:-3], s[-3:]
        parts = []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        return ",".join(parts + [tail])

    if a >= 10_000_000:
        value = Decimal(a) / Decimal(10_000_000)
        return f"{sign}{_trim(value)} Cr"

    if a >= 100_000:
        value = Decimal(a) / Decimal(100_000)
        return f"{sign}{_trim(value)} L"

    return f"{sign}{_indian_group(a)}"
