import re
from datetime import datetime, timedelta

def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    # Check strict format: DD/MM/YYYY hh:mm AM/PM (DD, MM exactly 2 digits, hh 1 or 2 digits)
    if not re.match(r"^\d{2}/\d{2}/\d{4} \d{1,2}:\d{2} (?:[Aa][Mm]|[Pp][Mm])$", s):
        raise ValueError("Invalid format: Must be 'DD/MM/YYYY hh:mm AM/PM'")

    try:
        # Convert to uppercase to ensure AM/PM is correctly parsed by %p
        dt_ist = datetime.strptime(s.upper(), "%d/%m/%Y %I:%M %p")
    except ValueError:
        raise ValueError("Invalid date or time values")

    # IST is UTC+05:30, so UTC = IST - 05:30
    dt_utc = dt_ist - timedelta(hours=5, minutes=30)

    # Format to required ISO format
    return dt_utc.strftime("%Y-%m-%dT%H:%M:00Z")
