def cheque_amount_words(paise: int) -> str:
    if paise < 0:
        raise ValueError("paise must be non-negative")

    ones = [
        "Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
        "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
        "Seventeen", "Eighteen", "Nineteen"
    ]
    tens = [
        "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"
    ]

    def two_digit_words(n: int) -> str:
        if n < 20:
            return ones[n]
        ten, unit = divmod(n, 10)
        if unit == 0:
            return tens[ten]
        return f"{tens[ten]}-{ones[unit]}"

    def three_digit_words(n: int) -> str:
        hundred, rem = divmod(n, 100)
        parts = []
        if hundred:
            parts.append(f"{ones[hundred]} Hundred")
        if rem:
            parts.append(two_digit_words(rem))
        return " ".join(parts) if parts else "Zero"

    def indian_number_words(n: int) -> str:
        if n == 0:
            return "Zero"

        parts = []

        crore, rem = divmod(n, 10_000_000)
        lakh, rem = divmod(rem, 100_000)
        thousand, rem = divmod(rem, 1_000)

        if crore:
            parts.append(f"{two_digit_words(crore)} Crore")
        if lakh:
            parts.append(f"{two_digit_words(lakh)} Lakh")
        if thousand:
            parts.append(f"{two_digit_words(thousand)} Thousand")
        if rem:
            parts.append(three_digit_words(rem))

        return " ".join(parts)

    rupees, paise_part = divmod(paise, 100)
    rupee_words = indian_number_words(rupees)

    if paise_part == 0:
        return f"Rupees {rupee_words} Only"
    return f"Rupees {rupee_words} and {two_digit_words(paise_part)} Paise Only"
