def card_info(number: str) -> tuple[str, bool] | None:
    # Remove spaces and hyphens
    cleaned = number.replace(" ", "").replace("-", "")

    # Check if length is 12-19 and contains only ASCII digits
    if not (12 <= len(cleaned) <= 19) or not all(c in "0123456789" for c in cleaned):
        return None

    # Determine network
    network = "Unknown"
    prefix4 = int(cleaned[:4])

    if cleaned.startswith(("34", "37")):
        network = "Amex"
    elif cleaned.startswith("4"):
        network = "Visa"
    elif cleaned.startswith(("51", "52", "53", "54", "55")) or (2221 <= prefix4 <= 2720):
        network = "Mastercard"
    elif cleaned.startswith(("60", "65", "81", "82", "508")):
        network = "RuPay"

    # Calculate Luhn checksum
    total = 0
    for i, char in enumerate(reversed(cleaned)):
        digit = int(char)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    luhn_ok = (total % 10 == 0)

    return network, luhn_ok
