    # Country/trunk prefix हटाइए
    if s.startswith('+91'):
        s = s[3:]
    elif s.startswith('0091'):
        s = s[4:]
    elif len(s) == 12 and s.startswith('91'):
        s = s[2:]
    elif len(s) == 11 and s.startswith('0'):
        s = s[1:]

    # बचे हुए हिस्से को validate करें: ठीक 10 ASCII अंक और 6, 7, 8 या 9 से शुरुआत
    if len(s) == 10 and s.isascii() and s.isdigit() and s[0] in '6789':
        return '+91' + s

    return None
