import re

_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
_CHAR_VALUE = {ch: i for i, ch in enumerate(_ALPHABET)}

# 2-digit state code, 10-char PAN, entity number (1-9 or A-Z), literal 'Z', check char
_GSTIN_RE = re.compile(r"([0-9]{2})([A-Z]{5}[0-9]{4}[A-Z])([1-9A-Z])Z([0-9A-Z])")


def _check_char(first14: str) -> str:
    total = 0
    for i, ch in enumerate(first14):
        product = _CHAR_VALUE[ch] * (1 if i % 2 == 0 else 2)
        total += (product // 36) + (product % 36)
    return _ALPHABET[(36 - total % 36) % 36]


def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    value = gstin.strip().upper()
    if len(value) != 15:
        return None

    match = _GSTIN_RE.fullmatch(value)
    if not match:
        return None

    state_code, pan, entity_number, check = match.groups()

    state = int(state_code)
    if not (1 <= state <= 38 or state == 97):
        return None

    if _check_char(value[:14]) != check:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
