import re

_GSTIN_RE = re.compile(r"([0-9]{2})([A-Z]{5}[0-9]{4}[A-Z])([1-9A-Z])Z([0-9A-Z])")
_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    value = gstin.strip().upper()
    if len(value) != 15:
        return None

    match = _GSTIN_RE.fullmatch(value)
    if not match:
        return None

    state_code, pan, entity_number, check_char = match.groups()

    state_num = int(state_code)
    if not (1 <= state_num <= 38 or state_num == 97):
        return None

    total = 0
    for i, ch in enumerate(value[:14]):
        product = _ALPHABET.index(ch) * (1 if i % 2 == 0 else 2)
        total += (product // 36) + (product % 36)

    expected = _ALPHABET[(36 - total % 36) % 36]
    if check_char != expected:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
```

