import re

def normalize_mobile(s: str) -> str | None:
    if s is None:
        return None

    # 1. spaces, hyphens, dots, parentheses ஆகியவற்றை நீக்குதல்
    cleaned = re.sub(r'[\s\-\.\(\)]+', '', s)

    # 2. country / trunk prefix-ஐ நீக்குதல்
    if cleaned.startswith("+91"):
        cleaned = cleaned[3:]
    elif cleaned.startswith("0091"):
        cleaned = cleaned[4:]
    elif len(cleaned) == 12 and cleaned.startswith("91"):
        cleaned = cleaned[2:]
    elif len(cleaned) == 11 and cleaned.startswith("0"):
        cleaned = cleaned[1:]

    # 3. மீதமிருக்கும் 10 இலக்கங்களை சரிபார்த்தல் (6, 7, 8, 9 -இல் தொடங்கும் ASCII இலக்கங்கள்)
    if len(cleaned) == 10 and cleaned[0] in "6789" and all(c in "0123456789" for c in cleaned):
        return f"+91{cleaned}"

    return None
