    elif s.startswith("0091"):
        s = s[4:]
    elif s.startswith("91") and len(s) == 12:
        s = s[2:]
    elif s.startswith("0") and len(s) == 11:
        s = s[1:]

    # Validate the remaining string:
    # - Exactly 10 characters
    # - Starts with 6, 7, 8, or 9
    # - Consists entirely of ASCII digits
    if len(s) == 10 and s[0] in "6789" and all(c in "0123456789" for c in s):
        return "+91" + s

