def normalize_mobile(s: str) -> str | None:
    if not isinstance(s, str):
        return None

    # Remove spaces, hyphens, dots, and brackets (parentheses)
    for char in " -.()":
        s = s.replace(char, "")

    # Remove country/trunk prefix
    if s.startswith("+91"):
        s = s[3:]
    elif s.startswith("0091"):
        s = s[4:]
    elif s.startswith("91") and len(s) == 12:
        s = s[2:]
    elif s.startswith("0") and len(s) == 11:
        s = s[1:]

    # Check if remaining string is exactly 10 ASCII digits and starts with 6, 7, 8, or 9
    if len(s) == 10 and s.isascii() and s.isdigit() and s[0] in "6789":
        return f"+91{s}"

    return None
