def inr_words_en(n: int) -> str:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must satisfy 0 <= n < 1,000,000,000")
    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight",
        "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
        "sixteen", "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
        "eighty", "ninety",
    ]

    def below_hundred(x: int) -> str:
        if x < 20:
            return ones[x]
        t, o = divmod(x, 10)
        return tens[t] if o == 0 else tens[t] + "-" + ones[o]

    def below_thousand(x: int) -> str:
        h, r = divmod(x, 100)
        parts = []
        if h:
            parts.append(ones[h] + " hundred")
        if r:
            parts.append(below_hundred(r))
        return " ".join(parts)

    crore, rem = divmod(n, 10_000_000)
    lakh, rem = divmod(rem, 100_000)
    thousand, rem = divmod(rem, 1_000)

    parts = []
    if crore:
        parts.append(below_hundred(crore) + " crore")
    if lakh:
        parts.append(below_hundred(lakh) + " lakh")
    if thousand:
        parts.append(below_hundred(thousand) + " thousand")
    if rem:
        parts.append(below_thousand(rem))
    return " ".join(parts)
