def inr_words_hi(n: int) -> str:
    words = {
        1: "एक", 2: "दो", 3: "तीन", 4: "चार", 5: "पाँच",
        6: "छह", 7: "सात", 8: "आठ", 9: "नौ", 10: "दस",
        20: "बीस", 30: "तीस", 40: "चालीस", 50: "पचास",
        60: "साठ", 70: "सत्तर", 80: "अस्सी", 90: "नब्बे",
    }

    if not isinstance(n, int) or n < 0 or n >= 1_000_000_000:
        raise ValueError("n must be an integer with 0 <= n < 1,000,000,000")

    if n == 0:
        return "शून्य"

    parts = [
        (n // 10**7, "करोड़"),
        ((n // 10**5) % 100, "लाख"),
        ((n // 1000) % 100, "हज़ार"),
        ((n // 100) % 10, "सौ"),
        (n % 100, ""),
    ]

    result = []
    for value, unit in parts:
        if value == 0:
            continue
        if value not in words:
            raise ValueError(f"Unsupported two-digit part: {value}")
        result.append(words[value])
        if unit:
            result.append(unit)

    return " ".join(result)
