from fractions import Fraction
from decimal import Decimal


def _round_half_up(value: Fraction) -> int:
    """Fraction को निकटतम integer तक round करता है; exact half पर ऊपर (शून्य से दूर)।"""
    if value >= 0:
        return (2 * value.numerator + value.denominator) // (2 * value.denominator)
    return -((-2 * value.numerator + value.denominator) // (2 * value.denominator))


def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    # float की binary त्रुटियों से बचने के लिए rate को उसकी दशमलव string से exact Fraction बनाते हैं
    rate = Fraction(Decimal(str(rate_pct)))
    taxable = Fraction(taxable_paise)

    supplier = str(supplier_state).strip()
    pos = str(place_of_supply).strip()

    if supplier == pos:
        # Intra-state: CGST और SGST अलग-अलग, हर एक आधी दर पर
        half_tax = _round_half_up(taxable * (rate / 2) / 100)
        return {"cgst": half_tax, "sgst": half_tax, "igst": 0}

    # Inter-state: पूरी दर पर IGST
    igst = _round_half_up(taxable * rate / 100)
    return {"cgst": 0, "sgst": 0, "igst": igst}
```

