from fractions import Fraction
from math import floor


def _round_half_up(value: Fraction) -> int:
    """அருகிலுள்ள முழு எண்ணுக்கு round செய்யும்; சரியாகப் பாதி என்றால் மேல்நோக்கி."""
    return floor(value + Fraction(1, 2))


def gst_split(taxable_paise: int, rate_pct: float, supplier_state: str, place_of_supply: str) -> dict:
    # float binary பிழைகளைத் தவிர்க்க, rate-ஐ அதன் தசம வடிவிலிருந்து (str) சரியான Fraction ஆக மாற்றுகிறோம்
    rate = Fraction(str(rate_pct))
    taxable = Fraction(taxable_paise)

    if str(supplier_state).strip() == str(place_of_supply).strip():
        # Intra-state: CGST, SGST ஒவ்வொன்றும் = taxable * (rate/2) / 100, தனித்தனியாக round
        half_rate = rate / 2
        component = _round_half_up(taxable * half_rate / 100)
        return {"cgst": component, "sgst": component, "igst": 0}

    # Inter-state: முழு விகிதத்தில் IGST
    igst = _round_half_up(taxable * rate / 100)
    return {"cgst": 0, "sgst": 0, "igst": igst}
```

