import math


def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    """Compute the monthly EMI for a reducing-balance loan.

    r = annual_rate_pct / 12 / 100
    EMI = P * r * (1 + r)^n / ((1 + r)^n - 1)
    If the rate is 0, EMI = P / n.
    Result is rounded to 2 decimal places (paise).

    Raises ValueError if months <= 0, principal < 0, or rate is negative.
    """
    if months <= 0:
        raise ValueError("months must be greater than 0")
    if principal < 0:
        raise ValueError("principal must not be negative")
    if annual_rate_pct < 0:
        raise ValueError("annual_rate_pct must not be negative")
    if (
        isinstance(principal, float) and not math.isfinite(principal)
        or not math.isfinite(annual_rate_pct)
    ):
        raise ValueError("principal and rate must be finite")

    if annual_rate_pct == 0:
        return round(principal / months, 2)

    r = annual_rate_pct / 12 / 100
    growth = (1 + r) ** months
    value = principal * r * growth / (growth - 1)
    return round(value, 2)
