import re


ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def parse_gstin(gstin: str) -> dict | None:
    if not isinstance(gstin, str):
        return None

    gstin = gstin.strip().upper()

    if len(gstin) != 15:
        return None

    state_code = gstin[:2]
    pan = gstin[2:12]
    entity_number = gstin[12]
    z_char = gstin[13]
    check_char = gstin[14]

    if not (state_code.isdigit() and (1 <= int(state_code) <= 38 or state_code == "97")):
        return None

    if not re.fullmatch(r"[A-Z]{5}[0-9]{4}[A-Z]", pan):
        return None

    if not re.fullmatch(r"[1-9A-Z]", entity_number):
        return None

    if z_char != "Z":
        return None

    total = 0
    for i, char in enumerate(gstin[:14]):
        if char not in ALPHABET:
            return None
        value = ALPHABET.index(char)
        product = value * (1 if i % 2 == 0 else 2)
        total += (product // 36) + (product % 36)

    expected_check_char = ALPHABET[(36 - total % 36) % 36]

    if check_char != expected_check_char:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
