import math


def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    """
    Calculate monthly EMI using the reducing-balance method
    (as used by Indian banks).

    r = annual_rate_pct / 12 / 100
    EMI = P * r * (1 + r)^n / ((1 + r)^n - 1)

    If the rate is 0, EMI = P / n.
    The result is rounded to 2 decimal places (paise) and returned as a float.

    Raises ValueError if months <= 0, principal < 0, or the rate is negative.
    """
    if months <= 0:
        raise ValueError("months must be greater than 0")
    if principal < 0:
        raise ValueError("principal must not be negative")
    if annual_rate_pct < 0:
        raise ValueError("annual_rate_pct must not be negative")
    if any(
        isinstance(v, float) and not math.isfinite(v)
        for v in (principal, annual_rate_pct)
    ):
        raise ValueError("principal and annual_rate_pct must be finite numbers")

    if annual_rate_pct == 0:
        return round(principal / months, 2)

    r = annual_rate_pct / 12 / 100

    # Numerically stable form of (1 + r)^n using log1p/expm1:
    # (1 + r)^n - 1 = expm1(n * log1p(r))
    growth_minus_one = math.expm1(months * math.log1p(r))
    growth = growth_minus_one + 1

    value = principal * r * growth / growth_minus_one
    return round(value, 2)
```

