def parse_gstin(gstin: str) -> dict | None:
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    gstin = gstin.strip().upper()

    if len(gstin) != 15:
        return None

    state_code = gstin[:2]
    pan = gstin[2:12]
    entity_number = gstin[12]
    z_char = gstin[13]
    check_char = gstin[14]

    if not state_code.isdigit():
        return None

    state_num = int(state_code)
    if not (1 <= state_num <= 38 or state_num == 97):
        return None

    if not (
        pan[:5].isalpha()
        and pan[:5].isupper()
        and pan[5:9].isdigit()
        and pan[9].isalpha()
        and pan[9].isupper()
    ):
        return None

    if not (entity_number in "123456789" or ("A" <= entity_number <= "Z")):
        return None

    if z_char != "Z":
        return None

    if check_char not in alphabet:
        return None

    total = 0
    for i, char in enumerate(gstin[:14]):
        if char not in alphabet:
            return None

        value = alphabet.index(char)
        product = value * (1 if i % 2 == 0 else 2)
        total += (product // 36) + (product % 36)

    expected_check_char = alphabet[(36 - total % 36) % 36]

    if check_char != expected_check_char:
        return None

    return {
        "state_code": state_code,
        "pan": pan,
        "entity_number": entity_number,
    }
