import math


def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    """
    Reducing-balance method se monthly EMI calculate karta hai.

    r = annual_rate_pct / 12 / 100
    EMI = P * r * (1 + r)^n / ((1 + r)^n - 1)

    Agar rate 0 hai toh EMI = P / n.
    Result 2 decimal places (paise) tak round hota hai.

    ValueError raise hoga agar:
      - months <= 0
      - principal < 0
      - annual_rate_pct < 0
      - inputs NaN/infinite hain
    """
    if (
        isinstance(months, bool)
        or isinstance(principal, bool)
        or isinstance(annual_rate_pct, bool)
    ):
        raise ValueError("Invalid input type")

    try:
        p = float(principal)
        rate = float(annual_rate_pct)
        n = int(months)
    except (TypeError, ValueError):
        raise ValueError("Invalid numeric input")

    if n != months:
        raise ValueError("months must be a whole number")

    if not (math.isfinite(p) and math.isfinite(rate)):
        raise ValueError("principal and rate must be finite numbers")

    if n <= 0:
        raise ValueError("months must be greater than 0")
    if p < 0:
        raise ValueError("principal must not be negative")
    if rate < 0:
        raise ValueError("annual_rate_pct must not be negative")

    if p == 0:
        return 0.0

    if rate == 0:
        return round(p / n, 2)

    r = rate / 12 / 100

    try:
        growth = (1 + r) ** n
        result = p * r * growth / (growth - 1)
    except OverflowError:
        # Bahut bade n par (1+r)^n overflow ho sakta hai; limit mein EMI -> P * r
        result = p * r

    return round(result, 2)
```

