def inr_words_en(n: int) -> str:
    if n < 0 or n >= 1_000_000_000:
        raise ValueError("n must be in the range 0 <= n < 1,000,000,000")

    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven",
        "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety"
    ]

    def below_100(num: int) -> str:
        if num < 20:
            return ones[num]
        ten, unit = divmod(num, 10)
        if unit == 0:
            return tens[ten]
        return f"{tens[ten]}-{ones[unit]}"

    def below_1000(num: int) -> str:
        hundred, rest = divmod(num, 100)
        parts = []
        if hundred:
            parts.append(f"{ones[hundred]} hundred")
        if rest:
            parts.append(below_100(rest))
        return " ".join(parts)

    if n == 0:
        return "zero"

    parts = []

    crore, n = divmod(n, 10_000_000)
    lakh, n = divmod(n, 100_000)
    thousand, n = divmod(n, 1_000)

    if crore:
        parts.append(f"{below_100(crore)} crore")
    if lakh:
        parts.append(f"{below_100(lakh)} lakh")
    if thousand:
        parts.append(f"{below_100(thousand)} thousand")
    if n:
        parts.append(below_1000(n))

    return " ".join(parts)
