def pincode_state(pincode: str, table: dict[str, str]) -> str | None:
    if not isinstance(pincode, str):
        return None

    pin = pincode.replace(" ", "")

    # Valid PIN: exactly 6 ASCII digits, not starting with '0'
    if len(pin) != 6 or pin[0] == "0":
        return None
    if any(ch not in "0123456789" for ch in pin):
        return None

    # Longest matching prefix wins
    for length in range(len(pin), -1, -1):
        prefix = pin[:length]
        if prefix in table:
            return table[prefix]

    return None
