import re

_WL_CODES = {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}
_NUM_RE = re.compile(r"[0-9]+")
_COACH_RE = re.compile(r"[A-Z0-9]+")
_BERTH_TYPE_RE = re.compile(r"[A-Z]+")


def parse_booking_status(status: str) -> dict | None:
    if not isinstance(status, str):
        return None

    text = status.strip().upper()
    if not text:
        return None

    parts = re.split(r"[/\s]+", text)
    if any(p == "" for p in parts):
        return None

    code = parts[0]

    if code == "CNF":
        if len(parts) not in (3, 4):
            return None
        coach, berth = parts[1], parts[2]
        if not _COACH_RE.fullmatch(coach) or not _NUM_RE.fullmatch(berth):
            return None
        berth_type = None
        if len(parts) == 4:
            berth_type = parts[3]
            if not _BERTH_TYPE_RE.fullmatch(berth_type):
                return None
        return {
            "status": "CNF",
            "coach": coach,
            "berth": int(berth),
            "berth_type": berth_type,
        }

    if code == "RAC":
        if len(parts) != 2 or not _NUM_RE.fullmatch(parts[1]):
            return None
        return {"status": "RAC", "number": int(parts[1])}

    if code in _WL_CODES:
        if len(parts) != 2 or not _NUM_RE.fullmatch(parts[1]):
            return None
        return {"status": "WL", "list": code, "number": int(parts[1])}

    return None
```

