    def round_half_up(value: Fraction) -> int:
        numerator = value.numerator
        denominator = value.denominator

        if numerator >= 0:
            return (2 * numerator + denominator) // (2 * denominator)
        return -((2 * (-numerator) + denominator) // (2 * denominator))

    rate = Fraction(str(rate_pct))

    if supplier_state == place_of_supply:
        cgst = round_half_up(Fraction(taxable_paise) * rate / 200)
        sgst = round_half_up(Fraction(taxable_paise) * rate / 200)
        return {"cgst": cgst, "sgst": sgst, "igst": 0}

    igst = round_half_up(Fraction(taxable_paise) * rate / 100)
    return {"cgst": 0, "sgst": 0, "igst": igst}
