import re
from datetime import datetime, timedelta

_PATTERN = re.compile(
    r"([0-9]{2})/([0-9]{2})/([0-9]{4}) ([0-9]{1,2}):([0-9]{2}) (AM|PM)",
    re.IGNORECASE,
)


def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    m = _PATTERN.fullmatch(s)
    if not m:
        raise ValueError(f"Invalid format: {s!r}")

    day = int(m.group(1))
    month = int(m.group(2))
    year = int(m.group(3))
    hour12 = int(m.group(4))
    minute = int(m.group(5))
    meridiem = m.group(6).upper()

    if not 1 <= hour12 <= 12:
        raise ValueError(f"Invalid hour: {hour12}")
    if not 0 <= minute <= 59:
        raise ValueError(f"Invalid minute: {minute}")

    hour24 = hour12 % 12  # 12 -> 0
    if meridiem == "PM":
        hour24 += 12

    try:
        local = datetime(year, month, day, hour24, minute)
        utc = local - timedelta(hours=5, minutes=30)
    except (ValueError, OverflowError) as e:
        raise ValueError(f"Invalid date/time: {s!r}") from e

    return (
        f"{utc.year:04d}-{utc.month:02d}-{utc.day:02d}"
        f"T{utc.hour:02d}:{utc.minute:02d}:00Z"
    )
