def card_info(number: str) -> tuple[str, bool] | None:
    if not isinstance(number, str):
        return None

    s = number.replace(" ", "").replace("-", "")

    # Only ASCII digits 0-9, length 12-19
    if not (12 <= len(s) <= 19) or any(c not in "0123456789" for c in s):
        return None

    # Network detection
    first2 = int(s[:2])
    first4 = int(s[:4])

    if s[:2] in ("34", "37"):
        network = "Amex"
    elif s[0] == "4":
        network = "Visa"
    elif 51 <= first2 <= 55 or 2221 <= first4 <= 2720:
        network = "Mastercard"
    elif s[:2] in ("60", "65", "81", "82") or s[:3] == "508":
        network = "RuPay"
    else:
        network = "Unknown"

    # Luhn check
    total = 0
    for i, ch in enumerate(reversed(s)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    luhn_ok = total % 10 == 0

    return (network, luhn_ok)
