from decimal import Decimal, ROUND_HALF_UP, localcontext


def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    if months <= 0:
        raise ValueError("months must be greater than 0")
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if annual_rate_pct < 0:
        raise ValueError("annual_rate_pct must be non-negative")

    with localcontext() as ctx:
        ctx.prec = 50

        p = Decimal(principal)
        rate = Decimal(str(annual_rate_pct))

        if rate == 0:
            amount = p / Decimal(months)
        else:
            r = rate / Decimal(12) / Decimal(100)
            factor = (Decimal(1) + r) ** months
            amount = p * r * factor / (factor - Decimal(1))

        return float(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
