import re
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

def parse_indian_amount(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    # Step 1: Strip whitespace
    s = s.strip()

    # Step 2: Remove a leading currency marker if present (case-insensitive)
    lower_s = s.lower()
    for marker in ['₹', 'inr', 'rs.', 'rs']:
        if lower_s.startswith(marker):
            s = s[len(marker):]
            break

    # Step 3: Remove commas and spaces
    s = s.replace(',', '').replace(' ', '')

    # Step 4: Extract the number and the optional unit
    # Matches an optional sign, digits with an optional decimal, and an alphabetic unit
    match = re.fullmatch(r'^([-+]?(?:\d+\.?\d*|\.\d+))([a-zA-Z]*)$', s)
    if not match:
        raise ValueError("Cannot parse amount: text does not match expected format")

    num_str, unit_str = match.groups()
    unit_str = unit_str.lower()

    # Step 5: Map unit to its numeric multiplier
    if unit_str in ['crore', 'crores', 'cr']:
        multiplier = Decimal('10000000')
    elif unit_str in ['lakh', 'lakhs', 'lac', 'lacs', 'l']:
        multiplier = Decimal('100000')
    elif unit_str in ['k', 'thousand']:
        multiplier = Decimal('1000')
    elif unit_str == '':
        multiplier = Decimal('1')
    else:
        raise ValueError(f"Cannot parse amount: unknown unit '{unit_str}'")

    # Step 6: Multiply and round to nearest rupee (exact halves up)
    try:
        num = Decimal(num_str)
    except InvalidOperation:
        raise ValueError("Cannot parse amount: invalid number format")

    total = num * multiplier
    rounded_total = total.to_integral_value(rounding=ROUND_HALF_UP)

    return int(rounded_total)
