def is_valid_upi_id(vpa: str) -> bool:
    if not isinstance(vpa, str):
        return False

    vpa = vpa.strip()

    if vpa.count("@") != 1:
        return False

    local, handle = vpa.split("@")

    if not (2 <= len(local) <= 64):
        return False

    if not (3 <= len(handle) <= 32):
        return False

    if not (local[0].isalnum() and local[-1].isalnum()):
        return False

    if ".." in local:
        return False

    allowed_local_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
    if any(ch not in allowed_local_chars for ch in local):
        return False

    if not handle[0].isalpha():
        return False

    if not handle.isalnum():
        return False

    return True
