import re

_MOBILE_RE = re.compile(r"[6-9][0-9]{9}")
_DIGITS_RE = re.compile(r"[0-9]+")


def normalize_mobile(s: str) -> str | None:
    if not isinstance(s, str):
        return None

    # Remove spaces, hyphens, dots and parentheses
    t = re.sub(r"[ \-.()]", "", s)

    # Strip exactly one country/trunk prefix
    if t.startswith("+91"):
        t = t[3:]
    elif t.startswith("0091"):
        t = t[4:]
    elif t.startswith("91") and len(t) == 12 and _DIGITS_RE.fullmatch(t):
        t = t[2:]
    elif t.startswith("0") and len(t) == 11 and _DIGITS_RE.fullmatch(t):
        t = t[1:]

    if _MOBILE_RE.fullmatch(t):
        return "+91" + t
    return None
