from decimal import Decimal, ROUND_HALF_UP


def emi(principal: int, annual_rate_pct: float, months: int) -> float:
    if months <= 0 or principal < 0 or annual_rate_pct < 0:
        raise ValueError("months must be > 0, principal must be >= 0, and rate must be >= 0")

    p = Decimal(principal)
    n = months

    if annual_rate_pct == 0:
        result = p / Decimal(n)
    else:
        r = Decimal(str(annual_rate_pct)) / Decimal(12) / Decimal(100)
        factor = (Decimal(1) + r) ** n
        result = p * r * factor / (factor - Decimal(1))

    return float(result.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
