import re

_STATES = {
    "AN", "AP", "AR", "AS", "BR", "CH", "CG", "DD", "DL", "GA", "GJ", "HP",
    "HR", "JH", "JK", "KA", "KL", "LA", "LD", "MH", "ML", "MN", "MP", "MZ",
    "NL", "OD", "PB", "PY", "RJ", "SK", "TN", "TR", "TS", "UK", "UP", "WB",
}

_REGULAR_RE = re.compile(r"([A-Z]{2})([0-9]{1,2})([A-Z]{1,3})([0-9]{1,4})")
_BH_RE = re.compile(r"([0-9]{2})BH([0-9]{4})([A-Z]{1,2})")


def parse_vehicle_reg(plate: str) -> dict | None:
    if not isinstance(plate, str) or not plate.isascii():
        return None

    cleaned = plate.upper().replace(" ", "").replace("-", "")

    m = _BH_RE.fullmatch(cleaned)
    if m:
        yy, number, series = m.groups()
        return {
            "type": "BH",
            "year": 2000 + int(yy),
            "number": number,
            "series": series,
        }

    m = _REGULAR_RE.fullmatch(cleaned)
    if m:
        state, rto, series, number = m.groups()
        if state not in _STATES:
            return None
        return {
            "type": "regular",
            "state": state,
            "rto": rto.zfill(2),
            "series": series,
            "number": number.zfill(4),
        }

    return None
