            return None

        return {
            "status": "RAC",
            "number": int(number_text),
        }

    waitlist_codes = {"WL", "GNWL", "RLWL", "PQWL", "TQWL"}
    if parts[0] in waitlist_codes and len(parts) == 2:
        number_text = parts[1]

        if not number_text.isdigit():
            return None

        return {
            "status": "WL",
            "list": parts[0],
            "number": int(number_text),
