import re
from datetime import datetime, timedelta, timezone


def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("invalid input")

    match = re.fullmatch(
        r"(\d{2})/(\d{2})/(\d{4}) (\d{1,2}):(\d{2}) ([AaPp][Mm])",
        s,
    )
    if not match:
        raise ValueError("invalid input")

    day_s, month_s, year_s, hour_s, minute_s, meridiem = match.groups()

    try:
        day = int(day_s)
        month = int(month_s)
        year = int(year_s)
        hour = int(hour_s)
        minute = int(minute_s)

        if not (1 <= hour <= 12) or not (0 <= minute <= 59):
            raise ValueError

        if meridiem.lower() == "am":
            hour_24 = 0 if hour == 12 else hour
        else:
            hour_24 = 12 if hour == 12 else hour + 12

        ist = timezone(timedelta(hours=5, minutes=30))
        local_dt = datetime(year, month, day, hour_24, minute, 0, tzinfo=ist)
        utc_dt = local_dt.astimezone(timezone.utc)

    except (ValueError, OverflowError):
        raise ValueError("invalid input")

    return utc_dt.strftime("%Y-%m-%dT%H:%M:00Z")
