    r"^(\d{2})/(\d{2})/(\d{4}) ([1-9]|1[0-2]):([0-5]\d) ([AP]M)$",
    re.IGNORECASE,
)

def ist_to_utc(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("invalid datetime string")

    match = _PATTERN.fullmatch(s)
    if not match:
        raise ValueError("invalid datetime string")

    day_s, month_s, year_s, hour_s, minute_s, ampm = match.groups()

    day = int(day_s)
    month = int(month_s)
    year = int(year_s)
    hour = int(hour_s)
    minute = int(minute_s)

    ampm = ampm.upper()
    if ampm == "AM":
        if hour == 12:
            hour = 0
    else:
        if hour != 12:
            hour += 12

    try:
        local_dt = datetime(year, month, day, hour, minute, 0, tzinfo=_IST)
        utc_dt = local_dt.astimezone(timezone.utc)
    except (ValueError, OverflowError) as exc:
        raise ValueError("invalid datetime string") from exc

    return utc_dt.strftime("%Y-%m-%dT%H:%M:00Z")
