def normalize_mobile(s: str) -> str | None:
    cleaned = s.translate(str.maketrans("", "", " -()."))

    if cleaned.startswith("+91"):
        number = cleaned[3:]
    elif cleaned.startswith("0091"):
        number = cleaned[4:]
    elif len(cleaned) == 12 and cleaned.startswith("91") and all("0" <= c <= "9" for c in cleaned):
        number = cleaned[2:]
    elif len(cleaned) == 11 and cleaned.startswith("0") and all("0" <= c <= "9" for c in cleaned):
        number = cleaned[1:]
    else:
        number = cleaned

    if (
        len(number) == 10
        and number[0] in "6789"
        and all("0" <= c <= "9" for c in number)
    ):
        return "+91" + number

    return None
