from decimal import Decimal, ROUND_HALF_UP


def epf_contribution(basic_da: int) -> dict:
    if basic_da is None or basic_da < 0:
        raise ValueError("basic_da must be a non-negative amount")

    def _round_half_up(value: Decimal) -> int:
        return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    # Use Decimal(str(...)) so ints, and floats/Decimals if passed, are handled exactly
    amount = Decimal(str(basic_da))
    wage_cap = Decimal(15000)
    eps_wage = min(amount, wage_cap)

    employee = _round_half_up(amount * Decimal("0.12"))
    employer_eps = _round_half_up(eps_wage * Decimal("0.0833"))
    employer_epf = employee - employer_eps

    return {
        "employee": employee,
        "employer_eps": employer_eps,
        "employer_epf": employer_epf,
    }
