from decimal import Decimal, ROUND_HALF_UP


def gst_invoice_total(items: list[tuple[int, int, float]], intra_state: bool) -> dict:
    def round_paisa(amount: Decimal) -> int:
        return int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

    taxable = 0
    by_rate: dict[Decimal, int] = {}

    for quantity, unit_price_paise, gst_rate_pct in items:
        line_taxable = quantity * unit_price_paise
        taxable += line_taxable

        rate = Decimal(str(gst_rate_pct))
        by_rate[rate] = by_rate.get(rate, 0) + line_taxable

    cgst = 0
    sgst = 0
    igst = 0

    for rate, group_taxable in by_rate.items():
        if intra_state:
            tax = round_paisa(Decimal(group_taxable) * rate / Decimal("200"))
            cgst += tax
            sgst += tax
        else:
            tax = round_paisa(Decimal(group_taxable) * rate / Decimal("100"))
            igst += tax

    total_before_rounding = taxable + cgst + sgst + igst

    grand_total = int(
        (Decimal(total_before_rounding) / Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        * Decimal("100")
    )
    round_off = grand_total - total_before_rounding

    return {
        "taxable": taxable,
        "cgst": cgst,
        "sgst": sgst,
        "igst": igst,
        "round_off": round_off,
        "grand_total": grand_total,
    }
