import re


def parse_indian_amount(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("amount must be a string")

    text = s.strip()

    lower = text.lower()
    for marker in ("₹", "rs.", "rs", "inr"):
        if lower.startswith(marker):
            text = text[len(marker):]
            break

    text = text.replace(",", "").replace(" ", "")

    match = re.fullmatch(
        r"(\d+(?:\.\d*)?|\.\d+)(crores?|cr|lakhs?|lacs?|l|k|thousand)?",
        text,
        flags=re.IGNORECASE,
    )
    if not match:
        raise ValueError(f"cannot parse amount: {s!r}")

    number_text, unit = match.groups()

    if "." in number_text:
        whole, frac = number_text.split(".", 1)
        digits = (whole or "0") + frac
        numerator = int(digits)
        denominator = 10 ** len(frac)
    else:
        numerator = int(number_text)
        denominator = 1

    unit = unit.lower() if unit else ""

    if unit in ("crore", "crores", "cr"):
        multiplier = 10_000_000
    elif unit in ("lakh", "lakhs", "lac", "lacs", "l"):
        multiplier = 100_000
    elif unit in ("k", "thousand"):
        multiplier = 1_000
    else:
        multiplier = 1

    total = numerator * multiplier
    rupees, remainder = divmod(total, denominator)

    if remainder * 2 >= denominator:
        rupees += 1

    return rupees
```

