def parse_indian_date(s: str) -> datetime.date:
    pattern = re.compile(
        r"^\s*([0-9]{1,2})(?:[\/\-.]|\s+)([A-Za-z]{3,9}|[0-9]{1,2})(?:[\/\-.]|\s+)([0-9]{2}|[0-9]{4})\s*$"
    )

    match = pattern.fullmatch(s)
    if not match:
        raise ValueError("Invalid date format")

    day_part, month_part, year_part = match.groups()

    day = int(day_part)

    if month_part.isdigit():
        month = int(month_part)
    else:
        month_lookup = {}

        for i in range(1, 13):
            month_lookup[calendar.month_abbr[i].lower()] = i
            month_lookup[calendar.month_name[i].lower()] = i

        month_key = month_part.lower()
        if month_key not in month_lookup:
            raise ValueError("Invalid month")

        month = month_lookup[month_key]

    if len(year_part) == 2:
        year = 2000 + int(year_part)
    else:
        year = int(year_part)

    try:
        return datetime.date(year, month, day)
    except ValueError as exc:
        raise ValueError("Invalid date") from exc
