import datetime
import calendar
import re


def parse_indian_date(s: str) -> datetime.date:
    if not isinstance(s, str):
        raise ValueError("Invalid date format")

    parts = re.split(r"[\/\-\.\s]+", s.strip())
    if len(parts) != 3 or any(part == "" for part in parts):
        raise ValueError("Invalid date format")

    day_part, month_part, year_part = parts

    if not re.fullmatch(r"\d{1,2}", day_part):
        raise ValueError("Invalid day")
    day = int(day_part)

    if re.fullmatch(r"\d{1,2}", month_part):
        month = int(month_part)
    elif re.fullmatch(r"[A-Za-z]+", month_part):
        month_map = {}
        for i in range(1, 13):
            month_map[calendar.month_abbr[i].lower()] = i
            month_map[calendar.month_name[i].lower()] = i

        month_key = month_part.lower()
        if month_key not in month_map:
            raise ValueError("Invalid month")
        month = month_map[month_key]
    else:
        raise ValueError("Invalid month")

    if not re.fullmatch(r"\d{2}|\d{4}", year_part):
        raise ValueError("Invalid year")
    year = int(year_part)
    if len(year_part) == 2:
        year += 2000

    try:
        return datetime.date(year, month, day)
    except ValueError as exc:
        raise ValueError("Invalid date") from exc
