import datetime
import re

_MONTHS = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTH_MAP = {}
for _i, _name in enumerate(_MONTHS, start=1):
    _MONTH_MAP[_name] = _i        # முழுப் பெயர்
    _MONTH_MAP[_name[:3]] = _i    # 3-எழுத்துச் சுருக்கம்

_SEP = r"(?:\s*[/.\-]\s*|\s+)"
_DATE_RE = re.compile(
    rf"^(\d{{1,2}}){_SEP}(\d{{1,2}}|[A-Za-z]+){_SEP}(\d{{4}}|\d{{2}})$",
    re.ASCII,
)


def parse_indian_date(s: str) -> datetime.date:
    """Parse a day-first Indian style date string into a datetime.date.

    Accepted formats: D/M/Y with separators '/', '-', '.' or spaces;
    month as number, 3-letter abbreviation or full English name
    (case-insensitive); year as 4 digits or 2 digits (meaning 2000-2099).

    Raises ValueError for an invalid format or an invalid calendar date.
    """
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")

    m = _DATE_RE.match(s.strip())
    if not m:
        raise ValueError(f"Invalid date format: {s!r}")

    day_s, month_s, year_s = m.groups()

    day = int(day_s)

    if month_s.isdigit():
        month = int(month_s)
    else:
        month = _MONTH_MAP.get(month_s.lower())
        if month is None:
            raise ValueError(f"Invalid month name: {month_s!r}")

    year = int(year_s)
    if len(year_s) == 2:
        year += 2000

    try:
        return datetime.date(year, month, day)
    except ValueError as e:
        raise ValueError(f"Invalid date: {s!r} ({e})") from None
