    _MONTH_MAP[_name] = _i
    _MONTH_MAP[_name[:3]] = _i

_SEP = r"(?:\s*[/\-.]\s*|\s+)"
_PATTERN = re.compile(
    r"^(?P<d>[0-9]{1,2})"
    r"(?P<s1>" + _SEP + r")"
    r"(?P<m>[0-9]{1,2}|[A-Za-z]+)"
    r"(?P<s2>" + _SEP + r")"
    r"(?P<y>[0-9]{4}|[0-9]{2})$"
)


def parse_indian_date(s: str) -> datetime.date:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    text = s.strip()
    match = _PATTERN.match(text)
    if not match:
        raise ValueError(f"Invalid date format: {s!r}")

    # Both separators must be of the same kind (same punctuation, or both spaces)
    if match.group("s1").strip() != match.group("s2").strip():
        raise ValueError(f"Inconsistent separators in date: {s!r}")

    day = int(match.group("d"))

    month_str = match.group("m")
    if month_str.isdigit():
        month = int(month_str)
    else:
        month = _MONTH_MAP.get(month_str.lower())
        if month is None:
            raise ValueError(f"Invalid month name: {month_str!r}")

    year_str = match.group("y")
    year = int(year_str)
    if len(year_str) == 2:
        year += 2000

    try:
        return datetime.date(year, month, day)
    except ValueError as exc:
        raise ValueError(f"Invalid date: {s!r}") from exc
