import datetime
import re

_MONTHS = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]

_MONTH_MAP = {}
for _i, _name in enumerate(_MONTHS, start=1):
    _MONTH_MAP[_name] = _i
    _MONTH_MAP[_name[:3]] = _i

_PATTERN = re.compile(
    r"([0-9]{1,2})"
    r"([/.\-]|[ \t]+)"
    r"([A-Za-z]+|[0-9]{1,2})"
    r"([/.\-]|[ \t]+)"
    r"([0-9]{4}|[0-9]{2})"
)


def parse_indian_date(s: str) -> datetime.date:
    if not isinstance(s, str):
        raise ValueError("Date must be a string")

    text = s.strip()
    m = _PATTERN.fullmatch(text)
    if not m:
        raise ValueError(f"Invalid date format: {s!r}")

    day_s, sep1, month_s, sep2, year_s = m.groups()

    # Both separators must be of the same kind (whitespace runs count as the same)
    if sep1.isspace() or sep2.isspace():
        if not (sep1.isspace() and sep2.isspace()):
            raise ValueError(f"Inconsistent separators in date: {s!r}")
    elif sep1 != sep2:
        raise ValueError(f"Inconsistent separators in date: {s!r}")

    if month_s.isdigit():
        month = int(month_s)
    else:
        month = _MONTH_MAP.get(month_s.lower())
        if month is None:
            raise ValueError(f"Invalid month: {month_s!r}")

    year = int(year_s)
    if len(year_s) == 2:
        year += 2000

    day = int(day_s)

    try:
        return datetime.date(year, month, day)
    except ValueError as e:
        raise ValueError(f"Invalid date: {s!r} ({e})") from None
