from urllib.parse import quote


def upi_pay_link(vpa: str, name: str, amount_paise: int, note: str | None = None) -> str:
    if isinstance(amount_paise, bool) or not isinstance(amount_paise, int):
        raise ValueError("amount_paise must be an integer")
    if amount_paise <= 0:
        raise ValueError("amount_paise must be greater than 0")

    rupees, paise = divmod(amount_paise, 100)
    amount = f"{rupees}.{paise:02d}"

    def enc(value: str) -> str:
        return quote(value, safe="@")

    link = (
        f"upi://pay?pa={enc(vpa)}"
        f"&pn={enc(name)}"
        f"&am={enc(amount)}"
        f"&cu=INR"
    )

    if note:
        link += f"&tn={enc(note)}"

    return link
