            "Seventy", "Eighty", "Ninety"]

    def below_100(n):
        if n < 20:
            return ones[n]
        t, o = divmod(n, 10)
        return tens[t] if o == 0 else tens[t] + "-" + ones[o]

    def below_1000(n):
        h, r = divmod(n, 100)
        parts = []
        if h:
            parts.append(ones[h] + " Hundred")
        if r:
            parts.append(below_100(r))
        return " ".join(parts)

    def number_words(n):
        if n == 0:
            return "Zero"
        parts = []
        crore, n = divmod(n, 10_000_000)
        lakh, n = divmod(n, 100_000)
