        raise ValueError("rupees part must be less than 1,000,000,000")

    ones = ["Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven",
            "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen",
            "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen",
            "Nineteen"]
    tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty",
            "Seventy", "Eighty", "Ninety"]

    def below_100(n: int) -> str:
        if n < 20:
            return ones[n]
        t, o = divmod(n, 10)
        return tens[t] if o == 0 else f"{tens[t]}-{ones[o]}"

    def words(n: int) -> str:
        if n == 0:
            return "Zero"
        parts = []
        crore = n // 10_000_000
        lakh = (n // 100_000) % 100
        thousand = (n // 1_000) % 100
        hundred = (n // 100) % 10
        rest = n % 100
        if crore:
            parts.append(f"{below_100(crore)} Crore")
        if lakh:
            parts.append(f"{below_100(lakh)} Lakh")
        if thousand:
            parts.append(f"{below_100(thousand)} Thousand")
        if hundred:
            parts.append(f"{ones[hundred]} Hundred")
        if rest:
            parts.append(below_100(rest))
        return " ".join(parts)

    result = f"Rupees {words(rupees)}"
    if ps:
        result += f" and {words(ps)} Paise"
    return result + " Only"
