            parts.append(head[-2:])
            head = head[:-2]
        if head:
            parts.append(head)
        return ",".join(reversed(parts)) + "," + tail

    if a >= CRORE:
        return sign + compact(a, CRORE, "Cr")
    if a >= LAKH:
        return sign + compact(a, LAKH, "L")
    return sign + indian_group(a)
