        parts = []
        while len(rest) > 2:
            parts.append(rest[-2:])
            rest = rest[:-2]
        if rest:
            parts.append(rest)
        return ",".join(reversed(parts)) + "," + last_three

    def rounded_compact_value(n: int, divisor: int) -> str:
        scaled, remainder = divmod(n * 100, divisor)
        if remainder * 2 >= divisor:
            scaled += 1

        whole, cents = divmod(scaled, 100)
        if cents == 0:
            return str(whole)
        if cents % 10 == 0:
            return f"{whole}.{cents // 10}"
        return f"{whole}.{cents:02d}"

    sign = "-" if rupees < 0 else ""
    amount = abs(rupees)

    if amount >= 1_00_00_000:
        return sign + rounded_compact_value(amount, 1_00_00_000) + " Cr"
    if amount >= 1_00_000:
        return sign + rounded_compact_value(amount, 1_00_000) + " L"
    return sign + indian_group(amount)
