def cheque_amount_words(paise: int) -> str:
    ONES = [
        "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
        "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen",
        "Sixteen", "Seventeen", "Eighteen", "Nineteen"
    ]
    TENS = [
        "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"
    ]

    def two_digits(n: int) -> str:
        if n == 0:
            return ""
        if 1 <= n <= 19:
            return ONES[n]
        if n >= 20:
            if n % 10 == 0:
                return TENS[n // 10]
            else:
                return TENS[n // 10] + "-" + ONES[n % 10]
        return ""

    def three_digits(n: int) -> str:
        res = []
        if n >= 100:
            res.append(ONES[n // 100] + " Hundred")
        rem = n % 100
        if rem > 0:
            res.append(two_digits(rem))
        return " ".join(res)

    def number_to_words(n: int) -> str:
        if n == 0:
            return "Zero"
        res = []
        if n >= 10000000:
            crore = n // 10000000
            res.append(two_digits(crore) + " Crore")
            n %= 10000000
        if n >= 100000:
            lakh = n // 100000
            res.append(two_digits(lakh) + " Lakh")
            n %= 100000
        if n >= 1000:
            thousand = n // 1000
            res.append(two_digits(thousand) + " Thousand")
            n %= 1000
        if n > 0:
            res.append(three_digits(n))
        return " ".join(res)

    rupees_part = paise // 100
    paise_part = paise % 100

    rupee_words = number_to_words(rupees_part)

    if paise_part == 0:
        return f"Rupees {rupee_words} Only"
    else:
        paise_words = number_to_words(paise_part)
        return f"Rupees {rupee_words} and {paise_words} Paise Only"
