import decimal

def format_compact_inr(rupees: int) -> str:
    if rupees == 0:
        return "0"

    is_negative = rupees < 0
    abs_val = abs(rupees)

    if abs_val >= 10_00_00_00:
        d = decimal.Decimal(abs_val) / decimal.Decimal(10_00_00_00)
        rounded = d.quantize(decimal.Decimal('0.01'), rounding=decimal.ROUND_HALF_UP)
        s = str(rounded)
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        res = s + " Cr"
    elif abs_val >= 1_00_000:
        d = decimal.Decimal(abs_val) / decimal.Decimal(1_00_000)
        rounded = d.quantize(decimal.Decimal('0.01'), rounding=decimal.ROUND_HALF_UP)
        s = str(rounded)
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        res = s + " L"
    else:
        s = str(abs_val)
        if len(s) > 3:
            last_3 = s[-3:]
            rest = s[:-3]
            chunks = []
            while len(rest) > 2:
                chunks.append(rest[-2:])
                rest = rest[:-2]
            if rest:
                chunks.append(rest)
            chunks.reverse()
            res = ",".join(chunks) + "," + last_3
        else:
            res = s

    if is_negative:
        res = "-" + res

    return res
